        tr.push({x: [xv2, xc2], y: [ev, ec], xaxis: xa, yaxis: ya, mode: 'markers', marker: {size: 10, color: BG, line: {color: INK, width: 2.2}}, showlegend: false,
          customdata: ['VBM', 'CBM'], hovertemplate: '%{customdata}: E = %{y:.4f} eV<br>k = %{x:.4f} ' + PB.kunit + '<extra></extra>'});
