# ==================================================================================================
# 3. INDEPENDENT AUDIT
# ==================================================================================================
BOHR = 0.529177210903


def au_canon(lbl):
    t = lbl.strip().strip("'").replace('$', '').replace('\\', '')
    return 'G' if t.upper() in ('G', 'GAMMA', 'Γ') else t.upper()


def au_read_summary(d):
    out = {}
    for l in open(os.path.join(d, 'summary.txt')):
        if ':' in l:
            k, v = l.split(':', 1)
            out[k.strip()] = v.strip()
    return out


def au_read_bands(fname):
    """SIESTA .bands: E_F, k (Bohr^-1), E[k, spin, band] (eV), node list"""
    L = open(fname).read().split('\n')
    ef = float(L[0].split()[0])
    nb, ns, nk = map(int, L[3].split())
    vals = ' '.join(L[4:]).split()
    a = np.array(vals[:nk * (1 + nb * ns)], float).reshape(nk, 1 + nb * ns)
    k, E = a[:, 0], a[:, 1:].reshape(nk, ns, nb)
    rest = vals[nk * (1 + nb * ns):]
    nodes = []
    if rest:
        n = int(rest[0])
        nl = [(float(m.group(1)), m.group(2).strip()) for m in
              re.finditer(r"^\s*([-+0-9.EeDd]+)\s+'([^']*)'\s*$", '\n'.join(L), re.M)]
        nodes = nl[-n:] if len(nl) >= n else []
    return ef, k, E, nodes


def au_read_path(d):
    f = os.path.join(d, 'path.dat')
    hdr = [l for l in open(f) if l.startswith('#')]
    nspin, nb = map(int, re.findall(r'nspin (\d+) nbands (\d+)', hdr[0])[0])
    nodes = [(float(l.split()[2]), l.split()[3] if len(l.split()) > 3 else '') for l in hdr if l.split()[1] == 'node']
    a = np.atleast_2d(np.loadtxt(f))
    return a[:, 0], a[:, 4:4 + nspin * nb].reshape(len(a), nspin, nb), nodes, nspin, nb



def canon_names(names, d, S):
    """independent copy of the shell-name rule: older engines wrote "C-s", "C-pxy", "C-pz"; they are the shells
    (C, l) and get SIESTA's n from <label>.ORB_INDX when unique -> "C-2s", "C-2p" (duplicates are summed by the checks)"""
    lnum = {'s': 0, 'p': 1, 'pxy': 1, 'pz': 1, 'd': 2, 'f': 3}
    if not any((nm[:-3] if nm.endswith(('_up', '_dn')) else nm).rsplit('-', 1)[-1] in lnum for nm in names if '-' in nm):
        return list(names)
    nmap = {}
    try:
        top = os.path.dirname(os.path.abspath(d))
        f = os.path.join(top, S.get('fdf_dir', '.'), S.get('system_label', '') + '.ORB_INDX')
        L = open(f).read().split('\n'); nou = int(L[0].split()[0])
        for l in L[3:3 + nou]:
            w = l.split()
            if len(w) >= 9:
                nmap.setdefault((w[3], int(w[6])), set()).add(int(w[5]))
    except Exception:
        pass
    out = []
    for nm in names:
        suf = nm[-3:] if nm.endswith(('_up', '_dn')) else ''
        base = nm[:-3] if suf else nm
        if '-' in base and base.rsplit('-', 1)[1] in lnum:
            sp, c = base.rsplit('-', 1); l = lnum[c]; ns_ = nmap.get((sp, l), set())
            base = f'{sp}-{min(ns_)}{"spdf"[l]}' if len(ns_) == 1 else f'{sp}-{"spdf"[l]}'
        out.append(base + suf)
    return out


def spin_identical(d, S):
    """the two collinear spin channels are the same within 2 meV on the path (engine flag, or measured here for
    folders written by an older engine)"""
    if int(S.get('nspin', 1)) != 2 or int(S.get('soc', 0)) > 0:
        return False
    if S.get('spin_degenerate', '0') == '1':
        return True
    try:
        h = open(os.path.join(d, 'path.dat')).readline().split(); nb = int(h[h.index('nbands') + 1])
        A = np.atleast_2d(np.loadtxt(os.path.join(d, 'path.dat')))
        return float(np.abs(A[:, 4:4 + nb] - A[:, 4 + nb:4 + 2 * nb]).max()) < 2e-3
    except Exception:
        return False

def haveDOS_a(d):
    return os.path.exists(os.path.join(d, 'dos.dat'))


def read_path_sz(d, nk):
    """spin-orbit: spin character <sz> of the path states from path_proj.dat ([k, band - lo]), lo; or None"""
    f = os.path.join(d, 'path_proj.dat')
    if not os.path.exists(f):
        return None, 0
    h = open(f).readline().split()
    g = open(f).readlines()[1].split()[2:]
    ng, lo, hi, ns = int(h[2]), int(h[4]), int(h[6]), int(h[8])
    if not (len(g) % 2 == 0 and all(x.endswith('_up') for x in g[:len(g) // 2])):
        return None, 0
    W = np.loadtxt(f).reshape(nk, ns, hi - lo + 1, ng)[:, 0]
    up, dn = W[..., :ng // 2].sum(-1), W[..., ng // 2:].sum(-1)
    return (up - dn) / np.maximum(up + dn, 1e-9), lo


def bilin(F, B, qx, qy):
    """periodic bilinear value of grid map F[i, j] (i along b1) at Cartesian q (own implementation)"""
    Na, Nb = F.shape
    u, v = np.linalg.solve(np.asarray(B).T, np.array([qx, qy]))
    u, v = u * Na, v * Nb
    i0, j0 = int(np.floor(u)), int(np.floor(v)); fu, fv = u - i0, v - j0
    g = lambda a, b: F[(i0 + a) % Na, (j0 + b) % Nb]
    return (1 - fu) * (1 - fv) * g(0, 0) + fu * (1 - fv) * g(1, 0) + (1 - fu) * fv * g(0, 1) + fu * fv * g(1, 1)


class Audit:
    def __init__(self, d):
        self.d = d.rstrip('/')
        self.rows = []
        self.nexp = 28

    def add(self, cid, status, what, value, note=''):
        self.rows.append(dict(id=cid, status=status, check=what, value=value, note=note))
        self.bar()

    def bar(self, done=False):
        """% bar in the terminal while the audit runs (only when the output is a terminal)"""
        if not sys.stdout.isatty():
            return
        if done:
            print('\r\x1b[2K', end='', flush=True); return
        p = min(99, int(100 * len(self.rows) / max(self.nexp, 1)))
        print(f'\r\x1b[2K  {"independent audit":<25s}: {p:3d} %  [{"#" * (p // 5)}{"." * (20 - p // 5)}]', end='', flush=True)

    def run(self):
        try:
            return self._run()
        finally:
            self.bar(done=True)

    def _run(self):
        d = self.d
        S = au_read_summary(d)
        label = S['system_label']
        top = os.path.dirname(os.path.abspath(d))
        DIM = int(S.get('periodic_dims', 2))
        self.nexp = {0: 16, 1: 37}.get(DIM, 46)
        self.bar()
        if DIM == 0:
            return self.run_0d(d, S, label, top)
        bf = next((f for f in (os.path.join(S.get('fdf_dir', '.'), label + '.bands'),
                               os.path.join(top, label + '.bands')) if os.path.exists(f)), None)
        EF = float(S['E_F_eV'])
        px, PE, pnodes, nsp, nbp = au_read_path(d)
        ax = json.load(open(os.path.join(d, 'figure_axes.json'))) if os.path.exists(
            os.path.join(d, 'figure_axes.json')) else None

        # ---------- A: k axis
        if bf:
            ef_b, kb, Eb, bnodes = au_read_bands(bf)
            if bnodes:
                pn = [(x * BOHR, l) for x, l in pnodes]
                ok_n = len(pn) == len(bnodes)
                dm = max(abs(a[0] - b[0]) for a, b in zip(pn, bnodes)) if ok_n else 9.9
                okl = ok_n and all(not b[1] or au_canon(a[1]) == au_canon(b[1]) for a, b in zip(pn, bnodes))   # blank = unnamed
                self.add('A01', 'PASS' if ok_n and okl and dm < 2e-5 else 'FAIL',
                         'engine path nodes (positions, names) = .bands node list', dm,
                         ', '.join(f'{au_canon(l)} {x:.6f}' for x, l in bnodes))
                if ax:
                    f2b = ax.get('units_factor_to_bohr', 1.0)
                    dn = max(abs(x * f2b - b[0]) for x, b in zip(ax['nodes'], bnodes)) \
                        if len(ax['nodes']) == len(bnodes) else 9.9
                    want = [('Γ' if au_canon(l or m[1]) == 'G' else (l or m[1])) for (_, l), m in zip(bnodes, pn)]
                    lab_ok = [au_canon(t) for t in ax.get('tick_text', [])] == [au_canon(t) for t in want]
                    nonum = not any(re.search(r'\d\.\d', t) for t in ax.get('tick_text', []))
                    self.add('A02', 'PASS' if dn < 2e-5 and lab_ok and nonum and len(ax['drawn_in']) > 0 else 'FAIL',
                             'PNG band axes: ticks at the .bands nodes, names only', dn,
                             f'drawn: {ax.get("tick_text")}; expected: {want}; {len(ax["drawn_in"])} band panels')
                else:
                    self.add('A02', 'FAIL', 'tick positions drawn in the band figures', 0.0, 'figure_axes.json missing')
            else:
                self.add('A01', 'SKIP', 'path nodes vs .bands node list', 0.0, 'no node list in the .bands file')
                self.add('A02', 'SKIP', 'tick values drawn vs .bands nodes', 0.0, 'no node list in the .bands file')
            nk = min(len(kb), len(px))
            dk = np.max(np.abs(px[:nk] * BOHR - kb[:nk])) if nk else 9.9
            self.add('A03', 'PASS' if len(kb) == len(px) and dk < 2e-5 else 'FAIL',
                     'every path point k = .bands k (Bohr^-1)', dk, f'{len(px)} engine / {len(kb)} SIESTA points')
            # ---------- B: energies
            self.add('B01', 'PASS' if abs(ef_b - EF) < 1e-4 else 'FAIL', 'E_F used = E_F in .bands (eV)',
                     abs(ef_b - EF), f'{EF:.5f} eV')
            ns_ = min(nsp, Eb.shape[1]); nb_ = min(nbp, Eb.shape[2])
            A, B = PE[:nk, :ns_, :nb_], Eb[:nk, :ns_, :nb_]
            m = np.abs(B - EF) < 10
            de = float(np.max(np.abs(A - B)[m])) if m.any() else 0.0
            self.add('B02', 'PASS' if de < 1e-3 else 'FAIL', 'path energies = SIESTA .bands within E_F±10 eV (eV)',
                     de, f'{int(m.sum())} eigenvalues compared')
            # every band, also deep semicore and high empty bands (relative limit: SIESTA prints 4-5 digits)
            dr = float(np.max(np.abs(A - B) / np.maximum(1.0, np.abs(B - EF)))) if A.size else 0.0
            self.add('B03', 'PASS' if dr < 1e-3 else 'FAIL', 'path energies = SIESTA .bands, all bands (max |dE| / max(1, |E-E_F|))',
                     dr, f'{A.size} eigenvalues compared')
        else:
            self.add('A01', 'SKIP', 'path nodes vs .bands', 0.0, 'no .bands file')

        # ---------- C: gap and gap type from the full periodic grid (independent of the refinement)
        gtxt = S.get('gap_type', '')
        cap = open(os.path.join(d, 'figures', 'CAPTIONS.md')).read() if os.path.exists(
            os.path.join(d, 'figures', 'CAPTIONS.md')) else ''
        gs = float(S.get('overall_gap_eV', 0))
        bz = os.path.join(d, 'bz_grid.dat')
        if os.path.exists(bz) and gs > 0.02:
            h = open(bz).readline().split()
            Na, Nb, ns_, blo, bhi = int(h[2]), int(h[4]), int(h[6]), int(h[8]), int(h[10])
            G = np.loadtxt(bz)[:, 4:]
            nw = bhi - blo + 1
            G = G.reshape(len(G), ns_, nw)
            vb_max, cb_min, dirg = -1e9, 1e9, 1e9
            for s in range(ns_):
                no = int(S.get(f'spin{s + 1}_nocc', S.get('spin1_nocc')))
                v, c = G[:, s, no - blo], G[:, s, no - blo + 1]
                vb_max, cb_min = max(vb_max, v.max()), min(cb_min, c.min())
                dirg = min(dirg, (c - v).min())
            gg = cb_min - vb_max
            self.add('C01', 'PASS' if -1e-3 <= gg - gs <= max(0.010 * gs, 2e-3) else 'FAIL',
                     'gap: periodic grid (upper bound) vs reported gap (eV; limit 1 %)', gg - gs,
                     f'grid {gg:.4f} eV, reported {gs:.4f} eV (refined off-grid, so grid >= reported)')
            dd = dirg - gg
            exp_type = 'direct' if dd < 0.010 else 'indirect'
            shown = 'direct' if '(direct)' in cap else ('indirect' if '(indirect)' in cap else '?')
            spins_between = 'between' in gtxt
            st = 'PASS' if (spins_between or (exp_type == shown == gtxt) or abs(dd - 0.010) < 0.004) else 'FAIL'
            self.add('C02', st, 'gap type: recomputed from the grid = shown in the figures', dd,
                     f'direct gap - fundamental (grid) = {1000 * dd:.1f} meV -> {exp_type}; figures say {shown}; '
                     f'summary {gtxt}')
        elif os.path.exists(os.path.join(d, 'grid1d.dat')) and gs > 0.02:
            g1 = os.path.join(d, 'grid1d.dat')
            h = open(g1).readline().split()
            ns_, blo, bhi = int(h[4]), int(h[6]), int(h[8])
            nw = bhi - blo + 1
            G = np.loadtxt(g1)[:, 2:].reshape(-1, ns_, nw)
            vb_max, cb_min, dirg = -1e9, 1e9, 1e9
            for s in range(ns_):
                no = int(S.get(f'spin{s + 1}_nocc', S.get('spin1_nocc')))
                v, c = G[:, s, no - blo], G[:, s, no - blo + 1]
                vb_max, cb_min = max(vb_max, v.max()), min(cb_min, c.min())
                dirg = min(dirg, (c - v).min())
            gg = cb_min - vb_max
            self.add('C01', 'PASS' if -1e-3 <= gg - gs <= max(0.010 * gs, 2e-3) else 'FAIL',
                     'gap: 1D periodic grid (upper bound) vs reported gap (eV; limit 1 %)', gg - gs,
                     f'grid {gg:.4f} eV, reported {gs:.4f} eV ({G.shape[0]} k-points)')
            dd = dirg - gg
            exp_type = 'direct' if dd < 0.010 else 'indirect'
            shown = 'direct' if '(direct)' in cap else ('indirect' if '(indirect)' in cap else '?')
            st = 'PASS' if ('between' in gtxt or exp_type == shown == gtxt or abs(dd - 0.010) < 0.004) else 'FAIL'
            self.add('C02', st, 'gap type: recomputed from the 1D grid = shown in the figures', dd,
                     f'direct gap - fundamental (grid) = {1000 * dd:.1f} meV -> {exp_type}; figures say {shown}; '
                     f'summary {gtxt}')
        else:
            self.add('C01', 'SKIP', 'gap from the periodic grid', 0.0, 'metal/semimetal (no gap)')

        # ---------- D: DOS
        D = np.loadtxt(os.path.join(d, 'dos.dat'))
        E = D[:, 0]
        nch = 2 if (int(S['nspin']) == 2 and not spin_identical(d, S)) else 1
        tot = D[:, 1:1 + nch].sum(1) if nch == 2 else D[:, 1]
        if gs > 0.1:
            vb = float(S['spin1_VBM_E_k'].split()[0]); cb = float(S['spin1_CBM_E_k'].split()[0])
            if nch == 2 and 'spin2_VBM_E_k' in S:
                vb = max(vb, float(S['spin2_VBM_E_k'].split()[0])); cb = min(cb, float(S['spin2_CBM_E_k'].split()[0]))
            m = (E > vb + 0.03) & (E < cb - 0.03)
            mx = float(tot[m].max()) if m.any() else 0.0
            self.add('D01', 'PASS' if mx < 1e-6 else 'FAIL', 'DOS is exactly zero inside the gap', mx,
                     f'{m.sum()} energies between VBM {vb:+.3f} and CBM {cb:+.3f} eV')
        if os.path.exists(os.path.join(d, 'pdos.dat')):
            P = np.loadtxt(os.path.join(d, 'pdos.dat'))
            m = np.abs(P[:, 0]) < 3
            ps = P[m, 1:].sum(1)
            t2 = D[:, 1:1 + int(S['nspin'])].sum(1) if S.get('soc', '0') == '0' else D[:, 1]
            r = float(np.abs(ps - t2[m]).sum() / max(np.abs(t2[m]).sum(), 1e-12))
            self.add('D02', 'PASS' if r < 0.010 else 'FAIL', 'sum of PDOS = total DOS (rel. L1, E_F±3 eV; limit 1 %)', r)
        dc = float(S.get('dos_convergence', -1))
        self.add('D03', 'PASS' if 0 <= dc < 0.010 else 'FAIL',
                 'DOS error of the k-grid (Richardson) present and < 1 %', dc,
                 f"N vs N/2 {100 * float(S.get('dos_diff_N_halfN', -0.01)):.2f} %, observed order {float(S.get('dos_error_order', 0)):.2f}")

        # ---------- Q: QPI physics, recomputed independently from the raw grid
        if os.path.exists(bz) and int(S.get('periodic_dims', 2)) >= 2:
            h = open(bz).readline().split()
            Na, Nb, ns_, blo, bhi = int(h[2]), int(h[4]), int(h[6]), int(h[8]), int(h[10])
            G = np.loadtxt(bz)[:, 4:].reshape(Nb, Na, ns_, bhi - blo + 1)
            E0 = float(S.get('qpi_energies', '0.3').split()[0]); eta = 0.03
            A = (eta / np.pi / ((E0 - G) ** 2 + eta ** 2)).sum(-1)               # [j, i, spin]
            # direct (non-FFT) evaluation of J(q) at a few q, vs the FFT autocorrelation
            Fa = np.fft.fft2(A[:, :, 0]); Jf = np.real(np.fft.ifft2(np.abs(Fa) ** 2)) / A[:, :, 0].size
            errs = []
            for (dj, di) in ((0, 0), (1, 0), (0, 3), (Nb // 4, Na // 3)):
                dsum = (A[:, :, 0] * np.roll(np.roll(A[:, :, 0], -dj, 0), -di, 1)).mean()
                errs.append(abs(dsum - Jf[dj, di]) / max(abs(dsum), 1e-12))
            self.add('Q01', 'PASS' if max(errs) < 1e-8 else 'FAIL', 'JDOS by FFT = direct sum over k (4 q points)',
                     max(errs))
            s1 = Jf.sum(); s2 = A[:, :, 0].sum() ** 2 / A[:, :, 0].size
            self.add('Q02', 'PASS' if abs(s1 - s2) / s2 < 1e-10 else 'FAIL', 'JDOS sum rule: sum_q J = (sum_k A)^2 / N',
                     abs(s1 - s2) / s2)
            sym = np.abs(Jf - np.roll(Jf[::-1, ::-1], 1, axis=(0, 1))).max() / max(Jf.max(), 1e-12)
            self.add('Q03', 'PASS' if sym < 1e-10 else 'FAIL', 'JDOS symmetric J(q) = J(-q)', sym)
            dEk = float(np.median(np.abs(np.diff(G, axis=1))))
            self.add('Q04', 'PASS' if dEk < 0.06 else 'WARN', 'k-grid fine enough for the QPI maps (median dE between '
                     'neighbours, eV)', dEk, 'should be below ~2 eta')
        g1 = os.path.join(d, 'grid1d.dat')
        if DIM == 1 and os.path.exists(g1):
            h = open(g1).readline().split()
            a = np.loadtxt(g1)
            N1 = int(h[2]); E = a[:, 2:]
            eta = 0.03; e0 = float(np.median(E[np.abs(E) < 1.0])) if (np.abs(E) < 1.0).any() else 0.0
            A = (eta / np.pi / ((e0 - E) ** 2 + eta ** 2)).sum(1)
            Fa = np.fft.fft(A); J = np.real(np.fft.ifft(Fa * np.conj(Fa))) / N1
            errs = []
            for q in (0, 1, N1 // 7, N1 // 2):
                Jd = np.sum(A * np.roll(A, -q)) / N1
                errs.append(abs(Jd - J[q]) / max(abs(Jd), 1e-300))
            self.add('Q01', 'PASS' if max(errs) < 1e-8 else 'FAIL', '1D JDOS by FFT = direct sum over k (4 q points)',
                     max(errs), f'{N1} k-points, eta {eta} eV, E = {e0:.3f} eV')
            s1, s2 = J.sum(), A.sum() ** 2 / N1
            self.add('Q02', 'PASS' if abs(s1 - s2) / s2 < 1e-10 else 'FAIL', '1D JDOS sum rule: sum_q J = (sum_k A)^2 / N',
                     abs(s1 - s2) / s2)
            sym = float(np.max(np.abs(J - np.roll(J[::-1], 1))) / J.max())
            self.add('Q03', 'PASS' if sym < 1e-10 else 'FAIL', '1D JDOS symmetric J(q) = J(-q)', sym)
            dEk = float(np.median(np.abs(np.diff(E, axis=0))))
            self.add('Q04', 'PASS' if dEk < 0.06 else 'WARN', '1D k-grid fine enough for the QPI maps (median dE, eV)', dEk,
                     'should be below ~2 eta')
        # ---------- E: validation tables
        bad = []
        for fn in ('validation.txt', 'validation_plots.txt'):
            p = os.path.join(d, fn)
            if os.path.exists(p):
                bad += [l.split('|')[1].strip() for l in open(p) if l.startswith('FAIL')]
        self.add('E01', 'PASS' if not bad else 'FAIL', 'no FAIL in the engine / plot validation tables', len(bad),
                 '; '.join(bad))

        # ---------- F: figures
        try:
            from PIL import Image
            main = ['0_validation', '1_bands_dos', '1b_projected_bands', '1e_projected_bands_atoms'] + (
                ['2_bands3d_bz', '6_1d_spectral_qpi', '6c_qpi_analysis', '7_qpi_dispersion', '8_overview'] if DIM == 1 else
                ['2_bands3d_bz', '3_bands3d_zoom', '4_dispersion_mesh', '5_vaspkit_style', '6_cec_qpi',
                 '6c_qpi_analysis', '7_qpi_dispersion', '8_overview'])
            miss, asp, small = [], [], []
            for n in main:
                f = os.path.join(d, 'figures', n + '.png')
                if not os.path.exists(f):
                    miss.append(n); continue
                w, h = Image.open(f).size
                asp.append((n, w / h))
                if max(w, h) < 2400:
                    small.append(n)
            amin, amax = min(a for _, a in asp), max(a for _, a in asp)
            self.add('F01', 'PASS' if not miss else 'FAIL', 'all main figures written (PNG)', len(miss), ', '.join(miss))
            self.add('F02', 'PASS' if 0.80 <= amin and amax <= 1.35 else 'WARN', 'figure width:height within 0.80-1.35',
                     amax, ', '.join(f'{n} {a:.2f}' for n, a in asp))
            self.add('F03', 'PASS' if not small else 'WARN', 'figures >= 2400 px (300 dpi print)', len(small),
                     ', '.join(small))
        except ImportError:
            self.add('F01', 'SKIP', 'figures', 0.0, 'Pillow not installed')

        # ---------- G: interactive page
        html = os.path.join(top, label + '_interactive.html')
        if os.path.exists(html):
            t = open(html, encoding='utf-8').read()
            i = t.index('const D = ') + len('const D = ')
            j = t.index('\n', i)
            Dj = json.loads(t[i:j].rstrip(';'))
            pn = Dj.get('pub', {}).get('nodes')
            if pn and ax:
                f2b = ax.get('units_factor_to_bohr', 1.0)
                ref = [x for x in ax.get('siesta_nodes_bohr', [])] or [x * f2b for x in ax['nodes']]
                dn = max(abs(a[0] * f2b - b) for a, b in zip(pn, ref)) if len(pn) == len(ref) else 9.9
                uok = Dj['pub'].get('kunit') == ax['units']
                self.add('G01', 'PASS' if dn < 2e-5 and uok else 'FAIL',
                         'HTML band axis k values = .bands node list', dn,
                         f'HTML {Dj["pub"].get("kunit")}: ' + ', '.join(f'{x:.3f}' for x, _ in pn))
            else:
                self.add('G01', 'FAIL', 'HTML band axis', 0.0, 'no band data in the page')
            self.add('G02', 'PASS' if 'plotly' in t[:200000].lower() else 'FAIL', 'plotly embedded (works offline)', 0.0)
            qp = Dj.get('qpi')
            if qp:
                import io
                from PIL import Image
                nE = len(qp['E']); nq = qp['n']
                okq = all(isinstance(qp[k], list) and len(qp[k]) == nE for k in ('A', 'J', 'T'))
                sz = set()
                if okq:
                    for k in ('A', 'J', 'T') + (('B',) if qp.get('B') else ()):
                        for ie in (0, nE // 2, nE - 1):
                            sz.add(Image.open(io.BytesIO(base64.b64decode(qp[k][ie]))).size)
                okq = okq and sz == {(nq, nq)}
                self.add('G03', 'PASS' if okq else 'FAIL', 'HTML QPI maps complete, one image per energy and map',
                         float(nE), f'{nE} energies; frame size {sorted(sz)} px')
                self.add('G05', 'PASS' if nq >= 300 else 'WARN', 'HTML QPI resolution >= 300 px (PNG figure: 321 px)',
                         float(nq))
                spin_lab = True                  # spin-conserving / spin-flip maps exist for every system
                pk = qp.get('peaks') or []
                okp = len(pk) == nE and (not spin_lab or (qp.get('Jc') and qp.get('Jf') and len(qp['Jc']) == nE))
                self.add('G08', 'PASS' if okp else 'FAIL', 'HTML QPI: scattering-vector table per energy'
                         + (' + spin-conserving / spin-flip maps' if spin_lab else ''), float(sum(len(x) for x in pk)),
                         f'{sum(1 for x in pk if x)} of {nE} energies with peaks')
            if DIM == 1:
                q1 = Dj.get('q1d')
                ok1 = False; note = 'no 1D QPI data in the page'
                if q1:
                    import io
                    from PIL import Image
                    sz = {k: Image.open(io.BytesIO(base64.b64decode(q1[k]))).size for k in ('A', 'J', 'T')}
                    ok1 = all(w >= 300 and h >= 200 for w, h in sz.values()) and len(q1.get('guides', [])) > 0
                    note = ', '.join(f'{k} {w}x{h}' for k, (w, h) in sz.items()) + f'; {len(q1["guides"])} 2k lines'
                self.add('G03', 'PASS' if ok1 else 'FAIL', 'HTML 1D spectral function / JDOS / T-matrix maps present', 0.0, note)
            fit = 'function fitTab(' in t and 'height:72vh' not in t and 'aspect-ratio:1.2' not in t
            self.add('G06', 'PASS' if fit else 'FAIL', 'HTML panels sized to the browser window (no page scrolling)',
                     0.0)
            self.add('G07', 'PASS' if 'Satish Kumar' in t else 'FAIL', 'author shown in the HTML header', 0.0)
            chs = (Dj.get('pub') or {}).get('chs', [])
            if float(S.get('overall_gap_eV', 0)) > 0.02 and chs:
                self.add('H04', 'PASS' if all(c.get('gap') for c in chs) else 'FAIL', 'HTML band panels carry the gap arrow', 0.0,
                         f'{sum(bool(c.get("gap")) for c in chs)} of {len(chs)} panels')
            spt = os.path.join(d, 'spin_texture.dat')
            if os.path.exists(spt) and os.path.getsize(spt) > 200:
                self.add('H05', 'PASS' if Dj.get('spin') else 'FAIL', 'HTML spin-texture tab present (spin-orbit run)', 0.0,
                         f'{len(Dj.get("spin") or [])} energies')
            self.check_views(d, S, Dj)
            self.page_bands_fat(d, S, Dj)
            self.add('G04', 'PASS' if 'Validation & method' not in t else 'FAIL',
                     'no validation tab in the HTML (validation is in validation_report.txt)', 0.0)
        else:
            self.add('G01', 'FAIL', 'interactive page exists', 0.0, html)
        # ---------- H: things the user sees (labels at panel joins, gap arrow, spin moment, spin texture page)
        joins = (ax or {}).get('joins', [])
        if joins:
            bad = [j['figure'] for j in joins if j.get('first_tick_text', '')]
            self.add('H01', 'PASS' if not bad else 'FAIL', 'no doubled k-label where two band panels touch', float(len(bad)),
                     ', '.join(bad) or f'{len(joins)} joins checked')
        gs = float(S.get('overall_gap_eV', 0))
        arrows = (ax or {}).get('gap_arrows', [])
        if gs > 0.02 and 'between' not in S.get('gap_type', ''):
            if not arrows:
                self.add('H02', 'FAIL', 'band-gap arrow drawn (VBM → CBM)', 0.0, 'gap but no arrow in the band figures')
            else:
                dmax = 0.0; lab = 0.0
                SZp, plo = read_path_sz(d, len(px))
                for r in arrows:
                    sp = int(r['spin'])
                    no = int(S.get(f'spin{sp + 1}_nocc', S.get('spin1_nocc', 0)))
                    if r.get('char') is not None and SZp is not None and 'soc_up_gap_eV' in S:
                        # spin-orbit panel: extrema of the states of that spin character only
                        own = (SZp >= 0) if r['char'] > 0 else (SZp < 0)
                        Eb = PE[:, 0, plo - 1:plo - 1 + SZp.shape[1]] - EF
                        occ = (np.arange(plo, plo + SZp.shape[1]) <= no)[None, :]
                        v = np.where(own & occ, Eb, -np.inf).max(1); c = np.where(own & ~occ, Eb, np.inf).min(1)
                        lab = max(lab, abs(r['gap'] - float(S['soc_' + ('up' if r['char'] > 0 else 'dn') + '_gap_eV'])))
                    elif r.get('overall') and PE.shape[1] == 2 and not spin_identical(d, S):
                        # overall gap of a collinear magnet: VBM / CBM of both spins together
                        no2 = int(S.get('spin2_nocc', no))
                        v = np.maximum(PE[:, 0, no - 1], PE[:, 1, no2 - 1]) - EF
                        c = np.minimum(PE[:, 0, no], PE[:, 1, no2]) - EF
                        lab = max(lab, abs(r['gap'] - gs))
                    else:
                        v = PE[:, sp, no - 1] - EF; c = PE[:, sp, no] - EF
                        if 'spin2_VBM_E_k' not in S or r.get('overall'):
                            lab = max(lab, abs(r['gap'] - gs))
                    dmax = max(dmax, abs(r['E_vbm'] - v.max()), abs(r['E_cbm'] - c.min()))
                ok = dmax < 1e-3 and lab <= max(0.010 * gs, 1e-3)
                self.add('H02', 'PASS' if ok else 'FAIL', 'gap arrow at the path VBM / CBM; value = reported gap (eV)', max(dmax, lab),
                         f'{len(arrows)} arrows; ends within {1000 * dmax:.2f} meV of the band extrema; label {arrows[0]["gap"]:.4f} eV, '
                         f'summary {gs:.4f} eV, type {arrows[0]["type"]}')
        mm = S.get('magnetic_moment_muB')
        if mm is not None and (int(S.get('soc', 0)) > 0 or int(S.get('nspin', 1)) == 2):
            sm = None
            fd = os.path.abspath(os.path.join(top, S.get('fdf_dir', '.')))
            files = [f for f in glob.glob(os.path.join(fd, '*')) if os.path.isfile(f)]   # isfile: skips broken links
            for f in sorted(files, key=os.path.getmtime):
                b = os.path.basename(f)
                if b.startswith('fdf.') or not (b.endswith(('.out', '.log')) or b.startswith(('log', 'out'))):
                    continue
                for l in open(f, errors='ignore'):
                    if 'spin moment:' in l and '=' in l:
                        t = l.split('=', 1)[1]; nums = re.findall(r'[-+]?\d+\.\d+', t)
                        if nums:
                            sm = float(nums[2]) if ('{' in t and len(nums) >= 3) else float(nums[0])
            if sm is None:
                self.add('H03', 'SKIP', 'spin moment vs SIESTA', 0.0, 'no SIESTA output file next to the fdf')
            else:
                dm = abs(float(mm) - sm)
                self.add('H03', 'PASS' if dm <= max(0.010 * abs(sm), 0.02) else 'FAIL',
                         'spin moment: this code = SIESTA output (muB; limit 1 %)', dm, f'{float(mm):.4f} vs {sm:.4f}')
        if haveDOS_a(d) and os.path.exists(os.path.join(d, 'pdos.dat')):
            self.fig1_check(d, S, ax)
        self.label_check(d, S, top, 'pdos.dat')
        self.dos_rows(d, S)
        self.dos_count(d, S)
        self.spin_and_files(d, S, ax, top, label)
        json.dump(self.rows, open(os.path.join(d, 'audit.json'), 'w'), indent=1)
        return self.rows

    def check_views(self, d, S, Dj):
        """G09: the DOS projections of the page (atoms / orbitals / atoms x orbitals, every spin channel, and the
        'both spins' total) are exact regroupings of pdos.dat; the 'both spins' gap = the reported overall gap"""
        pub = Dj.get('pub') or {}
        pf = os.path.join(d, 'pdos.dat')
        if not pub.get('views') or not os.path.exists(pf):
            return
        dec = lambda x: np.frombuffer(base64.b64decode(x), '<f4').astype(float)
        h = [l for l in open(pf) if l.startswith('#')]
        names = canon_names(next(l.split()[2:] for l in h if l.split()[1] == 'groups'), d, S)
        P = np.loadtxt(pf); ns = int(S['nspin']); ng = len(names)
        Pe, Pg = P[:, 0], P[:, 1:].reshape(len(P), ns, ng)
        E = dec(pub['dosE'])
        idx = np.array([int(np.argmin(np.abs(Pe - e))) for e in E])
        soc = int(S.get('soc', 0)) > 0
        chs = pub['chs']
        worst, n = 0.0, 0
        for ic, ch in enumerate(chs):
            if soc and len(chs) == 2:
                cols = [i for i, nm in enumerate(names) if nm.endswith('_up' if ic == 0 else '_dn')]
                ref = Pg[idx][:, 0, cols].sum(1)
            elif len(chs) == 2:
                ref = Pg[idx][:, ic, :].sum(1)
            else:
                f = 2.0 if (ns == 1 and not soc) else 1.0
                ref = Pg[idx][:, 0, :].sum(1) * f if ns == 1 else Pg[idx].sum((1, 2))
            for v, arrs in (ch.get('pdv') or {}).items():
                tot = sum(dec(a) for a in arrs)
                worst = max(worst, float(np.abs(tot - ref).sum() / max(np.abs(ref).sum(), 1e-12))); n += 1
        # the drawn channels add up to the TOTAL DOS of dos.dat (all spins; x2 without spin) -- catches a channel
        # drawn without its spin factor
        Dd = np.loadtxt(os.path.join(d, 'dos.dat'))
        tot_ref = Dd[:, 1:1 + (1 if soc else ns)].sum(1) * (2.0 if (ns == 1 and not soc) else 1.0)
        tot_ref = tot_ref[[int(np.argmin(np.abs(Dd[:, 0] - e))) for e in E]]
        tot_pg = sum(dec(c['tot']) for c in chs)
        rt = float(np.abs(tot_pg - tot_ref).sum() / max(np.abs(tot_ref).sum(), 1e-12))
        # spin channels on the page only when the two spins really differ (collinear runs): no spin selector,
        # no spin legend for unpolarised or spin-degenerate runs
        want = None if soc else (2 if (ns == 2 and not spin_identical(d, S)) else 1)
        okc = want is None or len(chs) == want
        self.add('G10', 'PASS' if (rt <= 1e-3 and okc) else 'FAIL',
                 'page / figure DOS channels add up to the total DOS (all spins); spin channels only for a magnet', rt,
                 f'{len(chs)} channel(s)' + ('' if want is None else f', expected {want} (nspin {ns}, degenerate {S.get("spin_degenerate", "0")})'))
        # G11: every single curve of every view (not only their sum) = the shells of pdos.dat grouped here,
        # independently of the plotting code; labels are "element n l" (Cr 3d), orbital view s / p / d / f only
        def key(nm, v):
            base = nm[:-3] if nm.endswith(('_up', '_dn')) else nm
            sp_, c_ = base.rsplit('-', 1) if '-' in base else (base, '')
            if v == 'atom':
                return sp_
            if v == 'orb':
                return c_.lstrip('0123456789')
            return f'{sp_} {c_}'
        worst1, bad_lab, ncurve = 0.0, [], 0
        for ic, ch in enumerate(chs):
            for vw in pub['views']:
                v = vw['key']
                arrs = (ch.get('pdv') or {}).get(v)
                if arrs is None:
                    continue
                for nmv, arr in zip(vw['names'], arrs):
                    cols = [i for i, nm in enumerate(names) if key(nm, v) == nmv and
                            (not (soc and len(chs) == 2) or nm.endswith('_up' if ic == 0 else '_dn'))]
                    if not cols:
                        bad_lab.append(nmv); continue
                    if soc and len(chs) == 2:
                        r = Pg[idx][:, 0, cols].sum(1)
                    elif len(chs) == 2:
                        r = Pg[idx][:, ic, cols].sum(1)
                    else:
                        f = 2.0 if (ns == 1 and not soc) else 1.0
                        r = Pg[idx][:, 0, cols].sum(1) * f if ns == 1 else Pg[idx][:, :, cols].sum((1, 2))
                        if ns == 2 and S.get('spin_degenerate', '0') == '1':
                            r = Pg[idx][:, 0, cols].sum(1) * 2.0
                    d_ = dec(arr)
                    worst1 = max(worst1, float(np.abs(d_ - r).sum() / max(np.abs(r).sum(), 1e-9 * max(np.abs(ref).sum(), 1.0), 1e-12)))
                    ncurve += 1
        labs = [n for vw in pub['views'] for n in vw['names']]
        okl = not any(x in n for n in labs for x in ('px', 'py', 'pz', 'pxy')) and \
            all(n in ('s', 'p', 'd', 'f', 'all') for vw in pub['views'] if vw['key'] == 'orb' for n in vw['names']) and not bad_lab
        self.add('G11', 'PASS' if (ncurve and worst1 <= 1e-4 and okl) else 'FAIL',
                 'every DOS curve of every view = its shells in pdos.dat; labels "element n l" (e.g. Cr 3d), orbitals s/p/d/f', worst1,
                 f'{ncurve} curves; labels ' + ', '.join(next((vw['names'] for vw in pub['views'] if vw['key'] == 'fine'), []))[:150]
                 + (f'; labels without data: {bad_lab}' if bad_lab else ''))
        spec = list(dict.fromkeys((nm[:-3] if nm.endswith(('_up', '_dn')) else nm).rsplit('-', 1)[0] for nm in names))
        av = next((v for v in pub['views'] if v['key'] == 'atom'), None)
        ok_names = av is not None and av['names'] == spec and pub.get('defview') == 'atom'
        both = pub.get('both')
        okb, note = True, ''
        if both:
            bt = dec(both['tot']); st = sum(dec(c['tot']) for c in chs)
            okb = float(np.abs(bt - st).max()) <= 1e-4 * max(np.abs(st).max(), 1e-12)
            g = float(S.get('overall_gap_eV', 0))
            if g > 0.02:
                okb = okb and both.get('gap') is not None and abs(both['gap'][4] - g) <= max(0.010 * g, 1e-3)
                note = f'; both-spins gap {both["gap"][4] if both.get("gap") else None} vs {g:.4f} eV'
        self.add('G09', 'PASS' if (n and worst <= 1e-4 and ok_names and okb) else 'FAIL',
                 'page DOS projections (atoms/orbitals/both) = regrouped pdos.dat', worst,
                 f'{n} channel x view sums; atoms view (default, names = species) {"ok" if ok_names else "MISSING / WRONG"}' + note)

    def dos_rows(self, d, S):
        """D04: every row of dos.dat is a valid DOS (>= 0) and the shells of pdos.dat add up to it at EVERY energy
        (max |sum - DOS| / max DOS <= 1 %) -- an L1 average would hide a single wrong row"""
        Dd = np.loadtxt(os.path.join(d, 'dos.dat'))
        ns = int(S['nspin']); soc = int(S.get('soc', 0)) > 0
        nsp = 1 if soc else ns
        tot = Dd[:, 1:1 + nsp]
        neg = float(tot.min())
        r = 0.0
        pf = os.path.join(d, 'pdos.dat')
        if os.path.exists(pf):
            P = np.loadtxt(pf); ng = (P.shape[1] - 1) // nsp
            for s in range(nsp):
                ps = P[:, 1 + s * ng:1 + (s + 1) * ng].sum(1)
                r = max(r, float(np.abs(ps - tot[:, s]).max() / max(np.abs(tot[:, s]).max(), 1e-300)))
        tol = -1e-6 * max(float(np.abs(tot).max()), 1.0)
        i0 = int(np.argmin(tot.min(1)))
        self.add('D04', 'PASS' if (neg >= tol and r <= 0.01) else 'FAIL',
                 'dos.dat >= 0 at every energy; shells of pdos.dat add up to it at every energy (limit 1 %)', max(r, -neg),
                 f'min DOS {neg:.3e} /eV at E = {Dd[i0, 0]:.4f} eV; max |sum PDOS - DOS| / max DOS = {r:.2e}; {len(Dd)} rows')

    def dos_count(self, d, S):
        """D05: the number of states in energy windows near E_F, integrated from dos.dat, equals the exact count from
        the band energies on the DOS k-grid (grid1d.dat for wires, bz_grid.dat for layers), computed here with an
        independent implementation of linear segments / triangles. Windows contain only the bands of the grid file."""
        f1, f2 = os.path.join(d, 'grid1d.dat'), os.path.join(d, 'bz_grid.dat')
        Dd = np.loadtxt(os.path.join(d, 'dos.dat')); de = Dd[1, 0] - Dd[0, 0]
        if os.path.exists(f1):
            h = open(f1).readline().split(); ns = int(h[4]); nb = int(h[8]) - int(h[6]) + 1
            E = np.loadtxt(f1)[:, 2:2 + ns * nb].reshape(-1, ns, nb); dim = 1
        elif os.path.exists(f2) and int(S.get('periodic_dims', 2)) == 2:
            h = open(f2).readline().split(); Na, Nb, ns = int(h[2]), int(h[4]), int(h[6]); nb = int(h[10]) - int(h[8]) + 1
            E = np.loadtxt(f2)[:, 4:4 + ns * nb].reshape(Nb, Na, ns, nb); dim = 2
        else:
            self.add('D05', 'SKIP', 'states counted from dos.dat = exact count on the k-grid', 0.0, '3D: the DOS grid is not written (the plane file is a b1-b2 section); electron count checked by the engine')
            return
        nsd = Dd.shape[1] - 1
        worst, notes, wnote = 0.0, [], ''
        for s in range(min(ns, nsd)):
            Es = E[..., s, :]
            # window that only the bands of the grid file can reach (no band below band_lo or above band_hi)
            blo_, bhi_ = int(h[6] if dim == 1 else h[8]), int(h[8] if dim == 1 else h[10])
            nbt = int(S.get('n_orbitals', 0)) * (2 if int(S.get('soc', 0)) > 0 else 1)
            lo_e = float(Es.min()) if blo_ == 1 else float(Es[..., 0].max())
            hi_e = float(Es.max()) if (nbt and bhi_ >= nbt) else float(Es[..., -1].min())
            lo_e, hi_e = max(lo_e, Dd[0, 0] + 0.05), min(hi_e, Dd[-1, 0] - 0.05)
            if hi_e - lo_e < 0.2:
                continue
            nw_ = max(1, int((hi_e - lo_e) / 0.5))                       # windows of ~0.5 eV
            for k in range(nw_):
                x0 = lo_e + (hi_e - lo_e) * k / nw_; x1 = lo_e + (hi_e - lo_e) * (k + 1) / nw_
                i0 = max(0, int(np.ceil((x0 - Dd[0, 0]) / de + 0.5))); i1 = min(len(Dd) - 1, int(np.floor((x1 - Dd[0, 0]) / de - 0.5)))
                if i1 <= i0:
                    continue
                e0, e1 = Dd[i0, 0] - de / 2, Dd[i1, 0] + de / 2              # window = whole bins
                got = float(Dd[i0:i1 + 1, 1 + s].sum() * de)
                if dim == 1:
                    A, B = Es, np.roll(Es, -1, axis=0)
                    lo, hi = np.minimum(A, B), np.maximum(A, B); L = hi - lo
                    cnt = lambda x: np.where(L > 1e-12, np.clip((x - lo) / np.maximum(L, 1e-300), 0, 1), (lo < x)).sum() / len(Es)
                else:
                    P = [Es, np.roll(Es, -1, 1), np.roll(Es, -1, 0), np.roll(np.roll(Es, -1, 0), -1, 1)]
                    def cnt(x):
                        tot = 0.0
                        for T in (np.stack([P[0], P[1], P[2]], -1), np.stack([P[3], P[1], P[2]], -1)):
                            T = np.sort(T, -1); t1, t2, t3 = T[..., 0], T[..., 1], T[..., 2]
                            o = np.where(x <= t1, 0.0, np.where(x >= t3, 1.0, np.where(
                                x <= t2, (x - t1) ** 2 / np.maximum((t2 - t1) * (t3 - t1), 1e-30),
                                1.0 - (t3 - x) ** 2 / np.maximum((t3 - t1) * (t3 - t2), 1e-30))))
                            tot += o.sum()
                        return tot / (2 * Es.shape[0] * Es.shape[1])
                ref = cnt(e1) - cnt(e0)
                if ref > 0.05:
                    r = abs(got - ref) / ref
                    if r >= worst:
                        worst = r; wnote = f'worst window [{e0:.2f},{e1:.2f}] eV: {got:.4f} vs {ref:.4f} states'
                    notes.append(1)
        st = 'PASS' if (notes and worst <= 0.01) else ('SKIP' if not notes else 'FAIL')
        self.add('D05', st, 'states in 0.5 eV windows from dos.dat = exact count on the k-grid (limit 1 %)', worst,
                 (f'{len(notes)} windows; ' + wnote) if notes else 'no window with only grid bands')

    def label_check(self, d, S, top, gfile):
        """H10: every projection group "element-n l" equals the shells listed by SIESTA itself in <label>.ORB_INDX
        (columns spec, n, l), with the same number of orbitals per (element, shell) -- independent of the engine"""
        fd = os.path.abspath(os.path.join(top, S.get('fdf_dir', '.')))
        lab = S.get('system_label') or os.path.basename(d)[:-len('_3dbands')]
        oi = os.path.join(fd, lab + '.ORB_INDX')
        if not os.path.exists(oi):
            self.add('H10', 'SKIP', 'projection labels = shells in SIESTA ORB_INDX', 0.0, f'{os.path.basename(oi)} not found')
            return
        L = open(oi).read().split('\n')
        nou = int(L[0].split()[0])
        lname = 'spdfgh'
        sie = {}
        for l in L[3:3 + nou]:
            w = l.split()
            if len(w) < 9:
                continue
            spec, n, ll = w[3], int(w[5]), int(w[6])
            k = f'{spec}-{n}{lname[ll]}'; sie[k] = sie.get(k, 0) + 1
        h = [x for x in open(os.path.join(d, gfile)) if x.startswith('#')]
        names = canon_names(next(x.split()[2:] for x in h if x.split()[1] == 'groups'), d, S)
        mine = list(dict.fromkeys(n[:-3] if n.endswith(('_up', '_dn')) else n for n in names))
        miss, extra = sorted(set(sie) - set(mine)), sorted(set(mine) - set(sie))
        ok = not miss and not extra
        self.add('H10', 'PASS' if ok else 'FAIL', 'projection labels "element n l" = shells in SIESTA ORB_INDX',
                 float(len(miss) + len(extra)),
                 f'{len(sie)} shells: ' + ', '.join(f'{k} ({v} orb.)' for k, v in sie.items())[:170]
                 + (f'; missing {miss}' if miss else '') + (f'; not in SIESTA {extra}' if extra else ''))

    def channel_gaps(self, d, S):
        """independent list of the gap of every spin channel shown in figure 1 (None = metallic / gapless):
        one channel -> [gap of spin 1]; collinear magnet -> [spin 1, spin 2]; spin-orbit -> [up, down character]"""
        soc = int(S.get('soc', 0)) > 0; ns = int(S['nspin'])
        def g_of(s):
            if 'insulator' not in S.get(f'spin{s}_type', 'insulator') or f'spin{s}_CBM_E_k' not in S:
                return None
            g = float(S[f'spin{s}_CBM_E_k'].split()[0]) - float(S[f'spin{s}_VBM_E_k'].split()[0])
            return g if g >= 0.02 else None
        if soc:
            out = []
            for tg in ('up', 'dn'):
                g = float(S.get(f'soc_{tg}_gap_eV', 'nan'))
                out.append(g if np.isfinite(g) and g >= 0.02 else None)
            return out
        if ns == 2 and not spin_identical(d, S):
            return [g_of(1), g_of(2)]
        return [g_of(1)]

    def fig1_check(self, d, S, ax):
        """H09 figure 1: layout by spin case (one panel without spin polarisation, DOS up | bands up | bands down |
        DOS down for a magnet or spin-orbit run); every channel with a gap has ONE arrow with that gap (summary,
        1 %), a metallic / gapless channel none; DOS of the channels = total of dos.dat; elements add up to it.
        H11: the band lines use one colour per band"""
        f1 = (ax or {}).get('fig1')
        if f1 is None:
            self.add('H09', 'FAIL', 'figure 1 recorded', 0.0, 'not recorded'); return
        pf = os.path.join(d, 'pdos.dat')
        names = canon_names(next(l.split()[2:] for l in open(pf) if l.startswith('#') and l.split()[1] == 'groups'), d, S)
        spec = list(dict.fromkeys((nm[:-3] if nm.endswith(('_up', '_dn')) else nm).rsplit('-', 1)[0] for nm in names))
        soc = int(S.get('soc', 0)) > 0; ns = int(S['nspin'])
        gaps = self.channel_gaps(d, S)
        two = len(gaps) == 2
        E = np.array(f1.get('E', []))
        Dd = np.loadtxt(os.path.join(d, 'dos.dat'))
        ref = Dd[:, 1:1 + (1 if soc else ns)].sum(1) * (2.0 if (ns == 1 and not soc) else 1.0)
        ref = ref[[int(np.argmin(np.abs(Dd[:, 0] - e))) for e in E]]
        if two:
            T = sum(np.array(c['tot']) for c in f1.get('chan', []))
            rs = max([float(np.abs(np.array(c['atoms']).sum(0) - np.array(c['tot'])).sum() /
                            max(np.abs(np.array(c['tot'])).sum(), 1e-12)) for c in f1.get('chan', [])] or [1.0])
        else:
            T = np.array(f1.get('tot', [])); A = np.array(f1.get('atoms', []))
            rs = float(np.abs(A.sum(0) - T).sum() / max(np.abs(T).sum(), 1e-12)) if A.size else 1.0
        rt = float(np.abs(T - ref).sum() / max(np.abs(ref).sum(), 1e-12)) if len(E) else 1.0
        arr = [r for r in (ax or {}).get('gap_arrows', []) if not r.get('overall')]
        bad = []
        for k, g in enumerate(gaps):
            if two and soc:
                mine = [r for r in arr if r.get('char') == (1 if k == 0 else -1)]
            elif two:
                mine = [r for r in arr if int(r['spin']) == k and r.get('char') is None]
            else:
                mine = [r for r in arr if r.get('char') is None]
            if g is None and mine:
                bad.append(f'channel {k + 1} is metallic / gapless but has a gap arrow')
            if g is not None and (not mine or any(abs(r['gap'] - g) > max(0.010 * g, 1e-3) for r in mine)):
                bad.append(f'channel {k + 1}: arrows {[round(r["gap"], 4) for r in mine]} vs gap {g:.4f} eV')
        okl = f1.get('panels') == (4 if two else 1)
        ok = okl and f1.get('dos_names') == spec and rt <= 1e-3 and rs <= 0.010 and not bad
        self.add('H09', 'PASS' if ok else 'FAIL',
                 'figure 1: layout by spin case, one arrow per gapped channel (none if gapless), total + element DOS',
                 max(rt, rs), f'{f1.get("panels")} panel(s) ({"magnet / spin-orbit" if two else "one band set"}); '
                 f'elements {f1.get("dos_names")} (expected {spec}); DOS vs dos.dat {rt:.1e}; elements vs total {rs:.1e}; '
                 + ('; '.join(bad) if bad else 'gaps ' + ', '.join('metallic' if g is None else f'{g:.4f} eV' for g in gaps)))
        nc = int(f1.get('band_colours', 0)); nl = int(f1.get('band_lines', 2))
        ncyc = int(f1.get('palette', 12))                 # a one-band model has one colour
        self.add('H11', 'PASS' if nc >= min(nl, ncyc) and nc >= 1 else 'FAIL',
                 'figure 1: every band its own colour (number of colours used)',
                 float(nc), f'{nc} colours for {nl} band lines')

    def page_bands_fat(self, d, S, Dj):
        """G13 page: the gap of every spin channel (none for a metallic / gapless one), the same as figure 1;
        G14 page fat bands: both resolutions (atom + orbital "Mo 4d"; atoms "Mo"), no px / py / pz, circles and
        PDOS for every spin channel; the PDOS of each resolution adds up to the channel's total DOS"""
        import re as _re
        pub = Dj.get('pub') or {}
        chs = pub.get('chs') or []
        gaps = self.channel_gaps(d, S)
        bad = []
        if len(chs) != len(gaps):
            bad.append(f'{len(chs)} channel(s) on the page, {len(gaps)} expected')
        else:
            for k, (c, g) in enumerate(zip(chs, gaps)):
                gp = c.get('gap')
                if g is None and gp:
                    bad.append(f'channel {k + 1} gapless but the page shows {gp[4]:.4f} eV')
                if g is not None and (not gp or abs(gp[4] - g) > max(0.010 * g, 1e-3)):
                    bad.append(f'channel {k + 1}: page {gp[4] if gp else None} vs {g:.4f} eV')
        self.add('G13', 'PASS' if not bad else 'FAIL', 'page: gap of each spin channel, none when gapless', float(len(bad)),
                 '; '.join(bad) or ', '.join('metallic' if g is None else f'{g:.4f} eV' for g in gaps))
        fv = pub.get('fatv') or {}
        dec = lambda x: np.frombuffer(base64.b64decode(x), '<f4').astype(float)
        okn = set(fv) == {'fine', 'atom'} and all(_re.fullmatch(r'\S+ \d[spdf]', n) for n in fv.get('fine', {}).get('names', [])) \
            and not any(_re.search(r'p[xyz]', n) for v in fv.values() for n in v['names'])
        okc, worst = bool(chs), 0.0
        for c in chs:
            if not c.get('fatv') or set(c['fatv']) != {'fine', 'atom'} or set(c.get('fpd', {})) != {'fine', 'atom'}:
                okc = False; continue
            tot = dec(c['tot'])
            for v in ('fine', 'atom'):
                s_ = sum(dec(x) for x in c['fpd'][v])
                worst = max(worst, float(np.abs(s_ - tot).sum() / max(np.abs(tot).sum(), 1e-12)))
        self.add('G14', 'PASS' if (okn and okc and worst <= 0.010) else 'FAIL',
                 'page fat bands: atoms and atom + orbital (s/p/d/f) circles and PDOS, every spin channel', worst,
                 f'{len(chs)} channel(s); shells ' + ', '.join(fv.get('fine', {}).get('names', []))[:140])

    def spin_and_files(self, d, S, ax, top, label):
        """H06 figures folder holds only this run's files; H07/H08 spin-orbit spin-up / spin-down gaps;
        Q05-Q07 the QPI scattering-vector table"""
        fd = os.path.join(d, 'figures'); mf = os.path.join(fd, 'MANIFEST.txt')
        if os.path.exists(mf):
            want = {l.strip() for l in open(mf) if l.strip() and not l.startswith('#')}
            have = {f for f in os.listdir(fd) if f.endswith(('.png', '.pdf', '.svg'))}
            extra, miss = sorted(have - want), sorted(want - have)
            self.add('H06', 'PASS' if not extra and not miss else 'FAIL',
                     'figures/ holds only the files of this run (no stale figures)', float(len(extra) + len(miss)),
                     ('left over: ' + ', '.join(extra) if extra else '') + (' missing: ' + ', '.join(miss) if miss else '')
                     or f'{len(have)} files = MANIFEST.txt')
        else:
            self.add('H06', 'FAIL', 'figures/ holds only the files of this run', 0.0, 'MANIFEST.txt missing')
        soc_mag = int(S.get('soc', 0)) > 0 and S.get('time_reversal', '1') == '0'
        if soc_mag and int(S.get('periodic_dims', 2)) >= 1:
            titles = [t['title'] for t in (ax or {}).get('panel_titles', [])]
            arr = [r for r in (ax or {}).get('gap_arrows', []) if r.get('char') is not None]
            ok_t = bool(titles) and all(t in ('Spin Up', 'Spin Down') for t in titles)
            gu, gd = float(S.get('soc_up_gap_eV', 'nan')), float(S.get('soc_dn_gap_eV', 'nan'))
            ok_a = bool(arr) and all(abs(r['gap'] - (gu if r['char'] > 0 else gd)) < 1e-4 for r in arr) and \
                {r['char'] for r in arr} == {1, -1}
            self.add('H07', 'PASS' if ok_t and ok_a else 'FAIL',
                     'spin-orbit: Spin Up / Spin Down panels, one gap arrow per spin character', float(len(arr)),
                     f'titles {sorted(set(titles))}; arrows ' + ', '.join(f'{"↑" if r["char"] > 0 else "↓"} {r["gap"]:.4f}' for r in arr)
                     + f'; summary ↑ {gu:.4f} ↓ {gd:.4f} eV')
            bz, bs = os.path.join(d, 'bz_grid.dat'), os.path.join(d, 'bz_spin.bin')
            if int(S.get('periodic_dims', 2)) != 2:
                self.add('H08', 'SKIP', 'spin-up / spin-down gaps recomputed from the grid', 0.0,
                         'plane grid file only for 2D systems')
            elif os.path.exists(bz) and os.path.exists(bs):
                h = open(bz).readline().split()
                Na, Nb, blo, bhi = int(h[2]), int(h[4]), int(h[8]), int(h[10])
                nw = bhi - blo + 1
                G = np.loadtxt(bz)[:, 4:4 + nw]
                Z = np.fromfile(bs, np.int8).reshape(-1, nw)
                no = int(S['spin1_nocc'])
                occ = (np.arange(blo, bhi + 1) <= no)[None, :]
                res = []
                for ch, tag in ((1, 'up'), (-1, 'dn')):
                    own = (Z >= 0) if ch > 0 else (Z < 0)
                    vb = np.where(own & occ, G, -np.inf).max(); cb = np.where(own & ~occ, G, np.inf).min()
                    ref = float(S.get(f'soc_{tag}_gap_eV', 'nan'))
                    res.append((tag, cb - vb, ref))
                dmax = max(abs(g - r) for _, g, r in res)
                lim = max(0.010 * min(r for _, _, r in res), 2e-3)
                self.add('H08', 'PASS' if dmax <= lim else 'FAIL',
                         'spin-up / spin-down gaps recomputed from bz_grid + bz_spin (eV; limit 1 %)', dmax,
                         ', '.join(f'{t} {g:.4f} vs {r:.4f}' for t, g, r in res))
            else:
                self.add('H08', 'FAIL', 'spin-up / spin-down gaps recomputed from the grid', 0.0, 'bz_spin.bin missing')
        # ---------- QPI scattering-vector table
        pf = os.path.join(d, 'qpi_peaks.txt')
        if int(S.get('periodic_dims', 2)) == 1 and os.path.exists(os.path.join(d, 'grid1d.dat')):
            return self.qpi_1d(d, S, pf)
        if int(S.get('periodic_dims', 2)) >= 2 and os.path.exists(os.path.join(d, 'bz_grid.dat')):
            if not os.path.exists(pf):
                self.add('Q05', 'FAIL', 'QPI scattering-vector table written', 0.0, 'qpi_peaks.txt missing')
                return
            rows = []
            for l in open(pf):
                if l.startswith('#') or not l.strip():
                    continue
                w = l.split()
                rows.append(dict(E=float(w[0]), eta=float(w[1]), qty=w[2], dir=w[3], q=float(w[4]), qx=float(w[5]),
                                 qy=float(w[6]), lam=float(w[7]), I=float(w[8]), cons=float(w[13])))
            bad = [r for r in rows if abs(r['lam'] - 2 * np.pi / r['q']) > 2e-3 * r['lam'] or
                   abs(np.hypot(r['qx'], r['qy']) - r['q']) > 2e-4 or not (0 < r['I'] <= 1.0001)]
            self.add('Q05', 'PASS' if rows and not bad else 'FAIL',
                     'QPI peak table: λ = 2π/|q|, |q| = |(qx, qy)|, 0 < I <= 1', float(len(bad)),
                     f'{len(rows)} peaks, {sum(r["qty"] == "JDOS" for r in rows)} JDOS')
            # independent JDOS at the listed peaks: local maximum along the direction
            h = open(os.path.join(d, 'bz_grid.dat')).readline().split()
            Na, Nb, ns, blo, bhi = int(h[2]), int(h[4]), int(h[6]), int(h[8]), int(h[10])
            nw = bhi - blo + 1
            B = np.array(open(os.path.join(d, 'bz_grid.dat')).readlines()[1].split(':')[1].split(), float).reshape(2, 2)
            G = np.loadtxt(os.path.join(d, 'bz_grid.dat'))[:, 4:4 + ns * nw].reshape(Nb, Na, ns, nw).transpose(1, 0, 2, 3)
            Zs = None
            bs = os.path.join(d, 'bz_spin.bin')
            if os.path.exists(bs):
                Zs = np.fromfile(bs, np.int8).astype(float).reshape(Nb, Na, nw).transpose(1, 0, 2) / 127.0
            fr = int(np.ceil(240 / min(Na, Nb)))
            if fr > 1:                     # coarse grid: same periodic bilinear refinement as stated in the method
                def refine(X):
                    n1, n2 = X.shape[:2]
                    out = np.empty((n1 * fr, n2 * fr) + X.shape[2:])
                    for a in range(fr):
                        for b in range(fr):
                            u, v = a / fr, b / fr
                            out[a::fr, b::fr] = ((1 - u) * (1 - v) * X + u * (1 - v) * np.roll(X, -1, 0)
                                                 + (1 - u) * v * np.roll(X, -1, 1) + u * v * np.roll(np.roll(X, -1, 0), -1, 1))
                    return out
                G = refine(G)
                if Zs is not None:
                    Zs = refine(Zs)
                Na, Nb = Na * fr, Nb * fr
            jr = [r for r in rows if r['qty'] == 'JDOS']
            E0s = sorted({(r['E'], r['eta']) for r in jr})[:2]
            worst, worst_c, nchk = 0.0, 0.0, 0
            for E0, eta in E0s:
                L = eta / np.pi / ((E0 - G) ** 2 + eta ** 2)                     # [i, j, spin, band]
                A = L.sum((2, 3))
                Fa = np.fft.fft2(A); J = np.real(np.fft.ifft2(np.abs(Fa) ** 2))
                # independent spin-resolved JDOS: spin-orbit by <sz>, collinear by channel, unpolarised A_up = A_dn
                au = (L[:, :, 0] * 0.5 * (1 + Zs)).sum(-1) if Zs is not None else L[:, :, 0].sum(-1)
                ad = (L[:, :, 0] * 0.5 * (1 - Zs)).sum(-1) if Zs is not None else (L[:, :, 1].sum(-1) if ns == 2 else au)
                xc = lambda a, b: np.real(np.fft.ifft2(np.conj(np.fft.fft2(a)) * np.fft.fft2(b)))
                Jc = xc(au, au) + xc(ad, ad); Jfl = xc(au, ad) + xc(ad, au)
                dq = 0.6 * min(np.linalg.norm(B[0]) / Na, np.linalg.norm(B[1]) / Nb)
                for r in [r for r in jr if (r['E'], r['eta']) == (E0, eta)]:
                    u = np.array([r['qx'], r['qy']]) / r['q']
                    f0 = bilin(J, B, r['qx'], r['qy'])
                    nb_ = max(bilin(J, B, *(np.array([r['qx'], r['qy']]) + s_ * dq * u)) for s_ in (-1, 1))
                    # and the listed q is the top of its own peak: a local maximum of the independent profile lies
                    # within 0.01 1/Ang of it (a peak moved off its position fails here)
                    ss = np.linspace(r['q'] - 0.05, r['q'] + 0.05, 201)
                    prof = np.array([bilin(J, B, *(x * u)) for x in ss])
                    lm = [i for i in range(1, len(ss) - 1) if prof[i] >= prof[i - 1] and prof[i] >= prof[i + 1]]
                    off = min([abs(ss[i] - r['q']) for i in lm] or [1.0])     # nearest local maximum
                    worst = max(worst, (nb_ - f0) / max(f0, 1e-30), 0.0 if off <= 0.01 else 1.0); nchk += 1
                    if Jc is not None and np.isfinite(r['cons']):
                        a_, b_ = bilin(Jc, B, r['qx'], r['qy']), bilin(Jfl, B, r['qx'], r['qy'])
                        worst_c = max(worst_c, abs(a_ / max(a_ + b_, 1e-30) - r['cons']))
            self.add('Q06', 'PASS' if nchk and worst <= 0.010 else 'FAIL',
                     'listed JDOS peaks = maxima of an independent JDOS (within 0.01 1/Å; rel. 1 %)', worst,
                     f'{nchk} peaks at {len(E0s)} energies, step ±{dq:.4f} 1/Å along the direction')
            if True:
                self.add('Q07', 'PASS' if worst_c <= 0.010 else 'FAIL',
                         'spin-conserving share at the peaks = independent spin-resolved JDOS (limit 0.010)', worst_c)

    def qpi_1d(self, d, S, pf):
        """1D wires / tubes: peak table (Q05), peaks = maxima of an independent JDOS (Q06), real-space
        Friedel oscillation = direct (non-FFT) sum of the Green functions (R01)"""
        if not os.path.exists(pf):
            self.add('Q05', 'FAIL', '1D QPI scattering-vector table written', 0.0, 'qpi_peaks.txt missing'); return
        rows = []
        for l in open(pf):
            if l.startswith('#') or not l.strip():
                continue
            w = l.split()
            rows.append(dict(E=float(w[0]), eta=float(w[1]), qty=w[2], q=float(w[4]), lam=float(w[7]), I=float(w[8])))
        g1 = os.path.join(d, 'grid1d.dat')
        h = open(g1).readline().split()
        N1, ns, blo, bhi, b = int(h[2]), int(h[4]), int(h[6]), int(h[8]), float(h[10])
        bad = [r for r in rows if abs(r['lam'] - 2 * np.pi / r['q']) > 2e-3 * r['lam'] or not (0 < r['q'] <= b / 2 + 1e-6)
               or not (0 < r['I'] <= 1.0001)]
        self.add('Q05', 'PASS' if rows and not bad else 'FAIL', '1D peak table: λ = 2π/q, 0 < q <= b/2, 0 < I <= 1',
                 float(len(bad)), f'{len(rows)} peaks')
        E = np.loadtxt(g1)[:, 2:].reshape(N1, ns, bhi - blo + 1)
        fr = int(np.ceil(600 / N1))                      # the periodic linear refinement stated in the method
        if fr > 1:
            u = np.arange(N1 * fr) / fr; i0 = np.floor(u).astype(int); w_ = (u - i0)[:, None, None]
            E = (1 - w_) * E[i0 % N1] + w_ * E[(i0 + 1) % N1]
        N = E.shape[0]; dq = b / N
        worst, n = 0.0, 0
        for E0, eta in sorted({(r['E'], r['eta']) for r in rows if r['qty'] == 'JDOS'}):
            A = (eta / np.pi / ((E0 - E) ** 2 + eta ** 2)).sum((1, 2))
            for r in [r for r in rows if r['qty'] == 'JDOS' and (r['E'], r['eta']) == (E0, eta)]:
                qs = np.arange(int((r['q'] - 0.05) / dq), int((r['q'] + 0.05) / dq) + 1)
                J = np.array([np.dot(A, np.roll(A, -m)) / N for m in qs])            # direct sum, no FFT
                lm = [i for i in range(1, len(qs) - 1) if J[i] >= J[i - 1] and J[i] >= J[i + 1]]
                off = min([abs(qs[i] * dq - r['q']) for i in lm] or [1.0])
                worst = max(worst, off); n += 1
        self.add('Q06', 'PASS' if n and worst <= 0.01 else 'FAIL',
                 '1D JDOS peaks = local maxima of an independent JDOS (direct sum; within 0.01 1/Å)', worst,
                 f'{n} peaks')
        ff = os.path.join(d, 'friedel_1d.dat')
        if not os.path.exists(ff):
            self.add('R01', 'FAIL', 'real-space Friedel oscillation written', 0.0, 'friedel_1d.dat missing'); return
        hdr = open(ff).readline().split()
        eta = float(hdr[hdr.index('eta') + 1]); nx = int(hdr[hdr.index('nx') + 1])
        F = np.loadtxt(ff)
        kk = np.arange(N) * dq
        a = 2 * np.pi / b
        rel = 0.0
        for i in np.linspace(0, len(F) - 1, 7).astype(int)[1:-1]:
            e0 = F[i, 0]
            G = (1.0 / (e0 - E + 1j * eta)).sum(2)                                   # [k, spin]
            val = np.zeros(nx + 1)
            for m in range(nx + 1):
                ph = np.exp(1j * kk * m * a)
                gp = (G * ph[:, None]).sum(0) / N; gm = (G * np.conj(ph)[:, None]).sum(0) / N
                val[m] = float((-np.imag(gp * gm) / np.pi).sum())
            ref = F[i, 1 + nx:1 + 2 * nx + 1]                                        # x = 0 .. +nx a
            sc = max(np.abs(ref).max(), 1e-3 * np.abs(F[:, 1:]).max(), 1e-30)   # rows where drho vanishes by symmetry
            rel = max(rel, float(np.abs(val - ref).max() / sc))
        self.add('R01', 'PASS' if rel <= 0.010 else 'FAIL',
                 'real-space Friedel oscillation = direct Green-function sum (rel.; limit 1 %)', rel,
                 f'5 energies, {nx + 1} cells each')

    def run_0d(self, d, S, label, top):
        """molecule / cluster: everything re-derived from levels.dat, dos.dat, pdos.dat and the SIESTA .EIG"""
        with open(os.path.join(d, 'levels.dat')) as f:
            h = f.readline().split(); grp = f.readline().split()[2:]
        ns, ng = int(h[4]), len(grp)
        a = np.atleast_2d(np.loadtxt(os.path.join(d, 'levels.dat')))
        EF = float(S['E_F_eV'])
        # Z01 levels vs .EIG (own parser: Ef / nb ns nk / k-index then values)
        eig = next((f for f in (os.path.join(top, label + '.EIG'), os.path.join(S.get('fdf_dir', '.'), label + '.EIG'))
                    if os.path.exists(f)), None)
        if eig:
            t = open(eig).read().split()
            ef, nb, nse = float(t[0]), int(t[1]), int(t[2])
            v = np.array(t[5:5 + nb * nse], float).reshape(nse, nb)
            dm = 0.0
            for s in range(min(ns, nse)):
                mine = np.sort(a[a[:, 0] == s + 1, 2]) + EF
                m = min(len(mine), nb)
                dm = max(dm, float(np.max(np.abs(mine[:m] - np.sort(v[s])[:m]))))
            self.add('Z01', 'PASS' if dm < 1e-3 else 'FAIL', 'molecular levels = SIESTA .EIG (max |dE|, eV)', dm,
                     f'{a.shape[0]} levels, {os.path.basename(eig)}')
            self.add('Z02', 'PASS' if abs(ef - EF) < 1e-4 else 'FAIL', 'E_F in .EIG = E_F used (eV)', abs(ef - EF))
        else:
            self.add('Z01', 'SKIP', 'molecular levels = SIESTA .EIG', 0.0, 'no .EIG file')
        # Z03 electron count and aufbau order
        occ = a[:, 3]; nel = float(S.get('n_electrons', occ.sum()))
        self.add('Z03', 'PASS' if abs(occ.sum() - nel) < 1e-6 else 'FAIL', 'sum of occupations = n_electrons',
                 abs(occ.sum() - nel), f'{occ.sum():.3f} electrons')
        Eo, Ee = a[occ > 1e-6, 2], a[occ < 1e-6, 2]
        aufbau = (len(Ee) == 0 or len(Eo) == 0 or Eo.max() <= Ee.min() + 1e-9)
        self.add('Z04', 'PASS' if aufbau else 'FAIL', 'aufbau: every occupied level below every empty level', 0.0)
        # Z05 HOMO / LUMO / gap re-derived
        homo, lumo = (float(Eo.max()) if len(Eo) else np.nan), (float(Ee.min()) if len(Ee) else np.nan)
        dg = max(abs(homo - float(S['HOMO_eV'])), abs(lumo - float(S['LUMO_eV'])),
                 abs((lumo - homo) - float(S['overall_gap_eV'])))
        self.add('Z05', 'PASS' if dg < 1e-4 else 'FAIL', 'HOMO, LUMO and gap recomputed = summary (eV)', dg,
                 f'HOMO {homo:.4f}, LUMO {lumo:.4f}, gap {lumo - homo:.4f} eV')
        # Z06 Mulliken weights
        w = a[:, 4:4 + ng]
        self.add('Z06', 'PASS' if np.max(np.abs(w.sum(1) - 1)) < 1e-3 else 'FAIL', 'Mulliken weights of every level sum to 1',
                 float(np.max(np.abs(w.sum(1) - 1))))
        # Z07 DOS integral = number of levels in the window; Z08 sum of PDOS = DOS
        dd = np.atleast_2d(np.loadtxt(os.path.join(d, 'dos.dat')))
        Ed = dd[:, 0]; de = Ed[1] - Ed[0]
        lo, hi = Ed[0] + 0.3, Ed[-1] - 0.3
        from math import erf, sqrt
        dev = 0.0
        sg = 0.05                                          # Gaussian of dos.dat (header)
        for s in range(ns):
            m = (Ed >= lo) & (Ed <= hi)
            Es = a[a[:, 0] == s + 1, 2]
            x0, x1 = Ed[m][0] - de / 2, Ed[m][-1] + de / 2
            nexp = sum(0.5 * (erf((x1 - e) / (sqrt(2) * sg)) - erf((x0 - e) / (sqrt(2) * sg))) for e in Es)
            integ = float(dd[m, 1 + s].sum() * de)
            dev = max(dev, abs(integ - nexp))
        self.add('Z07', 'PASS' if dev < 0.02 else 'FAIL', 'integral of the DOS = number of levels in the window '
                 '(Gaussian weight of every level, exact)', dev)
        try:
            pd = np.atleast_2d(np.loadtxt(os.path.join(d, 'pdos.dat')))
            r = 0.0
            for s in range(ns):
                tot = dd[:, 1 + s]; ps = pd[:, 1 + s * ng:1 + (s + 1) * ng].sum(1)
                r = max(r, float(np.abs(ps - tot).max() / max(np.abs(tot).max(), 1e-300)))
            self.add('Z08', 'PASS' if r < 0.010 else 'FAIL', 'sum of PDOS = total DOS at every energy (max |diff| / max DOS; limit 1 %)', r)
        except Exception as ex:
            self.add('Z08', 'FAIL', 'sum of PDOS = total DOS', 0.0, str(ex)[:60])
        bad = []
        for fn in ('validation.txt', 'validation_plots.txt'):
            p = os.path.join(d, fn)
            if os.path.exists(p):
                bad += [l.split('|')[1].strip() for l in open(p) if l.startswith('FAIL')]
        self.add('E01', 'PASS' if not bad else 'FAIL', 'no FAIL in the engine / plot validation tables', len(bad),
                 '; '.join(bad))
        try:
            from PIL import Image
            miss, asp = [], []
            for n in ('0_validation', '1_levels_dos', '1b_projected_levels'):
                f = os.path.join(d, 'figures', n + '.png')
                if not os.path.exists(f):
                    miss.append(n); continue
                wd, ht = Image.open(f).size; asp.append((n, wd / ht))
            self.add('F01', 'PASS' if not miss else 'FAIL', 'all 0D figures written (0, 1, 1b)', len(miss), ', '.join(miss))
            if asp:
                amin, amax = min(x for _, x in asp), max(x for _, x in asp)
                self.add('F02', 'PASS' if 0.80 <= amin and amax <= 1.35 else 'WARN', 'figure width:height within 0.80-1.35',
                         amax, ', '.join(f'{n} {x:.2f}' for n, x in asp))
        except ImportError:
            self.add('F01', 'SKIP', 'figures', 0.0, 'Pillow not installed')
        html = os.path.join(top, label + '_interactive.html')
        if os.path.exists(html):
            t = open(html, encoding='utf-8').read()
            i = t.index('const D = ') + len('const D = ')
            Dj = json.loads(t[i:t.index('\n', i)].rstrip(';'))
            L = Dj.get('levels')
            if L:
                dl = max(float(np.max(np.abs(np.sort(L['E'][s]) - np.sort(a[a[:, 0] == s + 1, 2])))) for s in range(ns))
                self.add('G01', 'PASS' if dl < 1e-3 else 'FAIL', 'HTML levels = levels.dat (eV)', dl)
            else:
                self.add('G01', 'FAIL', 'HTML levels', 0.0, 'no level data in the page')
            self.add('G02', 'PASS' if 'plotly' in t[:200000].lower() else 'FAIL', 'plotly embedded (works offline)', 0.0)
            self.add('G06', 'PASS' if 'function fitTab(' in t else 'FAIL', 'HTML panels sized to the browser window', 0.0)
            self.add('G07', 'PASS' if 'Satish Kumar' in t else 'FAIL', 'author shown in the HTML header', 0.0)
            # G12: level projections on the page: atoms view present and default; every curve of every view = its
            # shells in levels.dat (exact regrouping, no clipping); labels "element n l" for the orbital view
            grp0 = [x for x in open(os.path.join(d, 'levels.dat')) if x.startswith('#')][1].split()[2:]
            Wf = [a[a[:, 0] == s + 1, 4:4 + ng] for s in range(ns)]
            spec = list(dict.fromkeys(g.rsplit('-', 1)[0] for g in grp0))
            V = (L or {}).get('views') or []
            worst, okn = 0.0, bool(V) and V[0]['key'] == 'atom' and V[0]['names'] == spec
            for v in V:
                for s in range(ns):
                    for j, nm in enumerate(v['names']):
                        if v['key'] == 'atom':
                            cols = [c for c, g in enumerate(grp0) if g.rsplit('-', 1)[0] == nm]
                        elif v['key'] == 'fine':
                            cols = [c for c, g in enumerate(grp0) if g.replace('-', ' ', 1) == nm or
                                    (g.rsplit('-', 1)[0] + ' ' + g.rsplit('-', 1)[1]) == nm]
                        else:
                            cols = [c for c, g in enumerate(grp0) if g.rsplit('-', 1)[1].lstrip('0123456789') == nm]
                        if not cols:
                            okn = False; continue
                        ref = Wf[s][:, cols].sum(1)
                        worst = max(worst, float(np.max(np.abs(np.asarray(v['w'][s])[:, j] - ref))))
            self.add('G12', 'PASS' if (okn and worst <= 1e-5) else 'FAIL',
                     'page level projections: atoms (default), atom + orbital, orbital = regrouped levels.dat', worst,
                     '; '.join(f"{v['key']}: {', '.join(v['names'])}" for v in V)[:170] or 'no projection views on the page')
        else:
            self.add('G01', 'FAIL', 'interactive page exists', 0.0, html)
        self.label_check(d, S, top, 'levels.dat')
        self.spin_and_files(d, S, None, top, label)
        json.dump(self.rows, open(os.path.join(d, 'audit.json'), 'w'), indent=1)
        return self.rows


def au_write_text(d, rows):
    lines = [f"[{r['status']:4s}] {r['id']} {r['check']:62s} {r['value']:11.3e}  {r['note']}" for r in rows]
    nf = sum(r['status'] == 'FAIL' for r in rows)
    txt = '\n'.join(lines) + f'\n\naudit: {nf} FAIL, {sum(r["status"] == "WARN" for r in rows)} WARN\n'
    open(os.path.join(d, 'audit.txt'), 'w').write(txt)
    rep = os.path.join(d, 'validation_report.txt')
    if os.path.exists(rep):
        body = open(rep).read().split(AU_MARK)[0]
        # the first line of the report states the result of BOTH the plot/engine checks and this audit
        L = body.split('\n')
        for i, l in enumerate(L):
            if l.startswith('verdict:'):
                v = l.split(' | independent audit')[0]
                L[i] = v + (f' | independent audit: {nf} FAIL' if nf else ' | independent audit: 0 FAIL')
                break
        open(rep, 'w').write('\n'.join(L) + AU_MARK + '\n' + txt)
    return nf


AU_MARK = '=== 3. INDEPENDENT AUDIT (siesta3d_audit.py: re-reads the raw files, does not use the plotting code) ==='


def audit_main(argv):
    dirs = [a for a in argv[1:] if not a.startswith('--')] or glob.glob('*_3dbands')
    verbose = '--verbose' in argv
    nf = 0
    for d in dirs:
        try:
            rows = Audit(d).run()
        except Exception as ex:                        # the audit itself failed: report it as a FAIL, never silently
            import traceback
            tb = traceback.format_exc().strip().split('\n')[-1]
            rows = [dict(id='X00', status='FAIL', check='independent audit could not finish (program error)', value=0.0,
                         note=f'{type(ex).__name__}: {tb[:160]}')]
        n = au_write_text(d, rows)
        nf += n
        if verbose:
            print(open(os.path.join(d, 'audit.txt')).read())
        print(f'  independent audit        : {sum(r["status"] == "PASS" for r in rows)} PASS, {n} FAIL '
              f'  (validation_report.txt)')
    return 1 if nf else 0


