def _crash_hook(etype, value, tb):
    """an unexpected program error must never pass silently: print it and record it as a FAIL in the report"""
    import traceback
    traceback.print_exception(etype, value, tb)
    msg = f'{etype.__name__}: {value}'.replace('\n', ' ')[:200]
    try:
        with open(os.path.join(OUT, 'validation_report.txt'), 'a') as f:
            f.write(f'\n[FAIL] the figure program stopped with an error: {msg}\n')
    except Exception:
        pass
    print(f'\n  validation               : FAIL - the figure program stopped ({msg[:60]})')


