class Progress:
    """one-line % bar in the terminal ('\r' updates); silent when the output is not a terminal"""
    def __init__(self, label, total):
        self.label, self.total, self.done = label, max(total, 1e-9), 0.0
        self.tty = sys.stdout.isatty()

    def tick(self, w=1.0, what=''):
        self.done = min(self.done + w, self.total)
        if self.tty:
            p = int(100 * self.done / self.total)
            bar = '#' * (p // 5) + '.' * (20 - p // 5)
            print(f'\r\x1b[2K  {self.label:<25s}: {p:3d} %  [{bar}]  {what[:14]}', end='', flush=True)

    def close(self, final=False):
        if self.tty:
            if final:                                          # keep the completed bar on screen
                print(f'\r\x1b[2K  {self.label:<25s}: 100 %  [{"#" * 20}]  complete', flush=True)
            else:
                print('\r\x1b[2K', end='', flush=True)          # erase the line (no padding: no wrap)




