def classify_gap():
    """direct / indirect from the summary: VBM and CBM at the same k, or the smallest direct gap less than
    GAPTOL above the fundamental gap (quasi-direct; far below kT(300 K) and DFT accuracy)"""
    g = float(S.get('overall_gap_eV', 0))
    t = S.get('gap_type', '')
    if g <= 0.02 or not t or 'between' in t:
        return t, ''
    dgs = [float(S[k].split()[0]) for k in ('spin1_direct_gap_k', 'spin2_direct_gap_k') if k in S]
    if not dgs:
        return t, ''
    dE = min(dgs) - g
    if t == 'direct' or dE < GAPTOL:
        ksep = float(S.get('gap_vbm_cbm_k_separation', '0').split()[0])
        note = '' if dE < 1e-4 else (f'VBM and CBM {ksep:.3f} 1/Å apart; the smallest direct gap is only '
                                     f'{1000 * dE:.1f} meV larger, so the gap is direct within DFT accuracy')
        return 'direct', note
    return 'indirect', f'smallest direct gap {min(dgs):.3f} eV ({1000 * dE:.0f} meV above the fundamental gap)'


_gt_file = S.get('gap_type', '')
S['gap_type'], GAPNOTE = classify_gap()
if _gt_file and S['gap_type'] != _gt_file:              # keep summary.txt consistent with the figures
    _L = open(os.path.join(OUT, 'summary.txt')).read().split('\n')
    _L = [f"gap_type : {S['gap_type']}" if l.startswith('gap_type :') else l for l in _L
          if not l.startswith('gap_type_note')]
    _L.insert(next(i for i, l in enumerate(_L) if l.startswith('gap_type :')) + 1, f'gap_type_note : {GAPNOTE}')
    open(os.path.join(OUT, 'summary.txt'), 'w').write('\n'.join(_L))


def header(fname):
    h = {'nodes': []}
    with open(fname) as f:
        for line in f:
            if not line.startswith('#'):
                break
            w = line[1:].split()
            if not w:
                continue
            if w[0] == 'vertices':
                h['vertices'] = np.array(w[1:], float).reshape(-1, 2); continue
            if w[0] == 'node':
                h['nodes'].append((float(w[1]), w[2] if len(w) > 2 else '')); continue
            if w[0] == 'plane_offset':
                h['offset'] = float(w[1]); continue
            if w[0] == 'groups':
                h['groups'] = w[1:]; continue
            if 'energies' in line:
                h['energies'] = [float(x) for x in line.split(':')[1].split()]
            if 'B1 B2' in line:
                h['B'] = np.array(line.split(':')[1].split(), float).reshape(2, 2)
            for i in range(len(w) - 1):
                try:
                    h[w[i]] = int(w[i + 1])
                except ValueError:
                    pass
    return h


class Grid:
    """one k-grid file written by siesta3d (bz / ext / zoom)"""

    def __init__(self, fname):
        h = header(fname)
        a = np.loadtxt(fname)
        n1, n2 = h['n1'], h['n2']
        a = a.reshape(n2, n1, -1)
        self.kx, self.ky = a[:, :, 0], a[:, :, 1]
        ni = h['band_hi'] - h['band_lo'] + 1
        self.idx = a[:, :, 3:3 + nspin * ni].reshape(n2, n1, nspin, ni)
        self.blo = h['band_lo']
        self.nocc = [h['nocc1'], h['nocc2']]
        self.verts = h.get('vertices')
        self.offset = h.get('offset', 0.0)
        self.odd = None
        if h.get('odd', 0) == 1:
            no = h['odd_hi'] - h['odd_lo'] + 1
            self.odd = a[:, :, 3 + nspin * ni:3 + nspin * (ni + no)].reshape(n2, n1, nspin, no)
            self.olo = h['odd_lo']
            self.nocc_o = [h['nocc_odd1'], h['nocc_odd2']]

    def band(self, s, rel, bset):
        if bset == 'pi' and self.odd is not None:
            b, arr = self.nocc_o[s] + rel - self.olo, self.odd
        else:
            b, arr = self.nocc[s] + rel - self.blo, self.idx
        return arr[:, :, s, b] if 0 <= b < arr.shape[-1] else None


# =================================================================== 0D: molecules and clusters (levels at Gamma)
def write_check_sections(f):
    """engine and plotter checks (every error metric has a limit; relative limits are 1 %), then notes"""
    notes = []
    for title, fn in (('=== 1. ENGINE CHECKS (Fortran) ===', 'validation.txt'),
                      ('=== 2. FIGURE / DATA CHECKS (plotter) ===', 'validation_plots.txt')):
        f.write(title + '\n')
        for l in open(os.path.join(OUT, fn)):
            if not l.startswith('#'):
                w = [x.strip() for x in l.rstrip('\n').split(' | ')]
                if len(w) >= 4:
                    if w[0] in ('INFO', 'NOTE'):
                        notes.append(w); continue
                    f.write(f'[{w[0]:4s}] {w[1]:66s} {w[2]:>12s}  {w[3]}\n')
        f.write('\n')
    if notes:
        f.write('=== NOTES (information about the system or about SIESTA\'s own files; not errors of this code) ===\n')
        for w in notes:
            f.write(f'[note] {w[1]:66s} {w[2]:>12s}  {w[3]}\n')
        f.write('\n')


def eig_file():
    """SIESTA <label>.EIG next to the fdf (eigenvalues in eV, absolute) -> (Ef, [spin][level])"""
    fd = os.path.join(OUT, S.get('fdf_dir', '.'))
    for d in (os.path.dirname(os.path.abspath(OUT)), os.path.abspath(fd)):
        f = os.path.join(d, LABEL + '.EIG')
        if os.path.exists(f):
            t = open(f).read().split()
            ef = float(t[0]); nb, ns = int(t[1]), int(t[2])
            v = np.array(t[5:5 + nb * ns], float)          # t[4] = k-point index
            return ef, [np.sort(v[i * nb:(i + 1) * nb]) for i in range(ns)]
    return None


def _gsplit(n):
    base, suf = (n[:-3], n[-3:]) if n.endswith(('_up', '_dn')) else (n, '')
    sp, c = (base.rsplit('-', 1) if '-' in base else (base, ''))
    return base, suf, sp, c


_ORBLAB = {'pxy': 'p', 'pz': 'p', '': 'all'}      # older group names (before v10.11) map to plain s, p, d


def _lshell(c):
    """orbital letter of a group class: '3d' -> 'd', '2p' -> 'p', 'pxy' -> 'p'"""
    c2 = c.lstrip('0123456789')
    return _ORBLAB.get(c2, c2)


def view_names(names, mode):
    """'atom': element ("Cr"); 'orb': orbital letter over all elements ("d"); 'fine': element and shell as in
    SIESTA's basis ("Cr 3d", "O 2p", "H 1s")"""
    out = []
    for n in names:
        base, suf, sp, c = _gsplit(n)
        if mode == 'atom':
            v = sp
        elif mode == 'orb':
            v = _lshell(c)
        else:
            v = f'{sp} {c}' if c else sp
        out.append(v + suf)
    return out


def aggregate(names, arr, mode, axis=-1):
    """sum the groups of arr (along axis) into the view 'mode'; returns (new names, new array)"""
    vn = view_names(names, mode)
    uniq = list(dict.fromkeys(vn))
    M = np.zeros((len(names), len(uniq)))
    for i, v in enumerate(vn):
        M[i, uniq.index(v)] = 1.0
    a = np.moveaxis(np.asarray(arr, float), axis, -1) @ M
    return uniq, np.moveaxis(a, -1, axis)


# ---- canonical shell names. Older engines wrote "C-s", "C-pxy", "C-pz", "C-d" (no n, p split in two). Those are
# merged to one group per (element, l) and given SIESTA's n from <label>.ORB_INDX when it is unique, so the labels are
# always "element n l" (C 2s, C 2p, C 3d) and never px / py / pz.
def _orbindx_n():
    f = os.path.join(os.path.dirname(os.path.abspath(OUT)), S.get('fdf_dir', '.'), LABEL + '.ORB_INDX')
    nmap = {}
    try:
        L = open(f).read().split('\n'); nou = int(L[0].split()[0])
        for l in L[3:3 + nou]:
            w = l.split()
            if len(w) >= 9:
                nmap.setdefault((w[3], int(w[6])), set()).add(int(w[5]))
    except Exception:
        pass
    return nmap


def canon_groups(names):
    """old -> canonical group names and the 0/1 matrix that sums the old groups into them"""
    lnum = {'s': 0, 'p': 1, 'pxy': 1, 'pz': 1, 'd': 2, 'f': 3}
    nmap = None
    new = []
    for n in names:
        base, suf, sp, c = _gsplit(n)
        if c and not c[0].isdigit() and c in lnum:
            nmap = _orbindx_n() if nmap is None else nmap
            ns_ = nmap.get((sp, lnum[c]), set())
            letter = 'spdf'[lnum[c]]
            c = (f'{min(ns_)}{letter}' if len(ns_) == 1 else letter)
        new.append((f'{sp}-{c}' if c else sp) + suf)
    uniq = list(dict.fromkeys(new))
    M = np.zeros((len(names), len(uniq)))
    for i, v in enumerate(new):
        M[i, uniq.index(v)] = 1.0
    return uniq, M



def run_0d():
    import json as _j
    with open(os.path.join(OUT, 'levels.dat')) as f:
        h = f.readline().split(); grp = f.readline().split()[2:]
    ns = int(h[4])
    a = np.atleast_2d(np.loadtxt(os.path.join(OUT, 'levels.dat')))
    ng = len(grp)
    LE = [a[a[:, 0] == s + 1, 2] for s in range(ns)]
    LO = [a[a[:, 0] == s + 1, 3] for s in range(ns)]
    LW = [a[a[:, 0] == s + 1, 4:4 + ng] for s in range(ns)]
    _cg0, _cm0 = canon_groups(grp)                    # older engines: "H-s", "C-pxy" ... -> "H 1s", "C 2p"
    if _cg0 != list(grp):
        LW = [w @ _cm0 for w in LW]; grp = _cg0; ng = len(grp)
    fine0 = list(grp)                                  # (species, orbital) groups -> default view
    dv0 = 'atom' if len(dict.fromkeys(_gsplit(g)[2] for g in fine0)) > 1 else 'fine'
    grp = list(dict.fromkeys(view_names(fine0, dv0)))
    LWF = [np.asarray(w, float) for w in LW]          # (element, shell) weights, kept for the page views
    LW = [aggregate(fine0, w, dv0)[1] for w in LW]
    ng = len(grp)
    gcol = [XMG[i % len(XMG)] for i in range(ng)]
    homo, lumo = float(S['HOMO_eV']), float(S['LUMO_eV'])
    gap = float(S['overall_gap_eV'])
    deg = 2.0 if (nspin == 1 and not SOC) else 1.0
    allE = np.concatenate(LE)
    if EWIN:
        win = list(EWIN)
    else:
        win = [max(allE.min() - 0.5, homo - 7.0), min(allE.max() + 0.5, lumo + 6.0)]
    sig = 0.05
    ywin = (win[0], win[1] + 0.14 * (win[1] - win[0]))      # head-room for panel letters and legend
    Eg = np.arange(win[0], win[1] + 1e-9, 0.002)
    gauss = lambda e: np.exp(-0.5 * ((Eg[:, None] - e[None, :]) / sig) ** 2) / (sig * np.sqrt(2 * np.pi))
    DOS = [deg * gauss(LE[s]).sum(1) for s in range(ns)]
    PD = [deg * gauss(LE[s]) @ LW[s] for s in range(ns)]     # Mulliken weights may be slightly negative: never clipped, so the PDOS add up to the DOS
    # ---------------- checks (plotter side)
    VAL = []
    ref = eig_file()
    if ref is not None:
        ef, ev = ref
        dmax = 0.0; nn = 0
        for s in range(min(ns, len(ev))):
            m = min(len(ev[s]), len(LE[s]))
            dmax = max(dmax, float(np.max(np.abs(np.sort(LE[s])[:m] + EF - ev[s][:m])))); nn += m
        VAL.append(('PASS' if dmax < 1e-3 else 'FAIL', 'molecular levels vs SIESTA .EIG max|dE| (eV)', dmax,
                    f'{nn} levels at Gamma compared'))
        VAL.append(('PASS' if abs(ef - EF) < 1e-4 else 'WARN', 'E_F in .EIG vs HSX run (eV)', abs(ef - EF), ''))
    else:
        VAL.append(('SKIP', 'molecular levels vs SIESTA .EIG', 0.0, 'no .EIG file next to the fdf'))
    nel = sum(float(LO[s].sum()) for s in range(ns))
    VAL.append(('PASS' if abs(nel - float(S.get('n_electrons', nel))) < 1e-6 else 'FAIL',
                'sum of occupations - n_electrons', abs(nel - float(S.get('n_electrons', nel))), 'aufbau filling'))
    wsum = max(float(np.max(np.abs(LW[s].sum(1) - 1))) for s in range(ns))
    wlim = 1e-6 + 0.5e-6 * LW[0].shape[1]          # single precision + rounding of the 6 printed decimals
    VAL.append(('PASS' if wsum < wlim else ('WARN' if wsum < 1e-3 else 'FAIL'),
                'Mulliken weights sum to 1 (max deviation)', wsum, f'every level, limit {wlim:.1e}'))
    m = (Eg > win[0] + 6 * sig) & (Eg < win[1] - 6 * sig)
    pdev = max(float(np.max(np.abs(PD[s].sum(1) - DOS[s])[m])) / max(DOS[s].max(), 1e-12) for s in range(ns))
    VAL.append(('PASS' if pdev < 0.010 else 'FAIL', 'sum of PDOS = DOS (relative; limit 1 %)', pdev, 'Gaussian 0.05 eV'))
    try:
        dd = np.atleast_2d(np.loadtxt(os.path.join(OUT, 'dos.dat')))
        mm = (dd[:, 0] > win[0] + 6 * sig) & (dd[:, 0] < win[1] - 6 * sig)
        dE = max(float(np.max(np.abs(np.interp(dd[mm, 0], Eg, DOS[s] / deg) - dd[mm, 1 + s]))) for s in range(ns))
        dE /= max(float(dd[mm, 1:].max()), 1e-12)
        VAL.append(('PASS' if dE < 0.010 else 'FAIL', 'DOS: engine dos.dat vs plotter (relative; limit 1 %)', dE, 'same levels, same Gaussian'))
    except Exception as ex:
        VAL.append(('WARN', 'DOS: engine dos.dat vs plotter', 0.0, str(ex)[:60]))
    VAL.append(('PASS' if (gap > 0) == (lumo > homo) else 'FAIL', 'HOMO-LUMO gap = LUMO - HOMO (eV)', gap,
                f'HOMO {homo:.4f}, LUMO {lumo:.4f} eV'))
    with open(os.path.join(OUT, 'validation_plots.txt'), 'w') as f:
        for st, nm, v, nt in VAL:
            f.write(f'{st} | {nm} | {v:11.3e} | {nt}\n')
    rows = [l.rstrip('\n').split(' | ') for fn in ('validation.txt', 'validation_plots.txt')
            for l in open(os.path.join(OUT, fn)) if not l.startswith('#')]
    rows = [[r[0], r[1], r[2].strip(), r[3]] for r in rows if len(r) >= 4 and r[0] not in ('INFO', 'NOTE')]
    nf = sum(r[0] == 'FAIL' for r in rows); nw = sum(r[0] == 'WARN' for r in rows)
    vd = 'ALL CHECKS PASSED' if nf == 0 and nw == 0 else f'{nf} FAIL, {nw} WARN'
    shell = S.get('spin1_type', '')
    ttl = f'{LABEL}: HOMO–LUMO gap {gap:.3f} eV, {shell}'
    if 'magnetic_moment_muB' in S:
        ttl += f', m = {float(S["magnetic_moment_muB"]):.2f} μ$_B$'
    saved = []

    glyph0 = []

    def sv(fig, name):
        import warnings
        for ext in ('png', 'pdf'):
            with warnings.catch_warnings(record=True) as wl:
                warnings.simplefilter('always')
                fig.savefig(os.path.join(FIG, f'{name}.{ext}'))
            with open(os.path.join(FIG, 'MANIFEST.txt'), 'a') as _m:
                _m.write(f'{name}.{ext}\n')
            glyph0.extend(f'{name}: ' + str(w.message)[:60] for w in wl if 'missing from font' in str(w.message))
        plt.close(fig); saved.append(name.split('_')[0]); PROG.tick(1, name)

    def dom(w):
        return gcol[int(np.argmax(w))]

    def slots(s, x0, x1):
        """degenerate and near-degenerate levels (within 30 meV, closer than a line width) side by side,
        as in a molecular-orbital diagram, so that no level hides another"""
        o = np.argsort(LE[s]); out = {}; i = 0
        while i < len(o):
            j = i
            while j + 1 < len(o) and LE[s][o[j + 1]] - LE[s][o[j]] < 0.03:
                j += 1
            nd = j - i + 1; wd = (x1 - x0) / nd
            for m in range(nd):
                out[o[i + m]] = (x0 + m * wd + 0.04 * wd * (nd > 1), x0 + (m + 1) * wd - 0.04 * wd * (nd > 1))
            i = j + 1
        return out

    def levels(ax, s, x0=0.08, x1=0.92):
        sl = slots(s, x0, x1)
        for n, (e, o, w) in enumerate(zip(LE[s], LO[s], LW[s])):
            if win[0] <= e <= win[1]:
                ax.plot(sl[n], [e, e], color=dom(w), lw=3.2 if o > 1e-6 else 2.2,
                        ls='-' if o > 1e-6 else (0, (4, 2)), solid_capstyle='butt')
        ax.axhline(0, color='r', ls=(0, (6, 3)), lw=2.0)
        ax.set_xlim(0, 1); ax.set_ylim(*ywin); ax.set_xticks([])

    def gaparrow(ax, x=0.5):
        if lumo > homo:
            ax.annotate('', xy=(x, lumo), xytext=(x, homo), arrowprops=dict(arrowstyle='<|-|>', color=ARROW, lw=2.4,
                                                                            shrinkA=0, shrinkB=0))
            ax.text(x + 0.03, 0.5 * (homo + lumo) + 0.04 * (win[1] - win[0]), f'{gap:.3f} eV', color=ARROW, fontsize=15, va='center', zorder=30,
                    bbox=dict(fc='white', ec='none', pad=1))
            ax.text(0.97, homo, 'HOMO', ha='right', va='top', fontsize=13)
            ax.text(0.97, lumo, 'LUMO', ha='right', va='bottom', fontsize=13)

    def dosax(ax, s, sgn=1):
        for g in range(ng):
            ax.plot(sgn * PD[s][:, g], Eg, color=gcol[g], lw=2.2)
        ax.plot(sgn * DOS[s], Eg, color='k', lw=2.4)
        ax.axhline(0, color='r', ls=(0, (6, 3)), lw=2.0)
        ax.set_ylim(*ywin)

    dmx = 1.08 * max(d.max() for d in DOS)
    leg = [Line2D([], [], color='k', lw=3, label='Total')] + [Line2D([], [], color=c, lw=3, label=n) for c, n in zip(gcol, grp)]
    # ---------------- figure 0: validation
    with mpl.rc_context(dict(XG_RC, **{'font.size': 13, 'axes.labelsize': 16, 'xtick.labelsize': 13, 'ytick.labelsize': 13})):
        fig = plt.figure(figsize=(11.6, 10.8), layout='constrained')
        gs = fig.add_gridspec(2, 2, height_ratios=[1, 0.85])
        ax = fig.add_subplot(gs[0, 0])
        if ref is not None:
            for s in range(min(ns, len(ref[1]))):
                m_ = min(len(ref[1][s]), len(LE[s]))
                ax.plot(ref[1][s][:m_] - EF, np.sort(LE[s])[:m_], 'o', ms=6, mfc='none', mew=1.6,
                        color=['#0000FF', '#FF0000'][s], label=['spin 1', 'spin 2'][s] if ns == 2 else 'levels')
            lim = [allE.min() - 1, allE.max() + 1]; ax.plot(lim, lim, 'k-', lw=1)
            ax.set_xlim(lim); ax.set_ylim(lim); ax.legend(loc='upper left', frameon=True, edgecolor='k', fancybox=False)
        else:
            ax.text(0.5, 0.5, 'no .EIG file', ha='center', transform=ax.transAxes)
        ax.set_xlabel('SIESTA .EIG − E$_F$ (eV)'); ax.set_ylabel('this code (eV)')
        ax.set_title('(a) levels vs SIESTA .EIG')
        ax = fig.add_subplot(gs[0, 1])
        if ref is not None:
            for s in range(min(ns, len(ref[1]))):
                m_ = min(len(ref[1][s]), len(LE[s]))
                ax.semilogy(np.arange(1, m_ + 1), np.abs(np.sort(LE[s])[:m_] + EF - ref[1][s][:m_]) + 1e-9, 'o-',
                            color=['#0000FF', '#FF0000'][s], ms=4, lw=1.2)
            ax.axhline(1e-3, color='gray', ls='--', lw=1.2); ax.text(1, 1.4e-3, 'tolerance 1 meV', fontsize=12)
            ax.set_ylim(1e-9, 1e-1)
        ax.set_xlabel('level index'); ax.set_ylabel('|ΔE| (eV)'); ax.set_title('(b) deviation per level')
        ax = fig.add_subplot(gs[1, :]); ax.axis('off')
        col = {'PASS': '#1a7f37', 'FAIL': '#cf222e', 'WARN': '#bf8700', 'SKIP': '#777777', 'INFO': '#777777'}
        y = 0.98
        ax.text(0.0, y, f'(c) checks: {vd}', fontsize=15, fontweight='bold', va='top'); y -= 0.1
        for r in rows[:14]:
            ax.text(0.0, y, r[0], color=col.get(r[0], 'k'), fontsize=12, fontweight='bold', va='top', family='monospace')
            ax.text(0.08, y, r[1][:62], fontsize=12, va='top', fontweight='normal')
            ax.text(0.70, y, r[2], fontsize=12, va='top', family='monospace', fontweight='normal')
            y -= 0.075
        fig.suptitle(f'{LABEL}: validation (0D molecule, levels at Γ)', fontsize=19, fontweight='bold')
        sv(fig, '0_validation')
    # ---------------- figure 1: levels + DOS (xmgrace style)
    with mpl.rc_context(XG_RC):
        if ns == 2:
            fig, axs = plt.subplots(1, 4, figsize=(13.0, 10.4), sharey=True, layout='constrained',
                                    gridspec_kw=dict(width_ratios=[1, 1.15, 1.15, 1]))
            dosax(axs[0], 0, -1); axs[0].set_xlim(-dmx, 0); axs[0].set_title('Spin Up')
            levels(axs[1], 0); gaparrow(axs[1]); levels(axs[2], 1); gaparrow(axs[2])
            axs[1].set_title('levels ↑'); axs[2].set_title('levels ↓')
            dosax(axs[3], 1, 1); axs[3].set_xlim(0, dmx); axs[3].set_title('Spin Down')
            axs[0].set_ylabel('Energy (eV)'); axs[0].set_xlabel('DOS (1/eV)'); axs[3].set_xlabel('DOS (1/eV)')
            axs[3].legend(handles=leg, loc='upper right', frameon=True, fancybox=False, edgecolor='k', framealpha=1)
        else:
            fig, axs = plt.subplots(1, 2, figsize=(11.2, 10.4), sharey=True, layout='constrained',
                                    gridspec_kw=dict(width_ratios=[1.25, 1]))
            levels(axs[0], 0); gaparrow(axs[0]); axs[0].set_ylabel('Energy (eV)')
            axs[0].set_xlabel('molecular levels (Γ)')
            dosax(axs[1], 0); axs[1].set_xlim(0, dmx); axs[1].set_xlabel('DOS (1/eV)')
            axs[1].legend(handles=leg, loc='upper right', frameon=True, fancybox=False, edgecolor='k', framealpha=1)
        for i, a_ in enumerate(axs):
            a_.text(0.04, 0.985, f'({"abcd"[i]})', transform=a_.transAxes, va='top', fontsize=19, fontweight='bold',
                    bbox=dict(boxstyle='round,pad=0.15', fc='white', ec='none', alpha=0.85), zorder=50)
        fig.suptitle(f'{LABEL}: Molecular Levels and DOS', fontsize=22, fontweight='bold')
        fig.text(0.5, -0.005, wrapc(ttl.split(': ', 1)[1].replace('μ$_B$', 'μB') + '. Solid: occupied, dashed: empty; levels within 30 meV drawn side by side; '
                 f'colour = dominant Mulliken projection. DOS: Gaussian σ = {sig} eV' +
                 (', 2 electrons per level (spin-degenerate)' if deg == 2 else '') + '. Energies relative to E_F (SIESTA) = '
                 f'{EF:.4f} eV.', 140), ha='center', va='top', fontsize=12, fontweight='normal')
        sv(fig, '1_levels_dos')
    # ---------------- figure 1b: projected levels (bar split by weight) + stacked PDOS
    with mpl.rc_context(XG_RC):
        fig, axs = plt.subplots(1, 1 + ns, figsize=(11.6 if ns == 1 else 13.2, 10.4), sharey=True, layout='constrained',
                                gridspec_kw=dict(width_ratios=[1.25] * ns + [1]))
        for s in range(ns):
            ax = axs[s]
            sl = slots(s, 0.06, 0.94)
            for n, (e, o, w) in enumerate(zip(LE[s], LO[s], LW[s])):
                if not win[0] <= e <= win[1]:
                    continue
                x, L_ = sl[n][0], sl[n][1] - sl[n][0]; w = np.clip(w, 0, None); w = w / max(w.sum(), 1e-12)
                for g in range(ng):
                    ax.plot([x, x + L_ * w[g]], [e, e], color=gcol[g], lw=5 if o > 1e-6 else 3.2, solid_capstyle='butt')
                    x += L_ * w[g]
            ax.axhline(0, color='r', ls=(0, (6, 3)), lw=2.0); ax.set_xlim(0, 1); ax.set_xticks([]); ax.set_ylim(*ywin)
            ax.set_xlabel('projection (fraction of level)')
            if ns == 2:
                ax.set_title('Spin Up' if s == 0 else 'Spin Down')
        axs[0].set_ylabel('Energy (eV)')
        ad = axs[-1]
        for s in range(ns):
            base = np.zeros_like(Eg); sg = -1 if (ns == 2 and s == 1) else 1
            for g in range(ng):
                ad.fill_betweenx(Eg, sg * base, sg * (base + PD[s][:, g]), color=gcol[g], alpha=0.85, lw=0)
                base = base + PD[s][:, g]
            ad.plot(sg * DOS[s], Eg, color='k', lw=1.8)
        ad.axhline(0, color='r', ls=(0, (6, 3)), lw=2.0)
        ad.set_xlim(-dmx if ns == 2 else 0, dmx); ad.set_xlabel('PDOS (1/eV)')
        ad.legend(handles=leg, loc='upper right', frameon=True, fancybox=False, edgecolor='k', framealpha=1)
        for i, a_ in enumerate(axs):
            a_.text(0.04, 0.985, f'({"abc"[i]})', transform=a_.transAxes, va='top', fontsize=19, fontweight='bold',
                    bbox=dict(boxstyle='round,pad=0.15', fc='white', ec='none', alpha=0.85), zorder=50)
        fig.suptitle(f'{LABEL}: Projected Molecular Levels', fontsize=22, fontweight='bold')
        fig.text(0.5, -0.005, wrapc('Each level is split into its Mulliken projections (bar length = weight; thick: occupied, '
                 'thin: empty). Right: stacked PDOS, Gaussian σ = 0.05 eV.', 140), ha='center', va='top', fontsize=12,
                 fontweight='normal')
        sv(fig, '1b_projected_levels')
    # ---------------- HTML
    hp = None
    try:
        r4 = lambda v: np.round(np.asarray(v, float), 4).tolist()
        r6 = lambda v: np.round(np.asarray(v, float), 6).tolist()
        # page projections of the levels: atoms (default), atom + shell ("C 2p", "H 1s"), shell letter only
        lv_views = []
        for vk, vl in (('atom', 'atoms (total + each element)'), ('fine', 'atom + orbital (e.g. C 2p, H 1s)'),
                       ('orb', 'orbital only (s, p, d of all atoms)')):
            nmv = aggregate(fine0, LWF[0], vk)[0]
            lv_views.append(dict(key=vk, label=vl, names=nmv, col=[XMG[i % len(XMG)] for i in range(len(nmv))],
                                 w=[r6(aggregate(fine0, LWF[s], vk)[1]) for s in range(ns)]))
        ctx = dict(label=LABEL, title=ttl.replace('μ$_B$', 'μB'), EF=EF, dim=0, summary=S, codename='BandQPI-3D',
                   version=VERSION, groups=grp, gcol=gcol,
                   levels=dict(E=[r4(LE[s]) for s in range(ns)], occ=[r4(LO[s]) for s in range(ns)],
                               w=[r4(LW[s]) for s in range(ns)], groups=grp, gcol=gcol, homo=homo, lumo=lumo,
                               win=[round(win[0], 2), round(win[1], 2)], deg=deg,
                               views=lv_views))
        hp = html_build(ctx, OUT)
        PROG.tick(1, 'interactive page')
    except Exception as ex:
        PROG.close()
        import traceback; traceback.print_exc()
        print('  (interactive HTML skipped:', ex, ')')
    with open(os.path.join(FIG, 'CAPTIONS.md'), 'w') as f:
        f.write(f'# Figure captions for {LABEL} (0D molecule / cluster)\n\n{ttl.replace("μ$_B$", "μB")}. Energies relative to '
                f'the SIESTA Fermi level E_F = {EF:.4f} eV. A molecule has no Brillouin zone: the levels are the eigenvalues '
                'of H c = E S c at Γ (supercell with vacuum), filled by the aufbau principle at T = 0.\n\n'
                '**Fig. 0 (0_validation).** (a) levels vs SIESTA .EIG; (b) deviation per level; (c) all checks.\n\n'
                '**Fig. 1 (1_levels_dos).** Level diagram (solid occupied, dashed empty; colour = dominant Mulliken '
                'projection; arrow: HOMO–LUMO gap) and DOS / PDOS (Gaussian 0.05 eV).\n\n'
                '**Fig. 1b (1b_projected_levels).** Each level split into its projections; stacked PDOS.\n\n'
                'Bands, 3D surfaces, contours and QPI need periodicity and are not produced for 0D systems.\n')
    gl = sorted(set(glyph0))
    with open(os.path.join(OUT, 'validation_plots.txt'), 'a') as f:
        f.write(f"{'PASS' if not gl else 'FAIL'} | every character in the figures drawn by the font (no empty boxes) | "
                f"{float(len(gl)):11.3e} | {'; '.join(gl)[:150] or 'all text rendered'}\n")
    if gl:
        nf += 1
        vd = f'{nf} FAIL, {nw} WARN'
    with open(os.path.join(OUT, 'validation_report.txt'), 'w') as f:
        f.write(f'siesta3d validation report: {LABEL}\n{"=" * 100}\nverdict: {vd}\n\n')
        write_check_sections(f)
        f.write('=== METHOD ===\n0D (molecule / cluster): one k-point (Γ) of the SIESTA supercell. Levels: eigenvalues of the '
                'generalised problem H c = E S c (LAPACK zhegvx) of the self-consistent HSX matrices; occupations by the '
                'aufbau principle at T = 0 for the SIESTA electron count; HOMO / LUMO from the filling; Mulliken weights '
                'w_mu = Re(c_mu^* (S c)_mu) summed over each group; DOS / PDOS = levels broadened by a Gaussian of 0.05 eV.\n\n')
        f.write('=== 3. INDEPENDENT AUDIT (siesta3d_audit.py: re-reads the raw files, does not use the plotting code) ===\n'
                'not run yet\n')
    PROG.tick(1, 'validation report')
    with open(os.path.join(OUT, 'figure_axes.json'), 'w') as f:
        _j.dump(dict(dim=0, units='eV', window=win, homo=homo, lumo=lumo, drawn_in=saved), f, indent=1)
    PROG.done = PROG.total; PROG.close(final=True)
    print(f'  figures (PNG + PDF)      : {" ".join(saved)}   (folder figures/)')
    if hp:
        print(f'  interactive page         : {os.path.relpath(hp)}  (any web browser)')
    print(f'  validation               : {vd}   (validation_report.txt)')


def wrapc(t, n=130):
    import textwrap
    return '\n'.join(textwrap.wrap(t, n))


if DIM == 0:
    run_0d()
    sys.exit(0)


PH = header(os.path.join(OUT, 'path.dat'))
PA = np.atleast_2d(np.loadtxt(os.path.join(OUT, 'path.dat')))
NB, NODD = PH['nbands'], PH.get('nodd', 0)
PX, PKX, PKY, PKN = PA[:, 0], PA[:, 1], PA[:, 2], PA[:, 3]
PE = PA[:, 4:4 + nspin * NB].reshape(len(PA), nspin, NB) - EF
PEO = PA[:, 4 + nspin * NB:].reshape(len(PA), nspin, NODD) - EF if NODD else None

# Spin channels identical? The engine decides this (largest |E_up - E_dn| on the path < 2 meV). Folders written by
# an older siesta3d.x used 0.1 meV, so a non-magnetic hybrid-functional run (residual 0.6 meV) was taken as a magnet.
# The same rule is applied here, so every folder is shown correctly whichever engine wrote it.
PRENOTES = []
if S.get('engine_version') not in ('1.0',):
    PRENOTES.append(('NOTE', 'folder written by an older siesta3d.x (before v1.0): rebuild (bash install.sh) and run it again', 0.0,
                     'shown correctly here; the new engine also gives exact bin-averaged DOS and element + n l shells'))
SPIN_SPLIT = float(np.nanmax(np.abs(PE[:, 0] - PE[:, 1]))) if (nspin == 2 and not SOC) else 0.0
DEG_PY = False
if nspin == 2 and not SOC and not DEG and SPIN_SPLIT < 2e-3:
    DEG, DEG_PY, SP, TOTF = True, True, [0], 2
    PRENOTES.append(('NOTE', 'spin channels identical within 2 meV (non-magnetic): shown once, DOS = sum of both spins',
                     SPIN_SPLIT, 'decided by the plotter: this folder was written by an older siesta3d.x'))
NODES = PH['nodes']
# k-path axis: SIESTA writes .bands in Bohr^-1; default to the same units so that every tick value
# can be compared directly with the node list at the end of <label>.bands  (--kunits=ang for Å^-1)
BOHR = 0.529177210903
KUNITS = OPT.get('kunits', 'bohr').lower()
KS = BOHR if KUNITS.startswith('bohr') else 1.0
KLAB = 'Bohr$^{-1}$' if KS != 1.0 else 'Å$^{-1}$'
KLAB_TXT = 'Bohr⁻¹' if KS != 1.0 else 'Å⁻¹'
PX = PX * KS
NODES = [(x * KS, l) for x, l in NODES]
AXREC = dict(units=KLAB_TXT, nodes=[], labels=[], drawn_in=[])
BSET = 'pi' if PLANAR else 'index'
NAME = {'pi': (r'$\pi$', r'$\pi^*$'), 'index': ('VB', 'CB')}
NOCC = [int(S.get(f'spin{s + 1}_nocc', S.get('spin1_nocc', '1'))) for s in range(2)]

# projections (Mulliken weights) along the path and projected DOS
PROJ = None
fp = os.path.join(OUT, 'path_proj.dat')
if os.path.exists(fp):
    hp = header(fp)
    GRP = hp.get('groups', ['all'])
    ng, plo, phi = hp['ngrp'], hp['band_lo'], hp['band_hi']
    W = np.loadtxt(fp).reshape(len(PA), nspin, phi - plo + 1, ng)          # [k, spin, band, group]
    PROJ = dict(lo=plo, hi=phi, W=np.clip(W, 0, None))
else:
    GRP = ['all']
haveDOS = os.path.exists(os.path.join(OUT, 'dos.dat'))
D = np.loadtxt(os.path.join(OUT, 'dos.dat')) if haveDOS else None
PD = None
if os.path.exists(os.path.join(OUT, 'pdos.dat')):
    PD = np.loadtxt(os.path.join(OUT, 'pdos.dat'))
    PD = (PD[:, 0], PD[:, 1:].reshape(len(PD), nspin, len(GRP)))          # E, [E, spin, group]

_cg, _CM = canon_groups(GRP)
if _cg != list(GRP):
    PRENOTES.append(('NOTE', 'projection groups of an older siesta3d.x merged to element + shell (no px / py / pz)', 0.0,
                     ', '.join(GRP) + ' -> ' + ', '.join(_cg)))
    if PROJ is not None:
        PROJ['W'] = PROJ['W'] @ _CM
    if PD is not None:
        PD = (PD[0], PD[1] @ _CM)
    GRP = _cg
if DEG_PY:                                         # identical spins: both channels -> their mean (x2 = exact total)
    if haveDOS:
        D[:, 1:3] = 0.5 * (D[:, 1:2] + D[:, 2:3])
    if PD is not None:
        PD = (PD[0], np.repeat(0.5 * PD[1].sum(1, keepdims=True), 2, axis=1))
    if PROJ is not None:
        PROJ['W'] = np.repeat(0.5 * PROJ['W'].sum(1, keepdims=True), 2, axis=1)

# ---- projection views. The engine writes one group per (element, n, l) shell of SIESTA's basis: "Cr-3d",
# "Cr-4s", "O-2p", "H-1s" (spin-orbit: "..._up" / "..._dn"). Three views are built from them by exact sums:
#   atom : per element (figure 1, page default)   fine : element + shell, "Cr 3d" (fat bands)   orb : s, p, d
FINE_GRP = list(GRP)
NSPEC = len(dict.fromkeys(_gsplit(g)[2] for g in GRP))
DEFVIEW = 'fine'          # band projections (fat bands, band colours): element and shell, e.g. Cr 3d
FINE_PD = PD                                      # (E, [E, spin, fine group]) kept for the interactive page
if PROJ is not None:
    _g, PROJ['W'] = aggregate(FINE_GRP, PROJ['W'], DEFVIEW)
if PD is not None:
    _g, _p = aggregate(FINE_GRP, PD[1], DEFVIEW); PD = (PD[0], _p)
GRP = list(dict.fromkeys(view_names(FINE_GRP, DEFVIEW)))

# spin-orbit: every group comes as <name>_up / <name>_dn (spinor components). Keep both and
# also the sum, so that all other figures use the plain species / orbital groups.
SOCSPIN = None
if SOC and len(GRP) % 2 == 0 and all(g.endswith('_up') for g in GRP[:len(GRP) // 2]):
    n2 = len(GRP) // 2
    GRP = [g[:-3] for g in GRP[:n2]]
    SOCSPIN = {}
    if PROJ is not None:
        Wf = PROJ['W']
        SOCSPIN['Wup'], SOCSPIN['Wdn'] = Wf[:, 0, :, :n2], Wf[:, 0, :, n2:]        # [k, band, group]
        PROJ['W'] = Wf[..., :n2] + Wf[..., n2:]
    if PD is not None:
        SOCSPIN['PDup'], SOCSPIN['PDdn'] = PD[1][:, 0, :n2], PD[1][:, 0, n2:]
        PD = (PD[0], (PD[1][:, :, :n2] + PD[1][:, :, n2:]))
SZ = None          # spin-orbit: spin character <sigma_z> of every state on the path [k, band - lo + 1]
if SOCSPIN is not None and 'Wup' in SOCSPIN:
    _wu, _wd = SOCSPIN['Wup'].sum(-1), SOCSPIN['Wdn'].sum(-1)
    SZ = (_wu - _wd) / np.maximum(_wu + _wd, 1e-9)


def soc_mask(b, char):
    """spin-orbit: per k-segment of band b (0-based), True where the state has the spin character
    char (+1: <sz> >= 0, 'spin up'; -1: <sz> < 0, 'spin down'); None if b has no weights"""
    lo = PROJ['lo'] if PROJ else 1
    if SZ is None or not (lo - 1 <= b < lo - 1 + SZ.shape[1]):
        return None
    z = SZ[:, b - (lo - 1)]
    zm = 0.5 * (z[:-1] + z[1:])                     # segment i joins k_i and k_i+1
    return zm >= 0 if char > 0 else zm < 0
    GRP = [g[:-4] + '-p' if i == ixy else g for i, g in enumerate(GRP) if i != iz]
GCOL = [XMG[i % len(XMG)] for i in range(len(GRP))]


def nodelabel(l):
    return r'$\Gamma$' if l.upper() in ('G', 'Γ', 'GAMMA', '\\GAMMA') else l


def title_text(short=False):
    ty = S.get('spin1_type', '')
    g = float(S.get('overall_gap_eV', 0))
    ty2 = S.get('spin2_type', '') if (nspin == 2 and not SOC and not DEG) else ''
    if ty2 and (('insulator' in ty) != ('insulator' in ty2)):
        k = 2 if 'insulator' in ty2 else 1                 # the gapped channel
        try:
            gk = float(S[f'spin{k}_CBM_E_k'].split()[0]) - float(S[f'spin{k}_VBM_E_k'].split()[0])
            t = f'half-metal (spin {"↓" if k == 2 else "↑"} gap {gk:.3f} eV)'
        except (KeyError, ValueError, IndexError):
            t = 'half-metal'
    elif ty2 and 'insulator' not in ty and 'insulator' not in ty2:
        t = 'metal'
    elif ty.startswith('metal'):
        t = 'metal' + (' (doped Dirac cone)' if 'Dirac' in ty else '')
    elif g < 0.02:
        t = 'gapless (Dirac semimetal)'
    else:
        t = f'gap {g:.3f} eV ({S.get("gap_type", "")})'
    if SOC:
        t += ', spin–orbit coupled' + ('' if TRS else ', magnetic (time reversal broken)')
    if DIM == 3:
        t += ', 3D crystal'
    if 'magnetic_moment_muB' in S and not DEG:
        t += f', m = {float(S["magnetic_moment_muB"]):.2f} μ$_B$'
    if DEG:
        t += ', non-magnetic (spins identical)'
    return t if short else f'{LABEL}: {t}'


SAVED = []


GLYPHS = []                                       # characters a figure font could not draw (would show as boxes)


def save(fig, name):
    import warnings
    for ext in ('png', 'pdf'):
        with warnings.catch_warnings(record=True) as wl:
            warnings.simplefilter('always')
            fig.savefig(os.path.join(FIG, f'{name}.{ext}'))
        with open(os.path.join(FIG, 'MANIFEST.txt'), 'a') as _m:
            _m.write(f'{name}.{ext}\n')
        GLYPHS.extend(f'{name}: ' + re.sub(r'\s+', ' ', str(w.message))[:60] for w in wl if 'missing from font' in str(w.message))
    plt.close(fig)
    SAVED.append(name.split('_')[0])
    PROG.tick(1, name)


def letter(ax, c, color='k', x=0.025, y=0.975):
    box = dict(boxstyle='round,pad=0.15', fc='white', ec='none', alpha=0.85) if color == 'k' else None
    ax.text(x, y, f'({c})', transform=ax.transAxes, fontsize=12, fontweight='bold', va='top', ha='left',
            color=color, zorder=60, bbox=box)


CM = {(0, 'v'): 'Blues', (0, 'c'): 'Reds', (1, 'v'): 'Greens', (1, 'c'): 'Oranges'}
LC = {0: ('#1f4e9c', '#b2182b'), 1: ('#1b7837', '#d95f02')}


def cmap_part(name, lo=0.3, hi=0.95):
    return mpl.colors.ListedColormap(mpl.colormaps[name](np.linspace(lo, hi, 256)))


def clean3d(ax):
    ax.grid(False)
    for axis in (ax.xaxis, ax.yaxis, ax.zaxis):
        axis.pane.fill = False
        axis.pane.set_edgecolor((0, 0, 0, 0))
    ax.set_xlabel(r'$k_x$ (Å$^{-1}$)', labelpad=6)
    ax.set_ylabel(r'$k_y$ (Å$^{-1}$)', labelpad=6)
    ax.set_zlabel(r'$E-E_F$ (eV)', labelpad=6)
    r = np.ptp(ax.get_xlim()) / max(np.ptp(ax.get_ylim()), 1e-12)
    ax.xaxis.set_major_locator(MaxNLocator(2 if r < 0.45 else (3 if r < 0.75 else 4)))
    ax.yaxis.set_major_locator(MaxNLocator(2 if r > 2.2 else (3 if r > 1.35 else 4)))
    ax.zaxis.set_major_locator(MaxNLocator(5))


def box_aspect(ax, G):
    dx, dy = np.ptp(G.kx), np.ptp(G.ky)
    m = max(dx, dy)
    ax.set_box_aspect((max(dx / m, 0.4), max(dy / m, 0.4), 0.85), zoom=0.92)


# ------------------------------------------------------------------ geometry helpers
def in_bz(kx, ky, tol=1e-4):
    k = np.stack([np.atleast_1d(kx), np.atleast_1d(ky)], -1)
    ok = np.ones(k.shape[:-1], bool)
    for n1 in range(-2, 3):
        for n2 in range(-2, 3):
            if n1 == 0 and n2 == 0:
                continue
            g = n1 * Bm[0] + n2 * Bm[1]
            ok &= k @ g <= 0.5 * g @ g * (1 + tol)
    return ok


def fold(kx, ky):
    """fold points OUTSIDE the first zone back (points on the boundary stay put)"""
    k = np.stack([np.atleast_1d(kx), np.atleast_1d(ky)], -1).astype(float)
    out = ~in_bz(k[:, 0], k[:, 1])
    for i in np.where(out)[0]:
        best, bn = k[i].copy(), np.inf
        for n1 in range(-3, 4):
            for n2 in range(-3, 4):
                kk = k[i] + n1 * Bm[0] + n2 * Bm[1]
                if in_bz(kk[0], kk[1])[0] and np.linalg.norm(kk) < bn - 1e-9:
                    best, bn = kk, np.linalg.norm(kk)
        k[i] = best
    return k[:, 0], k[:, 1]


def shift_near(kx, ky, c):
    """for each point choose k + G (and -k + G only if time reversal holds) closest to c"""
    P = np.c_[kx, ky]; best = P.copy(); bd = np.linalg.norm(P - c, axis=1)
    for sgn in ((1, -1) if TRS else (1,)):
        for n1 in range(-3, 4):
            for n2 in range(-3, 4):
                Q = sgn * P + n1 * Bm[0] + n2 * Bm[1]
                d = np.linalg.norm(Q - c, axis=1); m = d < bd - 1e-9
                best[m] = Q[m]; bd[m] = d[m]
    return best[:, 0], best[:, 1]


def path_band(s, rel, bset):
    """band NOCC + rel along the path, or None when that band does not exist (one-band models,
    an empty or a completely filled spin channel)"""
    if bset == 'pi' and PEO is not None:
        b, arr = BZ.nocc_o[s] + rel - 1, PEO
    else:
        b, arr = NOCC[s] + rel - 1, PE
    return arr[:, s, b] if 0 <= b < arr.shape[-1] else None


def path_in_plane(G):
    if DIM == 2:
        return np.ones(len(PX), bool)
    return np.abs(PKN - G.offset) < 1e-4


def path_axes(ax, ylim):
    for xn, _ in NODES:
        ax.axvline(xn, color='0.75', lw=0.6, zorder=0)
    ax.axhline(0, color='0.35', ls='--', lw=0.7, zorder=0)
    ax.set_xticks([n[0] for n in NODES]); ax.set_xticklabels([nodelabel(l) for _, l in NODES])
    ax.set_xlim(PX[0], PX[-1]); ax.set_ylim(*ylim)
    ax.tick_params(axis='x', top=False)


# ------------------------------------------------------------------ 3D drawing
def draw(ax, G, spins, rels, bset, style='bands', mesh=False, efplane=False, outline=False,
         kpath=None, contour=False, alpha=1.0, cnorm=None):
    zs = []
    for s in spins:
        for rel in rels:
            Z = G.band(s, rel, bset)
            if Z is None:
                continue
            kind = 'v' if rel <= 0 else 'c'
            a = alpha if rel in (0, 1) else 0.55 * alpha
            kw = dict(rstride=1, cstride=1, antialiased=False, alpha=a, linewidth=0)
            cmo = PARULA if style == 'parula' else cmap_part(CM[(s, kind)])
            nrm = cnorm if (style == 'parula' and cnorm is not None) else Normalize(np.nanmin(Z), np.nanmax(Z) + 1e-9)
            if mesh:
                st_ = max(1, int(np.ceil(max(Z.shape) / 90)))
                rgba = cmo(nrm(Z))
                dx = np.nanmean(np.abs(np.diff(G.kx, axis=1))) or 1.0
                dy = np.nanmean(np.abs(np.diff(G.ky, axis=0))) or 1.0
                rgba[..., :3] = ls.shade_rgb(rgba[..., :3], Z, blend_mode='soft', vert_exag=0.6, dx=dx, dy=dy)
                kw.update(rstride=st_, cstride=st_, linewidth=0.25, edgecolor=(0, 0, 0, 0.45))
                ax.plot_surface(G.kx, G.ky, Z, facecolors=rgba, shade=False, **kw)
            else:
                ax.plot_surface(G.kx, G.ky, Z, cmap=cmo, norm=nrm, shade=True, lightsource=ls, **kw)
            zs.append((np.nanmin(Z), np.nanmax(Z)))
    if not zs:
        return
    z0, z1 = min(z[0] for z in zs), max(z[1] for z in zs)
    pad = 0.04 * (z1 - z0 + 1e-9)
    if contour:
        for s in spins:
            for rel in rels:
                Z = G.band(s, rel, bset)
                if Z is not None:
                    ax.contour(G.kx, G.ky, Z, 12, zdir='z', offset=z0 - pad,
                               cmap=cmap_part(CM[(s, 'v' if rel <= 0 else 'c')]), linewidths=0.8)
    if outline and G.verts is not None:
        v = np.vstack([G.verts, G.verts[:1]])
        ax.plot(v[:, 0], v[:, 1], np.full(len(v), z0 - pad), color='0.3', lw=1.0)
    if efplane:
        x0, x1, y0, y1 = G.kx.min(), G.kx.max(), G.ky.min(), G.ky.max()
        ax.plot_surface(np.array([[x0, x1], [x0, x1]]), np.array([[y0, y0], [y1, y1]]),
                        np.zeros((2, 2)), color=(0.5, 0.5, 0.5), alpha=0.12, linewidth=0, shade=False)
    if kpath is not None:
        draw_path(ax, G, spins, rels, bset, kpath)
    ax.set_zlim(z0 - pad, z1 + pad)
    ax.set_xlim(G.kx.min(), G.kx.max()); ax.set_ylim(G.ky.min(), G.ky.max())
    box_aspect(ax, G)


def draw_path(ax, G, spins, rels, bset, mode):
    plane = path_in_plane(G)
    if mode == 'bz':
        kx, ky = fold(PKX, PKY)
    elif mode == 'zoom':
        kx, ky = shift_near(PKX, PKY, np.array([G.kx.mean(), G.ky.mean()]))
    else:
        kx, ky = PKX.copy(), PKY.copy()
    inside = plane & (kx >= G.kx.min() - 1e-6) & (kx <= G.kx.max() + 1e-6) & \
        (ky >= G.ky.min() - 1e-6) & (ky <= G.ky.max() + 1e-6)
    jump = np.r_[False, np.hypot(np.diff(kx), np.diff(ky)) > 0.25 * np.linalg.norm(Bm[0])]
    sr = [(s, r) for s in spins for r in rels if path_band(s, r, bset) is not None]
    if not sr:
        return
    for s, rel in sr:
        if True:
            e = path_band(s, rel, bset).astype(float).copy()
            xs, ys = kx.copy(), ky.copy()
            e[~inside] = np.nan; xs[jump | ~inside] = np.nan; ys[~inside] = np.nan
            ax.plot(xs, ys, e, color='k', lw=1.3, zorder=20)
    zr = [path_band(s, r, bset)[inside] for s, r in sr]
    zr = np.concatenate(zr) if zr else np.zeros(1)
    dz = 0.06 * (np.nanmax(zr) - np.nanmin(zr) + 1e-6) if zr.size else 0.3
    for xn, lab in NODES:
        i = np.argmin(abs(PX - xn))
        if inside[i]:
            ax.text(kx[i], ky[i], path_band(*max(sr, key=lambda x: x[1]), bset)[i] + dz, nodelabel(lab), fontsize=11)


# ------------------------------------------------------------------ coloured bands and PDOS
def band_colors(s, b):
    """RGB per path point of band b (0-based) of spin s: colour of the dominant projection"""
    if PROJ is None or not (PROJ['lo'] - 1 <= b <= PROJ['hi'] - 1):
        return None
    w = PROJ['W'][:, s, b - (PROJ['lo'] - 1), :]
    rgb = np.array([mpl.colors.to_rgb(c) for c in GCOL])
    return rgb[np.argmax(w, 1)]


def plot_bands(ax, ylim, lw=1.4, show_pi=True):
    for s in SP:
        lsty = '-' if s == 0 else (0, (4, 2))
        for b in range(NB):
            e = PE[:, s, b]
            if np.nanmax(e) < ylim[0] - 0.5 or np.nanmin(e) > ylim[1] + 0.5:
                continue
            col = band_colors(s, b)
            if col is None:
                ax.plot(PX, e, color='0.7', lw=0.8, ls=lsty, zorder=1)
                continue
            pts = np.c_[PX, e].reshape(-1, 1, 2)
            seg = np.concatenate([pts[:-1], pts[1:]], 1)
            ax.add_collection(LineCollection(seg, colors=col[:-1], linewidths=lw,
                                             linestyles=lsty, zorder=3, capstyle='round'))
        if PEO is not None and show_pi:
            for b in range(NODD):
                ax.plot(PX, PEO[:, s, b], color='k', lw=0.6, ls=':', zorder=4)


def plot_pdos(ax, ylim, horizontal=True, legend=True):
    """total DOS (grey) and projected DOS (group colours); spin down mirrored"""
    if not haveDOS:
        return
    E = D[:, 0]
    m = (E > ylim[0] - 0.2) & (E < ylim[1] + 0.2)
    xmax = 0.0
    for s in SP:
        sg = 1 if (s == 0 or len(SP) == 1) else -1
        tot = D[:, 1 + s] * (TOTF if len(SP) == 1 else 1)
        ax.fill_betweenx(E[m], 0, sg * tot[m], color='0.85', lw=0, zorder=1)
        ax.plot(sg * tot[m], E[m], color='0.25', lw=0.8, zorder=2, label='total' if s == SP[0] else None)
        xmax = max(xmax, tot[m].max())
        if PD is not None:
            for g, name in enumerate(GRP):
                p = PD[1][:, s, g] * (TOTF if len(SP) == 1 else 1)
                ax.plot(sg * p[m], PD[0][m], color=GCOL[g], lw=1.2, zorder=3, label=name if s == SP[0] else None)
    ax.axhline(0, color='0.35', ls='--', lw=0.7)
    ax.set_ylim(*ylim)
    ax.set_xlim(-1.05 * xmax if len(SP) == 2 else 0, 1.05 * xmax)
    if len(SP) == 2:
        ax.axvline(0, color='k', lw=0.6)
        ax.text(0.97, 0.02, '↑', transform=ax.transAxes, ha='right', fontsize=12)
        ax.text(0.03, 0.02, '↓', transform=ax.transAxes, ha='left', fontsize=12)
    ax.set_xlabel('DOS (states/eV/cell)')


def group_legend(ax, loc='upper right', ncol=1, title='projection'):
    h = [Line2D([], [], color=c, lw=3, label=n) for c, n in zip(GCOL, GRP)]
    h.append(Line2D([], [], color='0.25', lw=1, label='total DOS'))
    if PEO is not None:
        h.append(Line2D([], [], color='k', lw=0.8, ls=':', label=r'$\pi$ (mirror-odd)'))
    if len(SP) == 2:
        h.append(Line2D([], [], color='0.4', lw=1.2, ls='-', label='spin ↑'))
        h.append(Line2D([], [], color='0.4', lw=1.2, ls=(0, (4, 2)), label='spin ↓'))
    ax.legend(handles=h, loc=loc, ncol=ncol, frameon=True, framealpha=0.92, fontsize=8, title=title,
              title_fontsize=8)


g_ = float(S.get('overall_gap_eV', 0))
YL = max(4.0, g_ + 1.5)

# =================================================================== FIGURE 1: band structure + DOS
# Layout used in spin-polarised DFT papers (xmgrace / origin style):
#   [DOS spin up, mirrored] [bands spin up] [bands spin down] [DOS spin down]
# Spin-orbit runs: S_z is not conserved, so the two band panels show the SAME bands with the
# spin-up and spin-down spinor weight of each state; the DOS panels are the spinor-component PDOS.
from scipy.ndimage import gaussian_filter1d



def ewindow():
    """energy window of the band figures: symmetric about E_F, large enough to show the VBM and CBM of every
    spin channel that has a gap (a half-metal's insulating channel included) with 0.5 eV to spare; --ewin=lo,hi"""
    if EWIN is not None:
        return tuple(EWIN)
    g = float(S.get('overall_gap_eV', 0))
    h = max(2.0, np.ceil((g / 2 + 1.3) * 2) / 2)
    edges = []
    for s_ in (1, 2):
        if f'spin{s_}_VBM_E_k' in S and 'insulator' in S.get(f'spin{s_}_type', 'insulator'):
            edges += [abs(float(S[f'spin{s_}_VBM_E_k'].split()[0])), abs(float(S[f'spin{s_}_CBM_E_k'].split()[0]))]
    for t_ in ('up', 'dn'):
        if f'soc_{t_}_VBM_E_k' in S:
            edges += [abs(float(S[f'soc_{t_}_VBM_E_k'].split()[0])), abs(float(S[f'soc_{t_}_CBM_E_k'].split()[0]))]
    # the band edges ON THE PATH as well: a path that misses the true VBM / CBM must still show its bands
    try:
        for s_ in range(PE.shape[1]):
            n_ = int(NOCC[s_])
            if 0 < n_ < PE.shape[2] and 'insulator' in S.get(f'spin{s_ + 1}_type', 'insulator'):
                edges += [abs(float(np.nanmax(PE[:, s_, n_ - 1]))), abs(float(np.nanmin(PE[:, s_, n_])))]
    except (NameError, IndexError, TypeError, ValueError):
        pass
    edges = [e for e in edges if e < 6.0]
    if edges:
        h = max(h, np.ceil((max(edges) + 0.5) * 2) / 2)
    return (-h, h)


def smooth(y, E):
    if SMEAR <= 0:
        return y
    return gaussian_filter1d(y, SMEAR / (E[1] - E[0]), axis=0, mode='nearest')


def spin_channels():
    """[(title, band-spin index, weight array [k, band, group] or None, (tot, pdos[E, group]))]"""
    if not haveDOS:
        return []
    E = D[:, 0]
    if SOCSPIN is not None and 'PDup' in SOCSPIN:
        ch = []
        for t, wk, pk in (('Spin Up', 'Wup', 'PDup'), ('Spin Down', 'Wdn', 'PDdn')):
            pd = SOCSPIN[pk]
            ch.append((t, 0, SOCSPIN.get(wk), (pd.sum(1), pd)))
        return ch
    if len(SP) == 2:
        return [(['Spin Up', 'Spin Down'][s], s, PROJ['W'][:, s] if PROJ else None,
                 (D[:, 1 + s], PD[1][:, s, :] if PD is not None else None)) for s in (0, 1)]
    f = TOTF
    return [('', 0, PROJ['W'][:, 0] if PROJ else None,
             (D[:, 1] * f, PD[1][:, 0, :] * f if PD is not None else None))]


def kaxis(ax, yl, arrows=True, show_x=True, first_label=True):
    xs = [x for x, _ in NODES]
    ax.set_xlim(PX[0], PX[-1]); ax.set_ylim(*yl)
    for x in xs[1:-1]:
        if arrows:
            ax.axvline(x, color=ARROW, ls=(0, (5, 3)), lw=2.2, zorder=2)
            dy = 0.035 * (yl[1] - yl[0])
            for y0, y1 in ((yl[1] - dy, yl[1]), (yl[0] + dy, yl[0])):
                ax.annotate('', xy=(x, y1), xytext=(x, y0), zorder=6, annotation_clip=False,
                            arrowprops=dict(arrowstyle='->', color=ARROW, lw=2.2, mutation_scale=22))
        else:
            ax.axvline(x, color='0.55', lw=0.8, zorder=1)
    ax.axhline(0, color='r', ls=(0, (6, 3)), lw=2.2, zorder=7)
    # ticks exactly at the high-symmetry points (positions = node list of SIESTA's .bands), labelled
    # only with the point names (Γ, K, M, ...); the k values are shown in the interactive page
    span = PX[-1] - PX[0]
    ax.set_xticks(xs)
    labs = [nodelabel(l) for _, l in NODES]
    if not first_label:            # this panel continues the previous one: its first point is already labelled
        labs[0] = ''
    ax.set_xticklabels(labs if show_x else [], fontsize=20, fontweight='bold')
    ax.tick_params(axis='x', which='major', labelbottom=show_x, pad=8)
    if show_x:                     # close pairs: left label right-aligned, right label left-aligned
        tl = ax.get_xticklabels()
        for i in range(1, len(NODES)):
            if NODES[i][0] - NODES[i - 1][0] < 0.07 * span:
                tl[i - 1].set_ha('right'); tl[i].set_ha('left')
    ax.set_xlabel('K-Points')
    AXREC['nodes'] = [round(float(x), 6) for x in xs]
    AXREC['labels'] = [l for _, l in NODES]
    AXREC['tick_text'] = [nodelabel(l).replace('$', '').replace('\\Gamma', 'Γ') for _, l in NODES]
    AXREC['drawn_in'].append(len(AXREC['drawn_in']) + 1)
    AXREC.setdefault('first_label_drawn', []).append(bool(first_label))
    ax.yaxis.set_major_locator(MaxNLocator(8, steps=[1, 2, 2.5, 5, 10]))



def soc_gap_points(char):
    """spin-orbit, magnetic: band edges of the states with spin character char (+1 up, -1 down).
    Value and direct/indirect from the full k-grid (summary soc_up_* / soc_dn_*), arrow ends at the
    extrema of the same-character states on the drawn path"""
    tag = 'up' if char > 0 else 'dn'
    if f'soc_{tag}_gap_eV' not in S or SZ is None:
        return None
    gs = float(S[f'soc_{tag}_gap_eV'])
    if gs < GAPMIN:
        return None
    no = int(S.get('spin1_nocc', '0'))
    lo = PROJ['lo']
    bv, bc = [], []
    for b in range(lo - 1, lo - 1 + SZ.shape[1]):
        z = SZ[:, b - (lo - 1)]
        m = (z >= 0) if char > 0 else (z < 0)
        if not m.any():
            continue
        e = np.where(m, PE[:, 0, b], np.nan)
        (bv if b < no else bc).append(e)
    if not bv or not bc:
        return None
    V = np.nanmax(np.array(bv), 0); C = np.nanmin(np.array(bc), 0)       # per-k edges of this character
    iv = int(np.nanargmax(V))
    cand = np.where(C <= np.nanmin(C) + 1e-3)[0]
    ic = int(cand[np.argmin(np.abs(PX[cand] - PX[iv]))])
    vcand = np.where(V >= np.nanmax(V) - 1e-3)[0]
    iv = int(vcand[np.argmin(np.abs(PX[vcand] - PX[ic]))])
    dg = float(S[f'soc_{tag}_direct_gap_k'].split()[0])
    typ = 'direct' if dg - gs < GAPTOL else 'indirect'
    return float(PX[iv]), float(V[iv]), float(PX[ic]), float(C[ic]), gs, typ


def gap_points(s, char=None):
    """VBM and CBM of spin channel s on the drawn band path: (x_v, E_v, x_c, E_c, gap, type) or None"""
    if char is not None:
        r = soc_gap_points(char)
        if r is not None or 'soc_up_gap_eV' in S:
            return r
    # every spin channel is judged on its OWN bands (a half-metal's insulating channel keeps its gap);
    # no arrow when the gap is below GAPMIN (gapless / metallic: there is no gap to mark)
    key = f'spin{s + 1}_nocc'
    if key not in S and 'spin1_nocc' not in S:
        return None
    if f'spin{s + 1}_type' in S and 'insulator' not in S[f'spin{s + 1}_type']:
        return None
    no = int(S.get(key, S.get('spin1_nocc')))
    if not (1 <= no < NB):
        return None
    v, c = PE[:, s, no - 1], PE[:, s, no]
    if np.nanmin(c) - np.nanmax(v) < 0.02:
        return None                                     # this channel is metallic on the path
    iv = int(np.nanargmax(v))
    cand = np.where(c <= np.nanmin(c) + 1e-3)[0]        # CB minima (within 1 meV): take the one closest to the VBM
    ic = int(cand[np.argmin(np.abs(PX[cand] - PX[iv]))])
    vcand = np.where(v >= np.nanmax(v) - 1e-3)[0]       # and the VB maximum closest to that CBM
    iv = int(vcand[np.argmin(np.abs(PX[vcand] - PX[ic]))])
    gs = float(S[f'spin{s + 1}_CBM_E_k'].split()[0]) - float(S[f'spin{s + 1}_VBM_E_k'].split()[0]) \
        if f'spin{s + 1}_CBM_E_k' in S else c[ic] - v[iv]
    if gs < GAPMIN:
        return None
    # direct / indirect of THIS channel: its smallest direct gap within GAPTOL of its own gap
    dg = float(S[f'spin{s + 1}_direct_gap_k'].split()[0]) if f'spin{s + 1}_direct_gap_k' in S else None
    if dg is not None:
        typ = 'direct' if dg - gs < GAPTOL else 'indirect'
    else:
        typ = 'direct' if S.get('gap_type', '') == 'direct' else 'indirect'
    return float(PX[iv]), float(v[iv]), float(PX[ic]), float(c[ic]), gs, typ


GAPREC = []
GAPMIN = 0.02          # eV: below this a channel is gapless / metallic and gets no gap arrow
_OVR = [False]           # True while figure 1 draws the overall gap (both spins together)


def overall_gap_points():
    """VBM and CBM of BOTH spins together on the drawn path (x_v, E_v, x_c, E_c, gap, type); the value is
    the overall gap of the summary, the type 'direct' / 'indirect' / 'between spins'"""
    g = float(S.get('overall_gap_eV', 0))
    if g < GAPMIN:
        return None
    if SOCSPIN is not None or len(SP) == 1:
        return gap_points(SP[0])
    best_v, best_c = None, None
    for s_ in SP:
        no = NOCC[s_]
        if not (1 <= no < NB):
            continue
        v, c = PE[:, s_, no - 1], PE[:, s_, no]
        iv, ic = int(np.nanargmax(v)), int(np.nanargmin(c))
        if best_v is None or v[iv] > best_v[1]:
            best_v = (float(PX[iv]), float(v[iv]), s_)
        if best_c is None or c[ic] < best_c[1]:
            best_c = (float(PX[ic]), float(c[ic]), s_)
    if best_v is None or best_c is None:
        return None
    gt = S.get('gap_type', '')
    typ = 'between spins' if 'between' in gt else ('direct' if gt == 'direct' else 'indirect')
    return best_v[0], best_v[1], best_c[0], best_c[1], g, typ


def draw_gap(ax, s, yl, fs=15, char=None, gp=None, overall=False):
    """band-gap arrow from the VBM to the CBM (vertical if direct, slanted if indirect) with its value;
    gp: precomputed points (the overall gap of both spins), overall: label it 'overall'"""
    gp = gap_points(s, char) if gp is None else gp
    if gp is None:
        return
    xv, ev, xc, ec, gs, typ = gp
    # band edges away from the drawn path (path chosen by the user misses the VBM / CBM): the arrow joins the
    # path's own extremes, so say that the true edges (and the gap value) lie off this path
    offp = abs((ec - ev) - gs) > max(0.010, 0.010 * gs)
    span = PX[-1] - PX[0]
    dx = 0.012 * span                                   # keep a band edge at the frame clear of the spine
    xv2 = min(max(xv, PX[0] + dx), PX[-1] - dx); xc2 = min(max(xc, PX[0] + dx), PX[-1] - dx)
    if typ == 'direct':
        xc2 = xv2
    ax.annotate('', xy=(xc2, ec), xytext=(xv2, ev), zorder=12, annotation_clip=False,
                arrowprops=dict(arrowstyle='-|>', color='#000000', lw=2.6, mutation_scale=22, shrinkA=0, shrinkB=0))
    ax.plot([xv2], [ev], 'o', ms=8, mfc='white', mec='k', mew=2, zorder=13)
    ax.plot([xc2], [ec], 'o', ms=8, mfc='white', mec='k', mew=2, zorder=13)
    xm = 0.5 * (xv2 + xc2)
    if abs(xc2 - xv2) < 1e-9:                          # vertical (direct): label beside the arrow
        right = xm < PX[0] + 0.6 * span
        lx, ly, ha, va = xm + (0.03 if right else -0.03) * span, 0.5 * (ev + ec), ('left' if right else 'right'), 'center'
    else:                                              # slanted (indirect): label below the line, away from it
        up_right = xc2 > xv2
        lx, ly = xm + (0.03 if up_right else -0.03) * span, 0.5 * (ev + ec) - 0.04 * (yl[1] - yl[0])
        ha, va = ('left' if up_right else 'right'), 'top'
    tag = ('(↑)' if s == 0 else '(↓)') if (len(SP) == 2 and SOCSPIN is None) else ''
    if char is not None and 'soc_up_gap_eV' in S:
        tag = '(↑)' if char > 0 else '(↓)'
    if _OVR[0]:
        tag = ' (overall)' if overall else ''
    ax.text(lx, ly, f'E$_g${tag} = {gs:.3f} eV\n({typ})' + (f'\nedges off this path\n(on path {ec - ev:.3f} eV)' if offp else ''),
            ha=ha, va=va, fontsize=fs, zorder=14,
            bbox=dict(boxstyle='round,pad=0.25', fc='white', ec='k', lw=1.2))
    GAPREC.append(dict(spin=s, char=char, x_vbm=xv, E_vbm=ev, x_cbm=xc, E_cbm=ec, gap=gs, type=typ, overall=bool(_OVR[0])))

def draw_lines(ax, s, wk, yl, lw=2.4, char=None, index=False):
    """band lines of spin s: coloured by dominant projection (wk) or xmgrace colour cycle.
    Spin-orbit (char = +1 / -1): only the parts of each band with that spin character are drawn,
    so the Spin Up and Spin Down panels separate the two spins as in a collinear calculation"""
    lo = PROJ['lo'] if PROJ else 1
    cyc = BANDCYC
    byidx = index or BANDCOL == 'index'
    for b in range(NB):
        e = PE[:, s, b]
        if np.nanmax(e) < yl[0] - 0.3 or np.nanmin(e) > yl[1] + 0.3:
            continue
        FIG1_BANDCOLS.add(cyc[b % len(cyc)]); FIG1_NLINES.add(b)
        if char is not None:
            mk = soc_mask(b, char)
            if mk is None or not mk.any():
                continue
            pts = np.c_[PX, e].reshape(-1, 1, 2)
            allseg = np.concatenate([pts[:-1], pts[1:]], 1)
            z = SZ[:, b - (lo - 1)]
            mix = ~mk & (np.abs(0.5 * (z[:-1] + z[1:])) < 0.5)      # strongly mixed, other panel: faint (continuity)
            if byidx or wk is None:
                col = np.array([mpl.colors.to_rgb(cyc[b % len(cyc)] if byidx else 'k')] * len(allseg))
            else:
                w = wk[:, b - (lo - 1), :]
                col = np.array([mpl.colors.to_rgb(c) for c in GCOL])[np.argmax(w, 1)][:-1]
            ax.add_collection(LineCollection(allseg[mk], colors=col[mk], linewidths=lw, zorder=3, capstyle='round'))
            if mix.any():
                ax.add_collection(LineCollection(allseg[mix], colors=1 - 0.3 * (1 - col[mix]), linewidths=0.6 * lw,
                                                 zorder=2, capstyle='round'))
            continue
        if byidx:
            ax.plot(PX, e, color=cyc[b % len(cyc)], lw=lw, zorder=3)
            continue
        if wk is None or not (lo - 1 <= b < lo - 1 + wk.shape[1]):
            ax.plot(PX, e, color='k', lw=lw, zorder=3)
            continue
        w = wk[:, b - (lo - 1), :]
        rgb = np.array([mpl.colors.to_rgb(c) for c in GCOL])[np.argmax(w, 1)]
        pts = np.c_[PX, e].reshape(-1, 1, 2)
        ax.add_collection(LineCollection(np.concatenate([pts[:-1], pts[1:]], 1), colors=rgb[:-1],
                                         linewidths=lw, zorder=3, capstyle='round'))


def draw_dos(ax, tot, pd, yl, sign, xmax, cols=None):
    E = D[:, 0]
    m = (E > yl[0] - 0.5) & (E < yl[1] + 0.5)
    cols = cols or GCOL
    # total first and wider, the contributions on top (a contribution equal to the total stays visible)
    ax.plot(sign * smooth(tot, E)[m], E[m], color='k', lw=3.4, zorder=3)
    if pd is not None:
        for g in range(pd.shape[1]):
            ax.plot(sign * smooth(pd[:, g], E)[m], E[m], color=cols[g % len(cols)], lw=2.2, zorder=4 + g)
    ax.axhline(0, color='r', ls=(0, (6, 3)), lw=2.2, zorder=7)
    ax.set_ylim(*yl)
    ax.set_xlim((-xmax, 0) if sign < 0 else (0, xmax))
    ax.set_xlabel('DOS (1/eV)')
    ax.xaxis.set_major_locator(MaxNLocator(4))
    ax.yaxis.set_major_locator(MaxNLocator(8, steps=[1, 2, 2.5, 5, 10]))


def dos_xmax(chs, yl):
    E = D[:, 0]; m = (E > yl[0]) & (E < yl[1])
    v = max(smooth(c[3][0], E)[m].max() for c in chs)
    return float(MaxNLocator(4).tick_values(0, 1.08 * v)[-1]) if v > 0 else 1.0


def legend_box(ax, loc='best', chs=None):
    """legend of the DOS panel; with chs, contributions below 1 % of the largest DOS in the window are left out
    (their curves lie on the axis) so that the legend stays small and covers no data"""
    h = [Line2D([], [], color='k', lw=3, label='Total')]
    keep = [True] * len(GRP)
    if chs and PD is not None:
        try:
            E_ = D[:, 0]; m_ = (E_ > YW[0]) & (E_ < YW[1])
            top = max(float(c[3][0][m_].max()) for c in chs)
            keep = [max(float(c[3][1][m_, g].max()) for c in chs if c[3][1] is not None) >= 0.01 * top
                    for g in range(len(GRP))]
        except Exception:
            keep = [True] * len(GRP)
    h += [Line2D([], [], color=c, lw=3, label=n) for c, n, k in zip(GCOL, GRP, keep) if k] if PD is not None else []
    lg = ax.legend(handles=h, loc=loc, frameon=True, fancybox=False, edgecolor='k', framealpha=1,
                   handlelength=1.8, borderpad=0.5, labelspacing=0.35, fontsize=14)
    lg.get_frame().set_linewidth(1.4)
    lg.set_zorder(20)




def soc_note():
    """spin-orbit, magnetic: how the two band panels are separated, and the gap of each spin character"""
    if SZ is None or 'soc_up_gap_eV' not in S:
        return ''
    g = [float(S.get(f'soc_{t}_gap_eV', 'nan')) for t in ('up', 'dn')]
    return ('spin-orbit: each state is drawn in the Spin Up panel if <σz> ≥ 0, else in the Spin Down '
            f'panel; E_g(↑) = {g[0]:.3f} eV, E_g(↓) = {g[1]:.3f} eV between states of the same spin '
            '(full k-grid); faint: strongly mixed states (|<σz>| < 0.5) that belong to the other panel; ')


def subtitle():
    t = title_text(short=True).replace('μ$_B$', 'μB') + (f' ({GAPNOTE})' if GAPNOTE else '')
    sm = f'; DOS: linear {DIM}D simplices, displayed with Gaussian σ = {SMEAR:.2f} eV' if SMEAR > 0 else ''
    return t + sm


YW = ewindow()
CHS = spin_channels()
MAGCOL = len(SP) == 2 and SOCSPIN is None        # collinear magnetic run: two different spin channels


def total_atom_dos():
    """figure 1 quantities: E, total DOS of ALL spins, species names and the DOS of each species (all spins).
    Exact sums of dos.dat / pdos.dat; x2 for an unpolarised or spin-degenerate run (TOTF)"""
    E = D[:, 0]
    f = TOTF if len(SP) == 1 else 1
    tot = sum(D[:, 1 + s] for s in SP) * f
    if FINE_PD is None:
        return E, tot, [], None
    nm = [n[:-3] if n.endswith(('_up', '_dn')) else n for n in FINE_GRP]
    arr = sum(FINE_PD[1][:, s, :] for s in SP) * f
    names, a = aggregate(nm, arr, 'atom')
    return E, tot, names, a


def draw_total_bands(ax, yl):
    """all bands as plain lines: one set (no spin, spin-degenerate or spin-orbit), or both spins of a
    collinear magnet (spin up solid black, spin down dashed red)"""
    for s in SP:
        dn = MAGCOL and s == 1
        for b in range(NB):
            e = PE[:, s, b]
            if np.nanmax(e) < yl[0] - 0.3 or np.nanmin(e) > yl[1] + 0.3:
                continue
            ax.plot(PX, e, color='#e00000' if dn else '#000000', ls=(0, (5, 3)) if dn else '-',
                    lw=2.2 if dn else 2.4, zorder=4 if dn else 3)


FIG1_BANDCOLS = set()          # colours used for the band lines of figure 1 (checked: one per band)
FIG1_NLINES = set()            # bands drawn in figure 1


def spin_gap_note():
    """the gap of each spin channel in words, as written in papers"""
    if len(CHS) != 2:
        return ''
    out = []
    for i_, (t_, s_, _, _) in enumerate(CHS):
        chr_ = ((1 if i_ == 0 else -1) if SZ is not None else None)
        gp = gap_points(s_, chr_)
        out.append(f'{"spin ↑" if i_ == 0 else "spin ↓"}: ' + ('metallic' if gp is None else f'E_g = {gp[4]:.3f} eV ({gp[5]})'))
    return '; '.join(out) + '; '


def element_dos(ich):
    """DOS of each element in spin channel ich of CHS (exact sums of the shells of pdos.dat)"""
    if FINE_PD is None:
        return [], None
    s_ = CHS[ich][1]
    if SOCSPIN is not None and len(CHS) == 2:
        suf = '_up' if ich == 0 else '_dn'
        idx = [k for k, n in enumerate(FINE_GRP) if n.endswith(suf)]
        return aggregate([FINE_GRP[k][:-3] for k in idx], FINE_PD[1][:, 0, idx], 'atom')
    nm = [n[:-3] if n.endswith(('_up', '_dn')) else n for n in FINE_GRP]
    if len(CHS) == 2:
        return aggregate(nm, FINE_PD[1][:, s_, :], 'atom')
    f = TOTF if len(SP) == 1 else 1
    return aggregate(nm, sum(FINE_PD[1][:, s, :] for s in SP) * f, 'atom')


# ---------------- figure 1: band structure and DOS, as drawn in papers.
#   no spin polarisation (or identical spins): one band panel, every band its own colour, the gap arrow,
#     total DOS + the DOS of each element;
#   magnets (collinear or spin-orbit): DOS up (mirrored) | bands up | bands down | DOS down, each spin
#     channel with its own gap arrow, "metallic" for a channel that crosses E_F.
with mpl.rc_context(XG_RC):
    E1 = D[:, 0] if haveDOS else None
    if len(CHS) != 2:
        fig = plt.figure(figsize=(10.0, 9.0), layout='constrained')
        gs = fig.add_gridspec(1, 2, width_ratios=[2.0, 1])
        a = fig.add_subplot(gs[0, 0]); b2 = fig.add_subplot(gs[0, 1], sharey=a)
        draw_lines(a, SP[0], None, YW, index=True)
        kaxis(a, YW)
        draw_gap(a, SP[0], YW)
        a.set_ylabel('Energy (eV)')
        F1 = dict(panels=1, magnetic=False)
        if haveDOS:
            T1 = CHS[0][3][0] if CHS else D[:, 1] * TOTF
            AN1, A1 = element_dos(0) if CHS else ([], None)
            m1 = (E1 > YW[0] - 0.5) & (E1 < YW[1] + 0.5)
            ACOL = [XMG[i % len(XMG)] for i in range(len(AN1))]
            # total first and wider, the elements on top: an element equal to the total (one element) stays visible
            b2.plot(smooth(T1, E1)[m1], E1[m1], color='k', lw=4.2, zorder=3)
            for g in range(len(AN1)):
                b2.plot(smooth(A1[:, g], E1)[m1], E1[m1], color=ACOL[g], lw=2.0, zorder=4 + g)
            b2.axhline(0, color='r', ls=(0, (6, 3)), lw=2.2, zorder=7)
            mw = (E1 > YW[0]) & (E1 < YW[1])
            v = smooth(T1, E1)[mw].max() if mw.any() else 1.0
            b2.set_xlim(0, float(MaxNLocator(4).tick_values(0, 1.08 * v)[-1]) if v > 0 else 1.0)
            b2.set_xlabel('DOS (1/eV)')
            b2.xaxis.set_major_locator(MaxNLocator(4))
            h = [Line2D([], [], color='k', lw=4.2, label='Total')]
            h += [Line2D([], [], color=c, lw=2.0, label=n) for c, n in zip(ACOL, AN1)]
            lg = b2.legend(handles=h, loc='best', frameon=True, fancybox=False, edgecolor='k', framealpha=1,
                           handlelength=1.8, borderpad=0.5, labelspacing=0.35, fontsize=14)
            lg.get_frame().set_linewidth(1.4); lg.set_zorder(20)
            ii = np.where(mw)[0]
            F1.update(dos_names=list(AN1), E=[round(float(x), 5) for x in E1[ii]],
                      tot=[float(x) for x in T1[ii]],
                      atoms=[[float(x) for x in A1[ii, g]] for g in range(len(AN1))] if A1 is not None else [])
        plt.setp(b2.get_yticklabels(), visible=False)
        cap = ('All bands, each in its own colour' + (' (spin–orbit)' if SOCSPIN is not None else '') +
               '; DOS: total (black) and the contribution of each element (Mulliken); ')
    else:
        fig = plt.figure(figsize=(12.0, 9.6), layout='constrained')
        gs = fig.add_gridspec(1, 4, width_ratios=[1, 1.45, 1.45, 1], wspace=0.0)
        axs = [fig.add_subplot(gs[0, 0])]
        axs += [fig.add_subplot(gs[0, i], sharey=axs[0]) for i in (1, 2, 3)]
        fig.get_layout_engine().set(w_pad=0.05, wspace=0.05)
        APD = [element_dos(k) for k in range(2)]
        ANM = APD[0][0]
        ACOL = [XMG[i % len(XMG)] for i in range(len(ANM))]
        xm = dos_xmax(CHS, YW)
        draw_dos(axs[0], CHS[0][3][0], APD[0][1], YW, -1, xm, cols=ACOL)
        draw_dos(axs[3], CHS[1][3][0], APD[1][1], YW, +1, xm, cols=ACOL)
        for i, (t, s, wk, _) in enumerate(CHS):
            a = axs[1 + i]
            chr_ = ((1 if i == 0 else -1) if SZ is not None else None)
            draw_lines(a, s, None, YW, char=chr_, index=True)       # every band its own colour, as in papers
            kaxis(a, YW, first_label=(i == 0))
            draw_gap(a, s, YW, char=chr_)
            if gap_points(s, chr_) is None:                       # this spin channel crosses E_F (or is gapless)
                a.text(0.5, 0.56, 'metallic', transform=a.transAxes, ha='center', va='bottom', fontsize=15,
                       zorder=14, bbox=dict(boxstyle='round,pad=0.25', fc='white', ec='k', lw=1.2))
            if i:
                AXREC.setdefault('joins', []).append(dict(figure='1_bands_dos', first_tick_text=a.get_xticklabels()[0].get_text()))
            a.set_title(t, pad=12)
            AXREC.setdefault('panel_titles', []).append(dict(figure='1_bands_dos', title=t))
            plt.setp(a.get_yticklabels(), visible=False)
        plt.setp(axs[3].get_yticklabels(), visible=False)
        axs[0].set_ylabel('Energy (eV)')
        h = [Line2D([], [], color='k', lw=3, label='Total')] + [Line2D([], [], color=c, lw=3, label=n) for c, n in zip(ACOL, ANM)]
        lg = axs[3].legend(handles=h, loc='best', frameon=True, fancybox=False, edgecolor='k', framealpha=1,
                           handlelength=1.8, borderpad=0.5, labelspacing=0.35, fontsize=14)
        lg.get_frame().set_linewidth(1.4); lg.set_zorder(20)
        F1 = dict(panels=4, magnetic=True, dos_names=list(ANM))
        if haveDOS:
            mw = (E1 > YW[0]) & (E1 < YW[1]); ii = np.where(mw)[0]
            F1.update(E=[round(float(x), 5) for x in E1[ii]],
                      chan=[dict(tot=[float(x) for x in c[3][0][ii]],
                                 atoms=[[float(x) for x in APD[k][1][ii, g]] for g in range(APD[k][1].shape[1])]
                                 if APD[k][1] is not None else []) for k, c in enumerate(CHS)])
        cap = (soc_note() + spin_gap_note() + 'every band its own colour; DOS: total (black) and each element (colours), '
               'spin up to the left, spin down to the right; ')
    F1['band_colours'] = len(FIG1_BANDCOLS); F1['band_lines'] = len(FIG1_NLINES); F1['palette'] = len(BANDCYC)
    AXREC['fig1'] = F1
    fig.suptitle(f'{LABEL}: Band Structure and DOS', fontsize=22, fontweight='bold')
    fig.text(0.5, -0.01, wrapc(cap + subtitle()), ha='center', va='top', fontsize=11, fontweight='normal')
    save(fig, '1_bands_dos')

# ---------------- 1b: VASPKIT-style projected ("fat") bands
# circles on each eigenvalue, area proportional to the Mulliken weight of each group (as in
# VASPKIT / PyProcar projected band plots), largest weights drawn last
def fat(ax, s, wk, yl, smax=55, char=None, cols=None, sig=None):
    lo = PROJ['lo']
    cols = cols or GCOL
    for b in range(NB):
        e = PE[:, s, b]
        if np.nanmax(e) < yl[0] - 0.3 or np.nanmin(e) > yl[1] + 0.3:
            continue
        mk = soc_mask(b, char) if char is not None else None
        if char is not None and mk is None:
            continue
        if mk is None:
            ax.plot(PX, e, color='0.15', lw=1.0, zorder=2)
        else:
            pts = np.c_[PX, e].reshape(-1, 1, 2)
            sg_ = np.concatenate([pts[:-1], pts[1:]], 1)
            z = SZ[:, b - (lo - 1)]
            mix = ~mk & (np.abs(0.5 * (z[:-1] + z[1:])) < 0.5)
            ax.add_collection(LineCollection(sg_[mk], colors='0.15', linewidths=1.0, zorder=2))
            ax.add_collection(LineCollection(sg_[mix], colors='0.75', linewidths=0.7, zorder=1))
    st = max(1, len(PX) // 110)
    xs, ys, ss, cs = [], [], [], []
    for b in range(lo - 1, lo - 1 + wk.shape[1]):
        e = PE[::st, s, b]
        if np.nanmax(e) < yl[0] - 0.3 or np.nanmin(e) > yl[1] + 0.3:
            continue
        w = wk[::st, b - (lo - 1), :]
        own = np.ones(len(e), bool)
        if char is not None:                      # only the states of this spin character
            z = SZ[::st, b - (lo - 1)]
            own = (z >= 0) if char > 0 else (z < 0)
        for g in range(w.shape[1]):
            if sig is not None and not sig[g]:
                continue
            k = (w[:, g] > 0.02) & own
            xs.append(PX[::st][k]); ys.append(e[k]); ss.append(smax * w[k, g]); cs += [cols[g % len(cols)]] * k.sum()
    if xs:
        x, y, z = np.concatenate(xs), np.concatenate(ys), np.concatenate(ss)
        o = np.argsort(-z)                    # small circles on top of big ones stay visible
        ax.scatter(x[o], y[o], s=z[o], c=np.array(cs)[o], alpha=0.8, linewidths=0, zorder=4)


def fat_channels(view):
    """CHS with band weights and PDOS summed to `view` ('fine': element + shell, 'atom': element):
    [(title, spin, weights [k, band, group], (tot, pdos [E, group]))], group names, colours, significance"""
    gk = [g.replace(' ', '-', 1) for g in GRP]          # "Mo 4d" -> engine form "Mo-4d" for the regrouping
    names = list(dict.fromkeys(view_names(gk, view))) if view != 'fine' else list(GRP)
    out = []
    for (t_, s_, wk, (tot, pd)) in CHS:
        w2 = aggregate(gk, wk, view)[1] if (wk is not None and view != 'fine') else wk
        p2 = aggregate(gk, pd, view)[1] if (pd is not None and view != 'fine') else pd
        out.append((t_, s_, w2, (tot, p2)))
    # groups that matter in the window: integrated PDOS >= 1 % of the total DOS there (any spin channel);
    # the others (a polarisation or semicore shell far from E_F) are named in the caption, not drawn
    sig = [True] * len(names)
    if haveDOS and out and out[0][3][1] is not None:
        E_ = D[:, 0]; m_ = (E_ > YW[0]) & (E_ < YW[1])
        tot_ = sum(float(np.abs(c[3][0][m_]).sum()) for c in out)
        sig = [sum(float(np.abs(c[3][1][m_, g]).sum()) for c in out) >= 0.01 * tot_ for g in range(len(names))]
    # strong, well separated colours go to the contributions that are drawn, in order
    cols, k_ = [], 0
    for g in range(len(names)):
        cols.append(FATCOL[k_ % len(FATCOL)] if sig[g] else '#B0B0B0'); k_ += 1 if sig[g] else 0
    return out, names, cols, sig


def fat_figure(view, fname):
    chans, names, cols, sig = fat_channels(view)
    with mpl.rc_context(XG_RC):
        nb = len(chans)
        fig = plt.figure(figsize=(12.0 if nb == 2 else 10.0, 9.6 if nb == 2 else 9.0), layout='constrained')
        gs = fig.add_gridspec(1, nb + 1, width_ratios=[1.45] * nb + [1])
        axs = [fig.add_subplot(gs[0, 0])]
        axs += [fig.add_subplot(gs[0, i], sharey=axs[0]) for i in range(1, nb + 1)]
        xm = dos_xmax(CHS, YW)
        for i, (t, s, wk, (tot, pd)) in enumerate(chans):
            chr_ = ((1 if i == 0 else -1) if (SZ is not None and nb == 2) else None)
            fat(axs[i], s, wk, YW, char=chr_, cols=cols, sig=sig)
            kaxis(axs[i], YW, first_label=(i == 0))
            draw_gap(axs[i], s, YW, char=chr_)
            if nb == 2 and gap_points(s, chr_) is None:
                axs[i].text(0.5, 0.56, 'metallic', transform=axs[i].transAxes, ha='center', va='bottom', fontsize=15,
                            zorder=14, bbox=dict(boxstyle='round,pad=0.25', fc='white', ec='k', lw=1.2))
            if i:
                AXREC.setdefault('joins', []).append(dict(figure=fname, first_tick_text=axs[i].get_xticklabels()[0].get_text()))
            if t:
                axs[i].set_title(t, pad=12)
                AXREC.setdefault('panel_titles', []).append(dict(figure=fname, title=t))
            if i:
                plt.setp(axs[i].get_yticklabels(), visible=False)
        a = axs[-1]
        E = D[:, 0]; m = (E > YW[0] - 0.5) & (E < YW[1] + 0.5)
        for i, (t, s, wk, (tot, pd)) in enumerate(chans):
            sg = (-1 if i == 0 else 1) if nb == 2 else 1          # spin up to the left, as in figure 1
            a.plot(sg * smooth(tot, E)[m], E[m], color='k', lw=2.2)
            for g in range(pd.shape[1] if pd is not None else 0):
                if not sig[g]:
                    continue
                a.fill_betweenx(E[m], 0, sg * smooth(pd[:, g], E)[m], color=cols[g], alpha=0.35, lw=0)
                a.plot(sg * smooth(pd[:, g], E)[m], E[m], color=cols[g], lw=1.8)
        a.axhline(0, color='r', ls=(0, (6, 3)), lw=2.2)
        a.set_xlim(-xm if nb == 2 else 0, xm); a.set_xlabel('DOS (1/eV)')
        if nb == 2:
            a.axvline(0, color='k', lw=1.2)
            a.text(0.04, 0.015, '↑', transform=a.transAxes, ha='left', va='bottom', fontsize=20)
            a.text(0.96, 0.015, '↓', transform=a.transAxes, ha='right', va='bottom', fontsize=20)
        plt.setp(a.get_yticklabels(), visible=False)
        axs[0].set_ylabel('Energy (eV)')
        h = [Line2D([], [], ls='', marker='o', ms=12, color=c, alpha=0.8, label=n.replace('-', ' '))
             for c, n, k in zip(cols, names, sig) if k]
        h += [Line2D([], [], color='k', lw=3, label='Total')]
        lg = a.legend(handles=h, loc='best', frameon=True, fancybox=False, edgecolor='k', framealpha=1,
                      handlelength=1.2, borderpad=0.5, labelspacing=0.35, fontsize=14)
        lg.get_frame().set_linewidth(1.4); lg.set_zorder(20)
        minor = [n.replace('-', ' ') for n, k in zip(names, sig) if not k]
        what = 'element' if view == 'atom' else 'atomic orbital shell (element and n l of the SIESTA basis, e.g. Mo 4d, S 3p)'
        fig.suptitle(f'{LABEL}: Projected Band Structure' + (' (atoms)' if view == 'atom' else ' (atoms and orbitals)'),
                     fontsize=22, fontweight='bold')
        fig.text(0.5, -0.01, wrapc('circle area proportional to the Mulliken weight of each ' + what +
                 '; circles and DOS in the same colour' + ('; DOS: spin up to the left, spin down to the right' if nb == 2 else '') +
                 (f'; contributions below 1 % of the DOS in this window not drawn: {", ".join(minor)}' if minor else '') +
                 '; ' + subtitle()), ha='center', va='top', fontsize=11, fontweight='normal')
        save(fig, fname)
    return names, sig


if PROJ is not None and CHS:
    FATSIG = {'fine': fat_figure('fine', '1b_projected_bands'), 'atom': fat_figure('atom', '1e_projected_bands_atoms')}


# ---------------- 1c: spin-orbit: bands coloured by <sigma_z>, spin-resolved DOS
if SOCSPIN is not None and 'Wup' in SOCSPIN and haveDOS:
    with mpl.rc_context(XG_RC):
        fig = plt.figure(figsize=(10.4, 9.0), layout='constrained')
