METHOD = """H(k), S(k): Bloch sums of the self-consistent SIESTA matrices (HSX file); eigenvalues of the generalised
problem H c = E S c (LAPACK). Spin-orbit runs: 2x2 spinor blocks of the HSX file.
DOS and electron count: linear simplices (triangles in 2D, Bloechl tetrahedra in 3D, intervals in 1D) on a
periodic k-grid, no broadening; the Fermi level is found again at T = 0. Figures show the DOS with a Gaussian
of the width printed on them (display only).
Band path: the fdf BandLines path; k-distance in Bohr^-1 exactly as in <label>.bands.
Contours: exact iso-lines of the eigenvalues, accuracy checked by exact diagonalisation at contour points.
QPI (figure 6, interactive page):
  A(k,E)   = sum_n (eta/pi) / ((E - e_n(k))^2 + eta^2)                        spectral function
  J(q,E)   = (1/N) sum_k A(k,E) A(k+q,E)                                       joint DOS (FFT, exact on the grid)
  drho(q,E)= -(1/2 pi i)[T C(q) - (T C(-q))*],  C(q) = (1/N) sum_k G(k,E) G(k+q,E)
             T-matrix of a scalar point impurity to first order in U (Born limit), G = sum_n 1/(E - e_n + i eta);
             Bena PRL 100, 076601 (2008); Kaladzhyan et al. arXiv:2105.01068 Eqs. (11)-(17)
  Bloch-weighted QPI = pair sum over the exact contours weighted by |<psi_k1| exp(-iq.r) |psi_k2>|^2
             (orbital / sublattice / spin selection rules).
  Backscattering loci: q = 2(k - c) (across a pocket of centre c) and q = -2k (time-reversed partner).
"""



def final_checks():
    """checks that can only be made after all figures exist: every character drawn, gap arrow consistent"""
    global verdict
    rows_ = []
    g = sorted(set(GLYPHS))
    rows_.append(('PASS' if not g else 'FAIL', 'every character in the figures drawn by the font (no empty boxes)',
                  float(len(g)), '; '.join(g)[:150] or 'all text rendered'))
    if GAPREC:
        dmax = 0.0
        for r in GAPREC:
            dmax = max(dmax, abs(r['gap'] - (r['E_cbm'] - r['E_vbm'])) if r['type'] == 'direct' and r['x_vbm'] == r['x_cbm'] else 0.0)
        gs = float(S.get('overall_gap_eV', 0))
        ref = lambda r: (float(S['soc_' + ('up' if r['char'] > 0 else 'dn') + '_gap_eV'])
                         if r.get('char') is not None and 'soc_up_gap_eV' in S else gs)
        lab = max(abs(r['gap'] - ref(r)) for r in GAPREC) if 'spin2_VBM_E_k' not in S else 0.0
        rows_.append(('PASS' if lab <= max(0.010 * gs, 1e-3) else 'FAIL', 'band-gap arrow: value drawn = reported gap (eV; limit 1 %)',
                      lab, f'{len(GAPREC)} arrows drawn, VBM → CBM on the band path'))
    elif float(S.get('overall_gap_eV', 0)) > 0.02 and DIM >= 1:
        rows_.append(('FAIL', 'band-gap arrow drawn for a system with a gap', 0.0, 'no arrow was drawn'))
    with open(os.path.join(OUT, 'validation_plots.txt'), 'a') as f:
        for st, nm, v, nt in rows_:
            f.write(f'{st} | {nm} | {v:11.3e} | {nt}\n')
    allv = [l.rstrip('\n').split(' | ') for fn in ('validation.txt', 'validation_plots.txt')
            for l in open(os.path.join(OUT, fn)) if not l.startswith('#')]
    nf = sum(r[0].strip() == 'FAIL' for r in allv if len(r) >= 4); nw = sum(r[0].strip() == 'WARN' for r in allv if len(r) >= 4)
    nn = sum(r[0].strip() in ('INFO', 'NOTE') for r in allv if len(r) >= 4)
    verdict = ('ALL CHECKS PASSED' if nf == 0 and nw == 0 else f'{nf} FAIL, {nw} WARN') + (f' ({nn} note{"s" if nn != 1 else ""})' if nn else '')


def print_checks():
    final_checks()
    with open(os.path.join(OUT, 'validation_report.txt'), 'w') as f:
        f.write(f'siesta3d validation report: {LABEL}\n{"=" * 100}\n')
        f.write(f'verdict: {verdict}\n\n')
        write_check_sections(f)
        f.write('=== METHOD ===\n' + METHOD + '\n')
        f.write('=== 3. INDEPENDENT AUDIT (siesta3d_audit.py: re-reads the raw files, does not use the plotting code) ===\n'
                'not run yet\n')
    PROG.tick(1, 'validation report')


def fig_list():
    return " ".join(sorted(dict.fromkeys(SAVED), key=lambda x: (int(''.join(c for c in x if c.isdigit()) or 0), x)))


def finish_output(hp):
    """write the report, close the % bar, then print the result lines"""
    print_checks()
    write_axrec()
    PROG.done = PROG.total; PROG.close(final=True)
    print(f'  figures (PNG + PDF)      : {fig_list()}   (folder figures/)')
    if hp:
        print(f'  interactive page         : {os.path.relpath(hp)}  (any web browser)')
    print(f'  validation               : {verdict}   (validation_report.txt)')


def pub_context():
    """data for the interactive copies of figures 1 / 1b / 1c (same curves as the PNGs)"""
    EW = max(abs(YW[0]), abs(YW[1])) + 3.0           # bands / DOS kept for windows up to +-EW
    lo = PROJ['lo'] if PROJ else 1
    alph = SOCSPIN is not None
    out = dict(ewin=list(YW), smear=SMEAR, soc=SOCSPIN is not None, groups=GRP, gcol=GCOL,
               nodes=[(float(x), nodelabel(l).replace('$', '').replace('\\Gamma', 'Γ')) for x, l in NODES],
               title=LABEL, sub=subtitle(), chs=[], kunit=KLAB_TXT)
    if haveDOS:
        E = D[:, 0]; m = np.abs(E) < EW + 0.5
        out['dosE'] = E[m]
    FC = {v: fat_channels(v) for v in ('fine', 'atom')} if (PROJ is not None and CHS) else {}
    if FC:
        out['fatv'] = {v: dict(names=[n.replace('-', ' ') for n in FC[v][1]], col=FC[v][2], sig=[bool(x) for x in FC[v][3]])
                       for v in FC}
    for ich, (t, s_, wk, (tot, pd)) in enumerate(CHS or [('', 0, PROJ['W'][:, 0] if PROJ else None, (None, None))]):
        ch = dict(title=t, segs=[], plain=None, fat=None)
        chr_ = ((1 if ich == 0 else -1) if (SZ is not None and len(CHS) == 2) else None)
        bands = [b for b in range(NB) if np.nanmin(np.abs(PE[:, s_, b])) < EW]
        if chr_ is not None:
            bands = [b for b in bands if soc_mask(b, chr_) is not None]

        def own_e(b):
            """band b of this panel; spin-orbit: NaN where the state belongs to the other spin"""
            e = PE[:, s_, b]
            if chr_ is None:
                return e
            z = SZ[:, b - (lo - 1)]
            return np.where((z >= 0) if chr_ > 0 else (z < 0), e, np.nan)
        xs, ys = [], []
        for b in bands:
            xs += [PX, [np.nan]]; ys += [own_e(b), [np.nan]]
        ch['plain'] = (np.concatenate(xs), np.concatenate(ys)) if xs else (np.zeros(0), np.zeros(0))
        ch['pbi'] = [int(b) for b in bands]              # band index of each block: one colour per band on the page
        segs = {}                                         # (group, alpha level) -> x, y with NaN breaks
        fx, fy, fw, fg = [], [], [], []
        st = max(1, len(PX) // 110)
        for b in bands:
            e = own_e(b)
            if wk is None or not (lo - 1 <= b < lo - 1 + wk.shape[1]):
                key = (-1, 2); xx, yy = segs.setdefault(key, ([], []))
                xx += [PX, [np.nan]]; yy += [e, [np.nan]]
                continue
            w = wk[:, b - (lo - 1), :]
            dom = np.argmax(w, 1)
            lev = np.full(len(PX), 2)
            key_pt = dom * 3 + lev
            i0 = 0
            for i in range(1, len(PX) + 1):              # runs of constant (group, level)
                if i == len(PX) or key_pt[i] != key_pt[i0]:
                    j1 = min(i, len(PX) - 1)
                    key = (int(dom[i0]), int(lev[i0]))
                    xx, yy = segs.setdefault(key, ([], []))
                    xx += [PX[i0:j1 + 1], [np.nan]]; yy += [e[i0:j1 + 1], [np.nan]]
                    i0 = i
            ww = w[::st]
            for g in range(ww.shape[1]):
                k = (ww[:, g] > 0.02) & np.isfinite(e[::st])
                fx.append(PX[::st][k]); fy.append(e[::st][k]); fw.append(ww[k, g]); fg.append(np.full(k.sum(), g))
        ch['segs'] = [dict(g=g, lev=l, x=np.concatenate(v[0]), y=np.concatenate(v[1])) for (g, l), v in segs.items()]
        if fx:
            ch['fat'] = dict(x=np.concatenate(fx), y=np.concatenate(fy), w=np.concatenate(fw), g=np.concatenate(fg))
        if FC:                                            # fat circles and PDOS in both resolutions (atoms; atom + orbital)
            ch['fatv'], ch['fpd'] = {}, {}
            for v, (fch, fnm, fcol, fsig) in FC.items():
                wv = fch[ich][2]; pv_ = fch[ich][3][1]
                gx, gy, gw, gg = [], [], [], []
                for b in bands:
                    if wv is None or not (lo - 1 <= b < lo - 1 + wv.shape[1]):
                        continue
                    e = own_e(b)
                    ww = wv[::st, b - (lo - 1), :]
                    for g in range(ww.shape[1]):
                        k = (ww[:, g] > 0.02) & np.isfinite(e[::st])
                        gx.append(PX[::st][k]); gy.append(e[::st][k]); gw.append(ww[k, g]); gg.append(np.full(k.sum(), g))
                ch['fatv'][v] = dict(x=np.concatenate(gx), y=np.concatenate(gy), w=np.concatenate(gw),
                                     g=np.concatenate(gg)) if gx else None
                if haveDOS and pv_ is not None:
                    ch['fpd'][v] = [pv_[m, g] for g in range(pv_.shape[1])]
        if haveDOS and tot is not None:
            ch['tot'] = tot[m]
            ch['pd'] = [] if pd is None else [pd[m, g] for g in range(pd.shape[1])]
        gp = gap_points(s_, chr_)
        ch['gap'] = None if gp is None else [round(float(v), 5) for v in gp[:5]] + [gp[5]]
        ch['gaptag'] = ('↑' if chr_ > 0 else '↓') if (chr_ is not None and 'soc_up_gap_eV' in S) else ''
        out['chs'].append(ch)
    # ---- projection views of the DOS (atom / orbital / atom x orbital) for every channel, and the
    #      'both spins' view: all bands in one panel with the overall gap and the total DOS
    if haveDOS and FINE_PD is not None and CHS:
        Pf = FINE_PD[1]
        views = ['atom', 'fine', 'orb']               # atoms always first (the default)
        vlab = {'atom': 'atoms (total + each element)', 'fine': 'atom + orbital (e.g. Cr 3d, O 2p)',
                'orb': 'orbital only (s, p, d of all atoms)'}

        def fine_of(ich):
            if SOCSPIN is not None and len(CHS) == 2:
                suf = '_up' if ich == 0 else '_dn'
                idx = [i for i, n in enumerate(FINE_GRP) if n.endswith(suf)]
                return [FINE_GRP[i][:-3] for i in idx], Pf[:, 0, idx]
            if len(CHS) == 2:
                return FINE_GRP, Pf[:, CHS[ich][1], :]
            # one channel: spin-orbit "_up" / "_dn" components of the same shell are summed; the engine names
            # ("Cr-3d") are kept so that every view below is built from them exactly once
            nm = [n[:-3] if n.endswith(('_up', '_dn')) else n for n in FINE_GRP]
            arr = Pf[:, 0, :] * (TOTF if len(SP) == 1 else 1)
            un = list(dict.fromkeys(nm))
            M = np.zeros((len(nm), len(un)))
            for i, n in enumerate(nm):
                M[i, un.index(n)] = 1.0
            return un, arr @ M
        out['views'] = []
        for v in views:
            names = None
            for ich, ch in enumerate(out['chs']):
                nm, arr = fine_of(ich)
                names, agg = aggregate(nm, arr, v)
                ch.setdefault('pdv', {})[v] = [agg[m, g] for g in range(agg.shape[1])]
            out['views'].append(dict(key=v, label=vlab[v], names=names,
                                     col=[XMG[i % len(XMG)] for i in range(len(names))]))
        out['defview'] = 'atom'
        out['bandview'] = DEFVIEW               # the groups by which band lines can be coloured
        if len(out['chs']) == 2:
            both = dict(tot=sum(np.asarray(c['tot']) for c in out['chs']),
                        pdv={v['key']: [sum(np.asarray(c['pdv'][v['key']][g]) for c in out['chs'])
                                         for g in range(len(v['names']))] for v in out['views']})
            if SOCSPIN is None:
                both['plainU'], both['plainD'] = out['chs'][0]['plain'], out['chs'][1]['plain']
                both['pbiU'], both['pbiD'] = out['chs'][0]['pbi'], out['chs'][1]['pbi']
            else:
                xs, ys, pb = [], [], []
                for b in range(NB):
                    if np.nanmin(np.abs(PE[:, 0, b])) < EW:
                        xs += [PX, [np.nan]]; ys += [PE[:, 0, b], [np.nan]]; pb.append(b)
                both['plain'] = (np.concatenate(xs), np.concatenate(ys)); both['pbi'] = pb
            og = overall_gap_points()
            both['gap'] = None if og is None else [round(float(v), 5) for v in og[:5]] + [og[5]]
            out['both'] = both
    if SOCSPIN is not None and 'Wup' in SOCSPIN and haveDOS:
        sz = SOCSPIN['Wup'].sum(-1) - SOCSPIN['Wdn'].sum(-1)
        X, Y, V = [], [], []
        for b in range(lo - 1, lo - 1 + sz.shape[1]):
            e = PE[:, 0, b]
            if np.nanmin(np.abs(e)) < EW:
                X.append(PX); Y.append(e); V.append(sz[:, b - (lo - 1)])
        out['sz'] = dict(x=np.concatenate(X), y=np.concatenate(Y), v=np.concatenate(V),
                         up=SOCSPIN['PDup'].sum(1)[m], dn=SOCSPIN['PDdn'].sum(1)[m])
    return out



# =================================================================== 1D (wires, chains, nanotubes)
def grid1d_read():
    f = os.path.join(OUT, 'grid1d.dat')
    if not os.path.exists(f):
        return None
    h = open(f).readline().split()
    N1, ns, blo, bhi, b = int(h[2]), int(h[4]), int(h[6]), int(h[8]), float(h[10])
    a = np.loadtxt(f)
    E = a[:, 2:].reshape(N1, ns, bhi - blo + 1)
    fr = int(np.ceil(600 / N1))                         # refine coarse grids: periodic linear interpolation
    if fr > 1:
        u = np.arange(N1 * fr) / fr; i0 = np.floor(u).astype(int); w = (u - i0)[:, None, None]
        E = (1 - w) * E[i0 % N1] + w * E[(i0 + 1) % N1]
    return dict(E=E, b=b, N=E.shape[0], ns=ns, refine=fr)


def maps1d(G1, Eg):
    """A(k,E), JDOS(q,E) and T-matrix |drho(q,E)| on the periodic 1D grid (exact FFT convolutions)"""
    E, N = G1['E'], G1['N']
    d = np.abs(np.roll(E, -1, 0) - E)
    near = (E > Eg.min() - 0.3) & (E < Eg.max() + 0.3)
    eta = float(np.clip(0.8 * np.percentile(d[near] if near.any() else d, 75), 0.01, 0.1))
    A = np.zeros((len(Eg), N)); J = np.zeros((len(Eg), N)); T = np.zeros((len(Eg), N))
    R = np.zeros((len(Eg), N))                         # real-space LDOS change per unit cell (Friedel)
    dq = G1['b'] / N
    for i, e0 in enumerate(Eg):
        for s in range(G1['ns']):
            x = e0 - E[:, s, :]
            As = (eta / np.pi / (x * x + eta * eta)).sum(-1)
            Gs = (1.0 / (x + 1j * eta)).sum(-1)
            A[i] += As
            Fa = np.fft.fft(As); J[i] += np.real(np.fft.ifft(Fa * np.conj(Fa))) / N
            Fg = np.fft.fft(Gs); Fm = np.roll(Fg[::-1], 1)
            C = np.fft.ifft(Fg * Fm) / N; Cm = np.roll(C[::-1], 1)
            T[i] += np.real(-(C - np.conj(Cm)) / (2j * np.pi))
            # Born: drho(R_m, E) = -(1/pi) Im[ U g(R_m) g(-R_m) ],  g(R_m) = (1/N) sum_k G(k) exp(i k R_m)
            g = np.fft.ifft(Gs)                          # g[m] = (1/N) sum_k G(k) e^{+2 pi i k m / N}
            R[i] += -np.imag(g * np.roll(g[::-1], 1)) / np.pi
        if i % 20 == 0:
            PROG.tick(2.0 * 20 / len(Eg), '1D spectral function, QPI')
    T = np.abs(T)
    T = np.clip(T - gaussian_filter1d(T, 0.12 / dq, axis=1, mode='wrap'), 0, None)   # smooth PV background
    return dict(A=A, J=J, T=T, R=R, eta=eta)


def rownorm(M, core):
    M = np.asarray(M, np.float64)
    hi = np.maximum(np.percentile(M[:, core], 99.5, axis=1, keepdims=True), 1e-300)
    lo = np.percentile(M[:, core], 3, axis=1, keepdims=True)
    return np.sqrt(np.clip((M - lo) / np.maximum(hi - lo, 1e-300), 0, 1))


def run_1d():
    G1 = grid1d_read()
    if G1 is None:
        finish_output(None); return
    b = G1['b']; N = G1['N']
    Eg = np.linspace(YW[0], YW[1], 301)
    M = maps1d(G1, Eg)
    k = (np.arange(N) / N) * b
    kc = np.where(k > b / 2, k - b, k); order = np.argsort(kc)          # k in (-b/2, b/2]
    core = (k > 0.04 * b) & (k < 0.96 * b)
    Ai = M['A'][:, order]; Ai = np.sqrt(np.clip(Ai / max(np.percentile(Ai, 99.7), 1e-12), 0, 1))
    Ji, Ti = rownorm(M['J'], core), rownorm(M['T'], core)
    # each energy is normalised for contrast; energies with (almost) no states, e.g. inside a gap, would then
    # show amplified Lorentzian tails -> fade every row by its DOS (sum_k A / N) relative to the band rows
    Dr = M['A'].mean(1)
    wE = np.clip(Dr / max(0.15 * np.percentile(Dr, 75), 1e-300), 0, 1)[:, None]
    Ji, Ti = Ji * wE, Ti * wE
    kk = kc[order]
    # backscattering guides q = 2k (mod b) of every band, from the exact grid
    guides = []
    half = (k <= b / 2 + 1e-12)
    for s in range(G1['ns']):
        # the bands closest to E_F (at most 4 per spin), so the lines stay readable for wires with many bands
        near = sorted(range(G1['E'].shape[2]), key=lambda n: np.min(np.abs(G1['E'][:, s, n])))[:4]
        for n in sorted(near):
            e = G1['E'][half, s, n]
            if e.max() < YW[0] or e.min() > YW[1]:
                continue
            q = np.mod(2 * k[half], b)
            o = np.argsort(q); guides.append((q[o], e[o]))
    G1M = dict(k=kk, q=k, E=Eg, A=Ai, J=Ji, T=Ti, eta=M['eta'], guides=guides, b=b, refine=G1['refine'], Araw=M['A'])
    globals()['G1M'] = G1M
    style = dict(XG_RC, **{'font.size': 13, 'axes.labelsize': 15, 'axes.titlesize': 14, 'xtick.labelsize': 12,
                           'ytick.labelsize': 12, 'axes.linewidth': 1.8})

    def emap(ax, img, x, cmap, title, lab, xl, guide=False):
        ax.imshow(img, extent=[x[0], x[-1], Eg[0], Eg[-1]], origin='lower', aspect='auto', cmap=cmap,
                  vmin=0, vmax=1, interpolation='bilinear')
        if guide:
            for q, e in guides:
                br = np.r_[False, np.diff(q) < 0]
                qq = q.astype(float).copy(); qq[br] = np.nan
                ax.plot(qq, e, color='c', lw=0.7, ls='--', alpha=0.75)
        ax.axhline(0, color='r', ls=(0, (6, 3)), lw=1.6)
        ax.set_xlim(x[0], x[-1]); ax.set_ylim(Eg[0], Eg[-1])
        ax.set_xlabel(xl); ax.set_ylabel('Energy (eV)'); ax.set_title(title)
        ax.text(0.03, 0.97, lab, transform=ax.transAxes, va='top', fontsize=15, fontweight='bold',
                color='k' if cmap == 'bone_r' else 'w')

    with mpl.rc_context(style):
        fig = plt.figure(figsize=(12.4, 11.2), layout='constrained')
        gs = fig.add_gridspec(2, 2)
        emap(fig.add_subplot(gs[0, 0]), Ai, kk, 'bone_r', 'spectral function $A(k,E)$', '(a)', r'$k$ (Å$^{-1}$)')
        emap(fig.add_subplot(gs[0, 1]), Ji, k, QCMAP, 'JDOS $(q,E)$', '(b)', r'$q$ (Å$^{-1}$)', True)
        emap(fig.add_subplot(gs[1, 0]), Ti, k, QCMAP, r'T-matrix QPI $|\delta\rho(q,E)|$', '(c)', r'$q$ (Å$^{-1}$)', True)
        ad = fig.add_subplot(gs[1, 1])
        if CHS:
            draw_dos(ad, CHS[0][3][0], CHS[0][3][1], YW, +1, dos_xmax(CHS, YW)); legend_box(ad, 'upper right')
        ad.set_ylabel('Energy (eV)'); ad.set_title('DOS'); ad.text(0.03, 0.97, '(d)', transform=ad.transAxes,
                                                                     va='top', fontsize=15, fontweight='bold')
        fig.suptitle(f'{LABEL}: 1D Spectral Function and Quasiparticle Interference', fontsize=19, fontweight='bold')
        fig.text(0.5, -0.005, wrapc(
            f'1D periodic grid of {N} k-points' + (f' (x{G1["refine"]} linear refinement)' if G1['refine'] > 1 else '') +
            f', Lorentzian eta = {1000 * M["eta"]:.0f} meV. (b) JDOS(q,E) = (1/N) sum_k A(k,E) A(k+q,E); (c) FT-LDOS of a '
            'point impurity, T-matrix to first order (Born), smooth background removed; (b,c) each energy normalised, '
            'q = 0 excluded, rows faded where the DOS vanishes (gaps). Cyan dashed: backscattering q = 2k (Friedel 2k_F) of the 4 bands nearest E_F. '
            + subtitle(), 160), ha='center', va='top', fontsize=10, fontweight='normal')
        save(fig, '6_1d_spectral_qpi')
    # overview: bands + DOS (figure-1 renderer) on top, A(k,E) and T-matrix QPI below
    with mpl.rc_context(XG_RC):
        fig = plt.figure(figsize=(12.6, 12.0), layout='constrained')
        gs = fig.add_gridspec(2, 1, height_ratios=[1.05, 1])
        gt = gs[0].subgridspec(1, 2, width_ratios=[2.0, 1]); gb = gs[1].subgridspec(1, 2)
        ac = fig.add_subplot(gt[0]); ad = fig.add_subplot(gt[1], sharey=ac)
        ch0 = CHS[0] if CHS else ('', SP[0], PROJ['W'][:, SP[0]] if PROJ else None, (None, None))
        draw_lines(ac, ch0[1], ch0[2], YW); kaxis(ac, YW); draw_gap(ac, ch0[1], YW); ac.set_ylabel('Energy (eV)')
        if CHS:
            draw_dos(ad, CHS[0][3][0], CHS[0][3][1], YW, +1, dos_xmax(CHS, YW)); legend_box(ad, 'upper right')
        plt.setp(ad.get_yticklabels(), visible=False)
        for a_, l_ in ((ac, '(a)'), (ad, '(b)')):
            a_.text(0.03, 0.985, l_, transform=a_.transAxes, va='top', fontsize=19, fontweight='bold',
                    bbox=dict(boxstyle='round,pad=0.15', fc='white', ec='none', alpha=0.85), zorder=50)
        with mpl.rc_context({'font.size': 13, 'axes.labelsize': 15, 'xtick.labelsize': 12, 'ytick.labelsize': 12}):
            emap(fig.add_subplot(gb[0]), Ai, kk, 'bone_r', 'spectral function $A(k,E)$', '(c)', r'$k$ (Å$^{-1}$)')
            emap(fig.add_subplot(gb[1]), Ti, k, QCMAP, r'T-matrix QPI $|\delta\rho(q,E)|$', '(d)', r'$q$ (Å$^{-1}$)', True)
        fig.suptitle(f'{LABEL}: Electronic-Structure Overview (1D)', fontsize=22, fontweight='bold')
        fig.text(0.5, -0.005, wrapc('(a) band structure, colour = dominant projection; (b) DOS; (c) spectral function; '
                 '(d) T-matrix QPI with the 2k backscattering lines. ' + subtitle(), 150), ha='center', va='top',
                 fontsize=11, fontweight='normal')
        save(fig, '8_overview')
    extra_1d(G1, M, Eg, k, kc, order)
    hp = None
    try:
        hp = html_build(html_context_1d(), OUT)
        PROG.tick(1, 'interactive page')
    except Exception as ex:
        PROG.close()
        import traceback; traceback.print_exc()
        print('  (interactive HTML skipped:', ex, ')')
    with open(os.path.join(FIG, 'CAPTIONS.md'), 'w') as f:
        f.write(f'# Figure captions for {LABEL} (1D)\n\nSystem: {title_text(short=True)}. Energies relative to the SIESTA '
                f'Fermi level E_F = {EF:.4f} eV; band-path k-distance in {KLAB_TXT}; k, q along the chain in 1/Å.\n\n'
                '**Fig. 0.** Validation. **Fig. 1 / 1b.** Band structure + DOS, projected bands (as for 2D/3D).\n\n'
                '**Fig. 6 (6_1d_spectral_qpi).** (a) spectral function A(k,E); (b) JDOS(q,E); (c) T-matrix (Born) '
                'FT-LDOS |δρ(q,E)| of a point impurity; (d) DOS. Cyan: q = 2k backscattering (Friedel 2k_F).\n\n'
                '**Fig. 2 (2_bands3d_bz).** A(k,E) as a 3D surface.\n\n'
                '**Fig. 5 (5_band_edges).** Band edges with the effective-mass parabolas (semiconductors only).\n\n'
                '**Fig. 6c (6c_qpi_analysis).** At three energies: J(q) and |δρ(q)| profiles for 0 < q ≤ b/2 with the JDOS '
                'peaks, the real-space Friedel oscillation δρ(x) per unit cell around a point impurity, and the table of '
                'dominant scattering vectors (q, λ = 2π/q, k → k+q, bands).\n\n'
                '**Fig. 7 (7_qpi_dispersion).** (a) real-space QPI δρ(x,E); (b) |δρ(q,E)| for 0 < q ≤ b/2; (c) DOS.\n\n'
                '**Fig. 8 (overview).** Bands, DOS, A(k,E), T-matrix QPI.\n')
    finish_output(hp)


def qpi_energies_1d(G1):
    """three QPI energies as in 2D (CBM + 0.1, VBM - 0.1, CBM + 0.3 eV; metals E_F, E_F +- 0.3), each moved into
    the nearest band if it has no states (the 1D simplex DOS is exactly zero in a gap)"""
    if 'qpi_user_energies' in S:                 # --qpi=E1,E2,... given by the user: used as they are
        return [float(x) for x in S['qpi_user_energies'].split()][:3]
    g = float(S.get('overall_gap_eV', 0))
    if g > 0.02 and 'spin1_VBM_E_k' in S:
        vb = max(float(S[f'spin{s + 1}_VBM_E_k'].split()[0]) for s in SP if f'spin{s + 1}_VBM_E_k' in S)
        cb = min(float(S[f'spin{s + 1}_CBM_E_k'].split()[0]) for s in SP if f'spin{s + 1}_CBM_E_k' in S)
        es = [cb + 0.10, vb - 0.10, cb + 0.30]
    else:
        es = [0.0, 0.30, -0.30]
    Eall = G1['E'].ravel()
    out = []
    for e in es:
        if not has_states(G1, e):
            up = e >= 0
            cand = np.sort(Eall)
            # nearest band energy, away from E_F first, then 50 meV into the band
            above, below = cand[cand > e], cand[cand < e]
            da = above[0] - e if len(above) else 9e9; db = e - below[-1] if len(below) else 9e9
            e = (above[0] + 0.05) if (da <= db if up else da < db) else (below[-1] - 0.05)
        out.append(float(e))
    return out


def has_states(G1, e):
    """a band crosses energy e somewhere on the 1D grid (some band n has min_k E_n <= e <= max_k E_n)"""
    E = G1['E']
    return bool(((E.min(0) <= e) & (E.max(0) >= e)).any())


def extra_1d(G1, M, Eg, k, kc, order):
    """1D wires and tubes: QPI analysis (profiles, scattering-vector table, real-space Friedel oscillation),
    the real-space LDOS map around an impurity, the band edges with effective masses and a 3D view of A(k,E)"""
    from scipy.signal import find_peaks
    ECOL = OKABE[:3]
    b = G1['b']; N = G1['N']; a = 2 * np.pi / b
    E1 = G1['E']; ns = G1['ns']
    QE1 = qpi_energies_1d(G1)
    eta = M['eta']
    half = k <= b / 2 + 1e-12                                 # J(q) = J(b - q): show q in [0, b/2]
    R01 = 0.06 * b
    nx = int(min(N // 2 - 1, max(20, np.ceil(60.0 / a))))   # +- 60 Angstrom (at least 20 cells)
    xm = np.arange(-nx, nx + 1) * a

    def at_energy(e0):
        A = np.zeros(N); J = np.zeros(N); T = np.zeros(N); Rr = np.zeros(N); Au = np.zeros(N); Ad = np.zeros(N)
        Ab = np.zeros((N, E1.shape[2]))
        for s_ in range(ns):
            x = e0 - E1[:, s_, :]
            L = eta / np.pi / (x * x + eta * eta)
            As = L.sum(-1); Ab += L
            Gs = (1.0 / (x + 1j * eta)).sum(-1)
            A += As
            if s_ == 0:
                Au = As
            else:
                Ad = As
            Fa = np.fft.fft(As); J += np.real(np.fft.ifft(Fa * np.conj(Fa))) / N
            Fg = np.fft.fft(Gs); Fm = np.roll(Fg[::-1], 1)
            C = np.fft.ifft(Fg * Fm) / N; Cm = np.roll(C[::-1], 1)
            T += np.real(-(C - np.conj(Cm)) / (2j * np.pi))
            g = np.fft.ifft(Gs)
            Rr += -np.imag(g * np.roll(g[::-1], 1)) / np.pi
        T = np.abs(T)
        T = np.clip(T - gaussian_filter1d(T, 0.12 / (b / N), mode='wrap'), 0, None)
        out = dict(A=A, J=J, T=T, R=Rr, Ab=Ab)
        # spin-conserving (A_up*A_up + A_dn*A_dn) and spin-flip (A_up*A_dn + A_dn*A_up) JDOS for every system:
        # without spin polarisation each band holds both spins, A_up = A_dn = A_band (spin-flip share = 1/2 exactly)
        if ns == 1:
            Ad = Au
        xc = lambda u, v: np.real(np.fft.ifft(np.conj(np.fft.fft(u)) * np.fft.fft(v))) / N
        out['Jc'] = xc(Au, Au) + xc(Ad, Ad); out['Jf'] = xc(Au, Ad) + xc(Ad, Au)
        return out

    def peaks1d(sq, y, nmax=4):
        core = sq > 1.5 * R01
        if not core.any() or y[core].max() <= 0:
            return []
        yn = y / y[core].max()
        i0 = int(np.argmax(core))
        pk, _ = find_peaks(yn[i0:], prominence=0.06)
        pk = pk + i0
        o = np.argsort(-yn[pk])[:nmax]
        return [(int(pk[i]), float(sq[pk[i]]), float(yn[pk[i]])) for i in o]

    rows, RES = [], []
    sq = k[half]
    for ie, e0 in enumerate(QE1):
        r = at_energy(e0)
        RES.append(r)
        for qty, y in (('JDOS', r['J'][half]), ('T-matrix', r['T'][half])):
            for ip, qv, h in peaks1d(sq, y):
                m = int(round(qv / (b / N)))
                P = r['A'] * np.roll(r['A'], -m)
                i1 = int(np.argmax(P)); i2 = (i1 + m) % N
                n1 = int(np.argmax(r['Ab'][i1])) + 1; n2 = int(np.argmax(r['Ab'][i2])) + 1
                k1 = kc[i1]; k2 = kc[i2]
                cons = float(r['Jc'][m] / max(r['Jc'][m] + r['Jf'][m], 1e-30)) if 'Jc' in r else None
                rows.append(dict(ie=ie, E=e0, eta=eta, qty=qty, q=qv, lam=2 * np.pi / qv, I=h, k1=float(k1), k2=float(k2),
                                 n1=n1, n2=n2, cons=cons))
    blo = int(open(os.path.join(OUT, 'grid1d.dat')).readline().split()[6])
    with open(os.path.join(OUT, 'qpi_peaks.txt'), 'w') as f:
        f.write('# 1D: dominant scattering vectors along the wire (peaks of J(q) and |drho(q)| for 0 < q <= b/2;\n'
                '# J(q) = J(b - q)). I = height relative to the largest value beyond the forward-scattering region;\n'
                '# lambda = 2 pi/q; k1 -> k2 = k1 + q: the pair with the largest A(k)A(k+q), on bands n1 -> n2 (absolute\n'
                '# band index); spin_cons = (J_uu + J_dd)/J_total (spin-polarised runs)\n'
                '# E_eV  eta_eV  map  direction  |q|_1/Ang  qx  qy  lambda_Ang  I  k1x k1y  k2x k2y  spin_cons  n1 n2\n')
        for r in rows:
            f.write(f'{r["E"]:9.4f}{r["eta"]:8.4f}  {r["qty"]:<9s} {"wire":<4s}{r["q"]:9.4f}{r["q"]:9.4f}{0.0:9.4f}'
                    f'{r["lam"]:9.3f}{r["I"]:7.3f}{r["k1"]:9.4f}{0.0:9.4f}{r["k2"]:9.4f}{0.0:9.4f}'
                    f'{(r["cons"] if r["cons"] is not None else float("nan")):8.3f}{r["n1"] + blo - 1:5d}{r["n2"] + blo - 1:5d}\n')
    # real-space Friedel oscillation, every cell, for all map energies -> friedel_1d.dat (checked by the audit)
    Rx = np.concatenate([M['R'][:, -nx:], M['R'][:, :nx + 1]], axis=1)          # cells -nx..nx
    with open(os.path.join(OUT, 'friedel_1d.dat'), 'w') as f:
        f.write(f'# drho(x_m, E) per unit cell around a point impurity at x = 0 (Born, U = 1), eta {eta:.5f} eV, '
                f'a {a:.6f} Ang, nx {nx}\n# rows: E - E_F (eV), then drho at x = -nx*a .. +nx*a\n')
        for i in range(len(Eg)):
            f.write(f'{Eg[i]:10.5f}' + ''.join(f'{v:14.6e}' for v in Rx[i]) + '\n')
    # ---------------- figure 6c (1D)
    spin_on = 'Jc' in RES[0] and SPINFUL   # non-magnetic: J_uu+J_dd = J and the spin-flip share is 1/2, not shown
    style = dict(XG_RC, **{'font.size': 12, 'axes.labelsize': 13, 'axes.titlesize': 12.5, 'xtick.labelsize': 10.5,
                           'ytick.labelsize': 10.5, 'axes.linewidth': 1.6, 'legend.fontsize': 10})
    with mpl.rc_context(style):
        fig = plt.figure(figsize=(17.0, 3.9 * len(QE1) + 1.8), layout='constrained')
        gsx = fig.add_gridspec(len(QE1), 3, width_ratios=[1.25, 1.25, 1.15])
        for ie, e0 in enumerate(QE1):
            r = RES[ie]; let = iter('abcdefghijkl'[ie * 3:])
            ax = fig.add_subplot(gsx[ie, 0])
            core = sq > 1.5 * R01
            for qty, y, ls_ in (('JDOS', r['J'][half], '-'), ('T-matrix', r['T'][half], '--')):
                yn = y / max(y[core].max(), 1e-30)
                ax.plot(sq, yn, color='k' if qty == 'JDOS' else '#D55E00', ls=ls_, lw=1.9, label=qty)
            if spin_on:
                yc = r['Jc'][half] / max(r['J'][half][core].max(), 1e-30); yf = r['Jf'][half] / max(r['J'][half][core].max(), 1e-30)
                ax.plot(sq, yc, color='#0072B2', lw=1.2, label='↑↑+↓↓'); ax.plot(sq, yf, color='#009E73', lw=1.2, label='↑↓+↓↑')
            num = 0; tab = []
            for rr in [x for x in rows if x['ie'] == ie and x['qty'] == 'JDOS']:
                num += 1; tab.append((num, rr))
                ax.plot(rr['q'], rr['I'], 'o', ms=7, mfc='white', mec='k', mew=1.8, zorder=10)
                ax.annotate(str(num), (rr['q'], rr['I']), xytext=(0, 7), textcoords='offset points', ha='center',
                            fontsize=11, fontweight='bold')
            ax.axvspan(0, 1.5 * R01, color='0.88', lw=0)
            ax.set_xlim(0, b / 2); ax.set_ylim(0, 1.12)
            ax.set_xlabel(r'$q$ along the wire (Å$^{-1}$)'); ax.set_ylabel('intensity (normalised)')
            if ie == 0:
                ax.set_title('QPI line profile, 0 < q ≤ b/2')
                ax.legend(loc='upper right', frameon=True, edgecolor='k')
            ax.text(-0.17, 0.5, f'$E-E_F$ = {e0:+.2f} eV', transform=ax.transAxes, rotation=90, va='center', ha='center',
                    fontsize=15, fontweight='bold', color=ECOL[ie])
            ax.text(0.015, 0.97, f'({next(let)})', transform=ax.transAxes, fontsize=13, fontweight='bold', va='top')
            # real-space Friedel oscillation at this energy
            ax2 = fig.add_subplot(gsx[ie, 1])
            rr_ = np.concatenate([r['R'][-nx:], r['R'][:nx + 1]])
            sc = np.max(np.abs(rr_[np.abs(xm) > 0.5 * a])) if np.any(np.abs(xm) > 0.5 * a) else 1.0
            ax2.axhline(0, color='0.5', lw=0.8)
            ax2.plot(xm, rr_ / max(sc, 1e-30), '-', color='#0072B2', lw=1.2)
            ax2.plot(xm, rr_ / max(sc, 1e-30), 'o', ms=3.5, color='#0072B2')
            ax2.set_ylim(-1.15, 1.15); ax2.set_xlim(xm[0], xm[-1])
            ax2.set_xlabel(r'distance from the impurity $x$ (Å)'); ax2.set_ylabel(r'$\delta\rho(x)$ / max$_{x\neq0}$')
            ax2.text(0.98, 0.03, f'impurity at x = 0 (value {rr_[nx] / max(sc, 1e-30):+.1f}, clipped)' if abs(rr_[nx]) > 1.15 * sc
                     else 'impurity at x = 0', transform=ax2.transAxes, ha='right', va='bottom', fontsize=10)
            if ie == 0:
                ax2.set_title('Friedel oscillation: LDOS change per unit cell')
            ax2.text(0.015, 0.97, f'({next(let)})', transform=ax2.transAxes, fontsize=13, fontweight='bold', va='top')
            at = fig.add_subplot(gsx[ie, 2]); at.axis('off')
            lines = [f'{"#":>2s} {"q":>6s}{"λ":>7s}{"I":>5s}  {"k → k+q":<16s}{"bands":>8s}' + ('  ↑↑+↓↓' if spin_on else ''),
                     f'   {"1/Å":>6s}{"Å":>7s}']
            for n_, rr in tab[:8]:
                lines.append(f'{n_:>2d} {rr["q"]:6.3f}{rr["lam"]:7.2f}{rr["I"]:5.2f}  {rr["k1"]:+.2f}→{rr["k2"]:+.2f}'
                             f'{rr["n1"] + blo - 1:>5d}→{rr["n2"] + blo - 1:<4d}' + (f' {100 * rr["cons"]:4.0f}%' if rr['cons'] is not None else ''))
            if not tab:
                lines.append('no JDOS peak beyond q ≈ 0')
            at.text(0.0, 0.98, '\n'.join(lines), transform=at.transAxes, va='top', ha='left', family='DejaVu Sans Mono',
                    fontsize=9.6, fontweight='normal', linespacing=1.45)
            if ie == 0:
                at.set_title('dominant scattering vectors (JDOS peaks)')
        fig.suptitle(f'{LABEL}: 1D QPI Analysis — Line Profiles, Friedel Oscillations and Scattering Vectors',
                     fontsize=18, fontweight='bold')
        fig.text(0.5, -0.005, wrapc(
            f'Left: J(q) (solid) and T-matrix |δρ(q)| (dashed) along the wire for 0 < q ≤ b/2 (b = {b:.3f} 1/Å; J(q) = J(b − q)), '
            'normalised beyond the forward-scattering region (grey)' + ('; blue / green: spin-conserving / spin-flip JDOS' if spin_on else '') +
            '. Numbered: JDOS peaks. Middle: real-space LDOS change δρ(x) = −(1/π) Im[U g(x) g(−x)], g(x) = (1/N) Σ_k G(k) e^{ikx}, '
            f'one value per unit cell (a = {a:.3f} Å) around a point impurity at x = 0 (Born limit) — the Friedel oscillation an STM '
            'line scan sees. Right: |q|, wavelength λ = 2π/q, relative height I, the k-pair with the largest A(k)A(k+q) and its bands '
            '(absolute index). All peaks: qpi_peaks.txt; δρ(x, E): friedel_1d.dat. ' + subtitle(), 175),
            ha='center', va='top', fontsize=10, fontweight='normal')
        save(fig, '6c_qpi_analysis')
    # ---------------- figure 7 (1D): real-space QPI map and clean q-space map
    with mpl.rc_context(dict(XG_RC, **{'font.size': 13, 'axes.labelsize': 15, 'axes.titlesize': 14, 'xtick.labelsize': 12,
                                       'ytick.labelsize': 12, 'axes.linewidth': 1.8})):
        fig = plt.figure(figsize=(13.0, 10.4), layout='constrained')
        gs7 = fig.add_gridspec(1, 3, width_ratios=[1.3, 1.0, 0.55])
        a1 = fig.add_subplot(gs7[0]); a2 = fig.add_subplot(gs7[1], sharey=a1); a3 = fig.add_subplot(gs7[2], sharey=a1)
        Dr = M['A'].mean(1)
        wE = np.clip(Dr / max(0.15 * np.percentile(Dr, 75), 1e-300), 0, 1)[:, None]
        X = Rx.copy(); X[:, nx] = 0.0                                        # the impurity site itself is not shown
        X = X / np.maximum(np.abs(X).max(1, keepdims=True), 1e-300) * wE
        a1.imshow(X, extent=[xm[0], xm[-1], Eg[0], Eg[-1]], origin='lower', aspect='auto', cmap='RdBu_r', vmin=-1, vmax=1,
                  interpolation='nearest')
        a1.axhline(0, color='k', ls=(0, (6, 3)), lw=1.4); a1.axvline(0, color='k', lw=0.8)
        a1.set_xlabel(r'distance from the impurity $x$ (Å)'); a1.set_ylabel('Energy (eV)')
        a1.set_title(r'(a) real-space QPI $\delta\rho(x,E)$'); a1.set_ylim(Eg[0], Eg[-1])
        core = (k[half] > 1.5 * R01)
        Tq = M['T'][:, half]; Tq = rownorm(Tq, core) * wE
        a2.imshow(Tq, extent=[0, k[half][-1], Eg[0], Eg[-1]], origin='lower', aspect='auto', cmap=QCMAP, vmin=0, vmax=1,
                  interpolation='bilinear')
        for q_, e_ in G1M['guides']:
            mm = q_ <= b / 2
            a2.plot(np.where(mm, q_, np.nan), e_, color='c', lw=0.8, ls='--', alpha=0.8)
            a2.plot(np.where(~mm, b - q_, np.nan), e_, color='c', lw=0.8, ls='--', alpha=0.8)
        a2.axhline(0, color='r', ls=(0, (6, 3)), lw=1.4); a2.set_xlim(0, b / 2)
        a2.set_xlabel(r'$q$ (Å$^{-1}$)'); a2.set_title(r'(b) $|\delta\rho(q,E)|$, 0 < q ≤ b/2')
        plt.setp(a2.get_yticklabels(), visible=False)
        if CHS:
            draw_dos(a3, CHS[0][3][0], CHS[0][3][1], YW, +1, dos_xmax(CHS, YW))
        a3.set_title('(c) DOS'); plt.setp(a3.get_yticklabels(), visible=False); a3.set_ylim(Eg[0], Eg[-1])
        for e0, c_ in zip(QE1, ECOL):
            for a_ in (a1, a2, a3):
                a_.axhline(e0, color=c_, lw=1.2, ls=':')
        fig.suptitle(f'{LABEL}: Quasiparticle Interference along the Wire (real space and q space)', fontsize=18, fontweight='bold')
        fig.text(0.5, -0.005, wrapc(
            '(a) LDOS change per unit cell around a point impurity at x = 0 (Born limit), red / blue = more / fewer states; '
            'each energy normalised (impurity cell excluded) and faded where there are no states. (b) |δρ(q,E)| with the smooth '
            'background removed, each energy normalised; cyan: backscattering q = 2k of the bands nearest E_F. (c) DOS. '
            'Dotted: the three energies of figure 6c. ' + subtitle(), 160), ha='center', va='top', fontsize=10.5, fontweight='normal')
        save(fig, '7_qpi_dispersion')
    # ---------------- figure 5 (1D): band edges with effective masses
    g = float(S.get('overall_gap_eV', 0))
    if g > 0.02 and 'spin1_mass_holes' in S:
        with mpl.rc_context(XG_RC):
            fig, axs = plt.subplots(1, 2, figsize=(12.0, 6.6), layout='constrained')
            kk = kc[order]
            hb = 7.619964                       # hbar^2 / (2 m_e) in eV Angstrom^2 (= 3.80998 * 2)
            for j, (lab, key, mk) in enumerate((('valence-band maximum', 'VBM', 'holes'), ('conduction-band minimum', 'CBM', 'electrons'))):
                ax = axs[j]
                s0 = 0; best = None
                for s_ in SP:
                    kv = f'spin{s_ + 1}_{key}_E_k'
                    if kv in S:
                        e_ = float(S[kv].split()[0])
                        if best is None or (e_ > best[0] if key == 'VBM' else e_ < best[0]):
                            best = (e_, s_)
                e_edge, s0 = best
                Eb = E1[:, min(s0, ns - 1), :][order]
                win = 0.6
                for n in range(Eb.shape[1]):
                    y = Eb[:, n]
                    if (y > e_edge - win).any() and (y < e_edge + win).any():
                        ax.plot(kk, y, color='#0072B2' if key == 'VBM' else '#D55E00', lw=2.2)
                kx = float(S[f'spin{s0 + 1}_{key}_E_k'].split()[1])
                mstar = float(S[f'spin{s0 + 1}_mass_{mk}'].split()[0])
                if abs(mstar) > 1e-6:
                    dk = np.linspace(-0.25, 0.25, 101)
                    ax.plot(kx + dk, e_edge + hb / 2 / mstar * dk ** 2, 'k--', lw=1.6,
                            label=f'parabola, m* = {mstar:+.3f} m$_e$')
                ax.plot([kx], [e_edge], 'o', ms=9, mfc='white', mec='k', mew=2, zorder=10)
                ax.set_xlim(kk[0], kk[-1])
                ax.set_ylim((e_edge - win, e_edge + 0.15) if key == 'VBM' else (e_edge - 0.15, e_edge + win))
                ax.set_xlabel(r'$k$ along the wire (Å$^{-1}$)'); ax.set_ylabel(r'$E - E_F$ (eV)')
                ax.set_title(f'{lab}: {e_edge:+.3f} eV at k = {kx:+.3f} 1/Å', fontsize=15)
                ax.legend(loc='upper right' if key == 'CBM' else 'lower right', frameon=True, edgecolor='k', fontsize=13)
            fig.suptitle(f'{LABEL}: Band Edges and Effective Masses (1D)', fontsize=20, fontweight='bold')
            fig.text(0.5, -0.01, wrapc('Exact bands on the periodic 1D grid near the band edges; dashed: E = E_edge + ħ²(k − k_edge)²/2m* '
                     'with the effective mass from the engine (finite differences at the refined extremum). ' + subtitle(), 150),
                     ha='center', va='top', fontsize=11, fontweight='normal')
            save(fig, '5_band_edges')
    # ---------------- figure 2 (1D): 3D view of the spectral function
    # A(k,E) recomputed for display with a broadening that the surface sampling can resolve (>= 2 energy steps),
    # the exact bands drawn on the floor of the box
    with mpl.rc_context(dict(XG_RC, **{'font.size': 13, 'axes.labelsize': 16, 'xtick.labelsize': 13, 'ytick.labelsize': 13})):
        fig = plt.figure(figsize=(11.0, 9.6), layout='constrained')
        ax = fig.add_subplot()
        nk3 = min(N, 600); ik = np.linspace(0, N - 1, nk3).astype(int)
        kv = kc[order][ik]
        g0 = float(S.get('overall_gap_eV', 0))
        if g0 > 0.02 and 'spin1_VBM_E_k' in S:          # window: 1 eV below the VBM to 1 eV above the CBM
            vb_ = float(S['spin1_VBM_E_k'].split()[0]); cb_ = float(S['spin1_CBM_E_k'].split()[0])
            W3 = (max(YW[0], vb_ - 1.0), min(YW[1], cb_ + 1.0))
        else:
            W3 = (max(YW[0], -1.2), min(YW[1], 1.2))
        Ev = np.linspace(W3[0], W3[1], 600)
        etv = max(eta, 2.2 * (Ev[1] - Ev[0]))
        Esel = E1[order][ik]                                          # [k, spin, band]
        A3 = np.zeros((len(Ev), nk3))
        for s_ in range(ns):
            for n in range(Esel.shape[2]):
                y = Esel[:, s_, n]
                if y.max() < W3[0] - 0.3 or y.min() > W3[1] + 0.3:
                    continue
                A3 += etv / np.pi / ((Ev[:, None] - y[None, :]) ** 2 + etv ** 2)
        A3 = np.clip(A3 / max(np.percentile(A3, 99.7), 1e-12), 0, 1)
        # relief: A(k,E) as a height field lit from the upper left (each band a ridge), E vertical as in figure 1
        rgb = ls.shade(np.sqrt(A3), cmap=mpl.colormaps['magma'], blend_mode='soft', vert_exag=6.0,
                       dx=(kv[-1] - kv[0]) / nk3, dy=(Ev[-1] - Ev[0]) / len(Ev), vmin=0, vmax=1)
        ax.imshow(rgb, extent=[kv[0], kv[-1], Ev[0], Ev[-1]], origin='lower', aspect='auto', interpolation='bilinear')
        ax.axhline(0, color='w', ls=(0, (6, 3)), lw=1.6)
        ax.set_xlabel(r'$k$ along the wire (Å$^{-1}$)'); ax.set_ylabel(r'$E-E_F$ (eV)')
        ax.set_xlim(kv[0], kv[-1]); ax.set_ylim(Ev[0], Ev[-1])
        ax.set_title(f'{LABEL}: spectral function A(k, E), 3D relief', fontsize=19, fontweight='bold')
        fig.text(0.5, -0.01, wrapc(f'A(k,E) of the exact bands on the periodic 1D grid, Lorentzian {1000 * etv:.0f} meV (display), '
                 'shown as a lit height field (square-root scale): every band is a ridge, flat bands are bright plateaus, '
                 'the gap is the dark valley. ' + subtitle(), 140),
                 ha='center', va='top', fontsize=10.5, fontweight='normal')
        save(fig, '2_bands3d_bz')
    for r_ in rows:
        r_['n1'] += blo - 1; r_['n2'] += blo - 1
    globals()['QE1'] = QE1; globals()['QROWS1'] = rows; globals()['FRIEDEL1'] = (xm, Rx)


def html_context_1d():
    import io, base64
    from PIL import Image
    ctx = dict(label=LABEL, title=title_text().replace('μ$_B$', 'μB') + (f' ({GAPNOTE})' if GAPNOTE else ''), EF=EF,
               dim=DIM, planar=False, spins=SP, nspin=nspin, summary=S, bset=BSET, soc=SOC, sets=['index'],
               names={'index': ['VB', 'CB']}, nodes=[(float(x), nodelabel(l).replace('$', '').replace('\\Gamma', 'Γ'))
                                                      for x, l in NODES], codename='BandQPI-3D', version=VERSION,
               groups=GRP, gcol=GCOL, vhs=[], grids={}, pub=pub_context())

    def webp(img, cmap, w=401, nearest=False):
        rgb = (mpl.colormaps[cmap](np.clip(np.nan_to_num(img), 0, 1))[..., :3] * 255).astype(np.uint8)[::-1]
        im = Image.fromarray(rgb).resize((w, rgb.shape[0]), Image.NEAREST if nearest else Image.LANCZOS)
        bio = io.BytesIO(); im.save(bio, 'WEBP', quality=92, method=6)
        return base64.b64encode(bio.getvalue()).decode('ascii')
    M = globals()['G1M']
    ctx['q1d'] = dict(E=[float(M['E'][0]), float(M['E'][-1])], k=[float(M['k'][0]), float(M['k'][-1])],
                      q=[0.0, float(M['b'])], A=webp(M['A'], 'bone_r'), J=webp(M['J'], QCMAP),
                      T=webp(M['T'], QCMAP), eta=M['eta'],
                      guides=[[np.round(q[::max(1, len(q) // 300)], 4).tolist(), np.round(e[::max(1, len(e) // 300)], 4).tolist()]
                              for q, e in M['guides']])
    if 'FRIEDEL1' in globals():
        xm_, Rx_ = FRIEDEL1
        X = np.array(Rx_, float); X[:, len(xm_) // 2] = 0.0
        Dr = M['Araw'].mean(1); wE = np.clip(Dr / max(0.15 * np.percentile(Dr, 75), 1e-300), 0, 1)[:, None]
        X = X / np.maximum(np.abs(X).max(1, keepdims=True), 1e-300) * wE
        ctx['q1d']['R'] = webp(0.5 + 0.5 * X, 'RdBu_r', w=len(xm_) * max(1, 401 // len(xm_)), nearest=True)
        ctx['q1d']['x'] = [float(xm_[0]), float(xm_[-1])]
        ctx['q1d']['peaks'] = [dict(E=round(r['E'], 4), q=round(r['q'], 4), lam=round(r['lam'], 3), I=round(r['I'], 3),
                                    k1=round(r['k1'], 3), k2=round(r['k2'], 3), n=f'{r["n1"]}→{r["n2"]}', qty=r['qty'],
                                    cons=None if r['cons'] is None else round(r['cons'], 3)) for r in QROWS1]
    return ctx


def write_axrec():
    import json as _j
    AXREC['units_factor_to_bohr'] = BOHR / KS
    AXREC['gap_arrows'] = GAPREC
    with open(os.path.join(OUT, 'figure_axes.json'), 'w') as _f:
        _j.dump(AXREC, _f, indent=1)


