def side_envelope(K, Z, nb):
    """exact orthographic side view of a surface E(kx, ky) seen along the other axis: for each bin of the
    viewing coordinate K, the lowest and highest energy of all grid points in it (no interpolation)"""
    K, Z = K.ravel(), Z.ravel(); ok = np.isfinite(Z); K, Z = K[ok], Z[ok]
    e = np.linspace(K.min(), K.max(), nb + 1); ib = np.clip(np.digitize(K, e) - 1, 0, nb - 1)
    lo = np.full(nb, np.nan); hi = np.full(nb, np.nan)
    np.fmin.at(lo, ib, Z); np.fmax.at(hi, ib, Z)
    c = 0.5 * (e[1:] + e[:-1]); m = np.isfinite(lo)
    return c[m], lo[m], hi[m]


def side_panel(a, K, s, xlab):
    """band index VB (blue) / CB (red): shaded band between the envelopes, colour = energy, as in VASPKIT"""
    from matplotlib.patches import Polygon
    nb = max(40, int(K.shape[1] if K.ndim == 2 else 80))
    allz = []
    for rel, kind in ((0, 'v'), (1, 'c')):
        Z = EXT.band(s, rel, 'index')
        if Z is None:
            continue
        x, lo, hi = side_envelope(K, Z, nb)
        cmo = cmap_part(CM[(s, kind)], 0.25, 1.0)
        grad = np.linspace(0, 1, 256)[:, None]
        im = a.imshow(grad if kind == 'c' else grad, extent=[x[0], x[-1], lo.min(), hi.max()], origin='lower',
                      aspect='auto', cmap=cmo, interpolation='bilinear', zorder=2)
        poly = Polygon(np.c_[np.r_[x, x[::-1]], np.r_[lo, hi[::-1]]], closed=True, transform=a.transData)
        im.set_clip_path(poly)
        a.plot(x, hi, color=LC[s][0 if kind == 'v' else 1], lw=1.3, zorder=3)
        a.plot(x, lo, color=LC[s][0 if kind == 'v' else 1], lw=1.3, zorder=3)
        allz += [lo.min(), hi.max()]
    if allz:
        z0, z1 = min(allz), max(allz); pd = 0.06 * (z1 - z0 + 1e-9)
        a.set_ylim(z0 - pd, z1 + pd)
    a.axhline(0.0, color='0.45', lw=0.9, ls='--', zorder=1)
    a.set_xlim(np.nanmin(K), np.nanmax(K))
    a.set_xlabel(xlab); a.set_ylabel(r'$E-E_F$ (eV)')


