def per_interp(F, X, Y):
    n = F.shape[0]
    u, v = np.einsum('ij,j...->i...', Binv, np.array([X, Y])) * n
    i0, j0 = np.floor(u).astype(int), np.floor(v).astype(int)
    fu, fv = u - i0, v - j0
    gg = lambda di, dj: F[(i0 + di) % n, (j0 + dj) % n]
    return (1 - fu) * (1 - fv) * gg(0, 0) + fu * (1 - fv) * gg(1, 0) + (1 - fu) * fv * gg(0, 1) + fu * fv * gg(1, 1)


def window(fac):
    hx, hy = fac * np.abs(V[:, 0]).max(), fac * np.abs(V[:, 1]).max()
    m = max(hx, hy)
    return max(hx, m / 1.25), max(hy, m / 1.25)          # near-square windows (shows neighbouring zones)


