def bragg(ax, Lx, Ly, color='w'):
    n = int(np.ceil(3 * max(Lx, Ly) / min(np.linalg.norm(Bm[0]), np.linalg.norm(Bm[1])))) + 1
    for n1 in range(-n, n + 1):
        for n2 in range(-n, n + 1):
            G = n1 * Bm[0] + n2 * Bm[1]
            if abs(G[0]) < Lx and abs(G[1]) < Ly and (n1 or n2):
                ax.plot(G[0], G[1], '+', color=color, ms=6, mew=0.9, alpha=0.8, zorder=20)


def tile_segments(P1, P2, Lx, Ly):
    nb = [int(np.ceil(2.2 * max(Lx, Ly) / np.linalg.norm(b))) + 1 for b in Bm]
    lines, idx = [], []
    for n1 in range(-nb[0], nb[0] + 1):
        for n2 in range(-nb[1], nb[1] + 1):
            G = n1 * Bm[0] + n2 * Bm[1]
            M = 0.5 * (P1 + P2) + G
            ok = (np.abs(M[:, 0]) < 1.05 * Lx) & (np.abs(M[:, 1]) < 1.05 * Ly)
            if ok.any():
                lines.extend(np.stack([P1[ok] + G, P2[ok] + G], 1)); idx.extend(np.where(ok)[0])
    return lines, np.array(idx, int)


