def spaced_arrows(mid, sxy, dmin):
    """greedy subset of contour points at least dmin apart: one arrow per place, so the arrows of two
    nearly overlapping contours (e.g. a Rashba pair) alternate instead of lying on top of each other"""
    keep = []
    for i in range(len(mid)):
        if all((mid[i, 0] - mid[k, 0]) ** 2 + (mid[i, 1] - mid[k, 1]) ** 2 >= dmin * dmin for k in keep):
            keep.append(i)
    return mid[keep], sxy[keep]


def spin_data(ie):
    """contour segments (tiled into the window), sigma_z and spaced in-plane arrows at QPI energy ie (1-based)"""
    sg = SPT[SPT[:, 0] == ie]
    if not len(sg):
        return None
    segs, idx = tile_segments(sg[:, 1:3], sg[:, 3:5], Lx, Ly)
    segs = np.array(segs)
    m0 = (np.abs(segs[:, :, 0]).max(1) < Lx) & (np.abs(segs[:, :, 1]).max(1) < Ly)
    ext = np.abs(segs[m0]).reshape(-1, 2).max(0) if m0.any() else np.array([Lx, Ly])
    zx, zy = Lx, Ly
    if ext[0] < 0.45 * Lx and ext[1] < 0.45 * Ly:            # small pockets: zoom on them
        zx = 1.6 * max(ext[0], ext[1] * Lx / Ly); zy = zx * Ly / Lx
    mid = 0.5 * (segs[:, 0] + segs[:, 1]); sxy = sg[idx, 5:7]; sz = sg[idx, 7]
    inw = (np.abs(mid[:, 0]) < zx) & (np.abs(mid[:, 1]) < zy)
    am, asx = spaced_arrows(mid[inw], sxy[inw], 0.075 * zx)
    return dict(segs=segs, sz=sz, zx=zx, zy=zy, am=am, asx=asx, E=QE[ie - 1])


