VHC = '#FFC400'                                   # van Hove (saddle point) marker colour
with mpl.rc_context(XG_RC):
    fig = plt.figure(figsize=(12.6, 12.0), layout='constrained')
    gs = fig.add_gridspec(2, 1, height_ratios=[1, 1.05])
    gtop = gs[0].subgridspec(1, 2, width_ratios=[1, 1.05])
    gbot = gs[1].subgridspec(1, 2, width_ratios=[2.0, 1])
    # (a) exact constant-energy contours of VB and CB, one diverging energy scale
    a = fig.add_subplot(gtop[0])
