    lo_e = np.floor((np.nanmax(Zv) - 1.2) * 10) / 10 if Zv is not None else -1.5
    hi_e = np.ceil((np.nanmin(Zc) + 1.2) * 10) / 10 if Zc is not None else 1.5
    # colour scale: VB dark -> medium blue (deep -> band top), gap grey, CB medium -> dark red
    vtop = float(np.nanmax(Zv)) if Zv is not None else 0.0
    cbot = float(np.nanmin(Zc)) if Zc is not None else 0.0
    if Zc is None and Zv is not None:
        cbot = vtop; hi_e = vtop + 1.5
    if Zv is None and Zc is not None:
        vtop = cbot; lo_e = cbot - 1.5
    vmin8, vmax8 = min(lo_e, vtop - 0.2), max(hi_e, cbot + 0.2)
    nrm8 = Normalize(vmin8, vmax8)
    pv, pc = nrm8(min(vtop, cbot)), nrm8(max(vtop, cbot))
    B_, R_ = mpl.colormaps['Blues'], mpl.colormaps['Reds']
    stops = [(0.0, B_(1.0)), (max(pv - 1e-3, 1e-3), B_(0.45)), (min(max(pv, 2e-3), 0.998), '#bbbbbb'),
             (max(min(pc, 0.998), min(max(pv, 2e-3), 0.998) + 1e-4), '#bbbbbb'), (min(pc + 1e-3, 0.999), R_(0.45)), (1.0, R_(1.0))]
    stops = sorted(stops, key=lambda t: t[0])
    cm8 = LinearSegmentedColormap.from_list('vbcb', stops)
    steps8 = []
    for Z, sty in ((Zv, (0, (4, 2))), (Zc, 'solid')):
        if Z is None:
            continue
        zlo, zhi = max(np.nanmin(Z), nrm8.vmin), min(np.nanmax(Z), nrm8.vmax)
        raw = max((zhi - zlo) / 8, 1e-3)
        mag = 10 ** np.floor(np.log10(raw))
        dz = mag * min([f for f in (1, 2, 2.5, 5, 10) if f * mag >= raw])
        steps8.append(dz)
        lv = np.arange(np.ceil(zlo / dz) * dz, zhi + 1e-9, dz)
        if len(lv) >= 1:
            a.contour(EXT.kx, EXT.ky, Z, levels=lv, cmap=cm8, norm=nrm8, linewidths=1.4, linestyles=[sty])
    if steps8:
        a.text(0.97, 0.03, 'steps: ' + ' / '.join(f'{1000 * d:g} meV' for d in steps8) + ' (VB / CB)',
               transform=a.transAxes, ha='right', va='bottom', fontsize=11,
               bbox=dict(boxstyle='round,pad=0.2', fc='white', ec='k', lw=0.8, alpha=0.9), zorder=50)
    a.plot(vv[:, 0], vv[:, 1], 'k-', lw=2.6)
    for x_, y_, l_ in HSP:
        a.plot(x_, y_, 'o', ms=7, color='k', zorder=30)
        a.annotate(l_, (x_, y_), xytext=(7, 5), textcoords='offset points', fontsize=18, fontweight='bold',
                   zorder=31, bbox=dict(boxstyle='round,pad=0.1', fc='white', ec='none', alpha=0.8))
    for e, b, pts in VHSF:                          # every equivalent copy (k + G) inside the window
        for x_, y_ in pts:
            for n1 in range(-2, 3):
                for n2 in range(-2, 3):
                    g_ = n1 * Bm[0] + n2 * Bm[1]
                    X_, Y_ = x_ + g_[0], y_ + g_[1]
                    if abs(X_) <= Lx and abs(Y_) <= Ly and EXT.kx.min() <= X_ <= EXT.kx.max() and \
                            EXT.ky.min() <= Y_ <= EXT.ky.max():
                        a.plot(x_ + g_[0], y_ + g_[1], 'D', ms=9, mfc=VHC, mec='k', mew=1.2, zorder=40)
    a.set_aspect('equal'); a.set_xlim(-Lx, Lx); a.set_ylim(-Ly, Ly)
    a.set_xlabel(r'$k_x$ (Å$^{-1}$)'); a.set_ylabel(r'$k_y$ (Å$^{-1}$)')
    a.xaxis.set_major_locator(MaxNLocator(5, steps=[1, 2, 2.5, 5, 10]))
    a.yaxis.set_major_locator(MaxNLocator(5, steps=[1, 2, 2.5, 5, 10]))
    cb = fig.colorbar(mpl.cm.ScalarMappable(nrm8, cm8), ax=a, location='right', shrink=0.82, pad=0.02, aspect=24)
    cb.set_label('Energy (eV):  VB blue (dashed), CB red', fontsize=14)
